var e={"nav.overview":`Επισκόπηση`,"nav.collector":`Συλλέκτης συνδέσμων`,"nav.downloads":`Λήψεις`,"nav.instances":`Στιγμιότυπα`,"nav.accounts":`Λογαριασμοί`,"settings.accounts.setupTitle":`Πλαϊνή γραμμή`,"settings.accounts.showInSidebar":`Εμφάνιση και στην πλαϊνή γραμμή`,"settings.accounts.showInSidebarHint":`Αυτή η καρτέλα και ο προορισμός Λογαριασμοί στην πλαϊνή γραμμή δείχνουν την ίδια σελίδα - απενεργοποιήστε το αν τα δύο μαζί σας φαίνονται περιττά αντί για βολικά.`,"settings.instances.showInSidebarHint":`Αυτή η καρτέλα και η καταχώριση Στιγμιότυπα στην πλαϊνή μπάρα δείχνουν την ίδια σελίδα. Απενεργοποίησέ το αν και τα δύο μοιάζουν περιττά, ή αν έχεις μόνο ένα στιγμιότυπο.`,"settings.instances.showInSidebar":`Εμφάνιση και στην πλαϊνή γραμμή`,"settings.instances.setupTitle":`Πλαϊνή γραμμή`,"settings.nav.instances":`Στιγμιότυπα`,"nav.settings":`Ρυθμίσεις`,"nav.workingTitle":`προσωρινός τίτλος`,"theme.dark":`Σκούρο`,"theme.light":`Ανοιχτό`,"theme.toggle":`Εναλλαγή θέματος`,"lang.label":`Γλώσσα`,"lang.open":`Αλλαγή γλώσσας`,"lang.close":`Κλείσιμο επιλογέα γλώσσας`,"status.collected":`Συλλεγμένο`,"status.queued":`Σε αναμονή`,"status.running":`Σε εξέλιξη`,"status.paused":`Σε παύση`,"status.extracting":`Αποσυμπίεση`,"status.done":`Ολοκληρώθηκε`,"status.error":`Σφάλμα`,"task.pause":`Παύση`,"task.resume":`Συνέχιση`,"task.start":`Έναρξη`,"task.restart":`Επανεκκίνηση`,"task.remove":`Αφαίρεση`,"task.left":`απομένουν`,"task.file":`αρχείο`,"task.files":`αρχεία`,"task.ungrouped":`Χωρίς ομάδα`,"task.reason.gone":`Δεν υπάρχει πια`,"task.reason.auth":`Απαιτείται σύνδεση`,"task.reason.limit":`Όριο του hoster`,"task.reason.unavailable":`Ο hoster δεν απαντά`,"task.reason.network":`Δίκτυο`,"task.reason.diskFull":`Γεμάτος δίσκος`,"task.reason.unsupported":`Χωρίς μηχανή`,"task.reason.captcha":`Captcha`,"task.reason.cancelled":`Ακυρώθηκε`,"task.reason.unknown":`Χωρίς κατηγορία`,"overview.title":`Επισκόπηση`,"overview.totalSpeed":`Συνολική ταχύτητα λήψης`,"overview.active":`Ενεργά`,"overview.queued":`Σε αναμονή`,"overview.inCollector":`Στον συλλέκτη`,"overview.done":`Ολοκληρωμένα`,"overview.errors":`Σφάλματα`,"overview.recent":`Πρόσφατα`,"overview.noDownloads":`Δεν υπάρχουν λήψεις ακόμη.`,"overview.instances":`Στιγμιότυπα`,"overview.idle":`αδρανές`,"common.loading":`Φόρτωση…`,"common.loadFailed":`Δεν ήταν δυνατή η φόρτωση. Είναι προσβάσιμος ο διακομιστής;`,"common.retry":`Δοκιμάστε ξανά`,"hint.collector.title":`Οι σύνδεσμοι προετοιμάζονται εδώ, δεν έχουν κατέβει ακόμη`,"hint.collector.body":`Ό,τι προσθέτεις καταλήγει πρώτα σε αυτόν τον συλλέκτη, όπου μπορείς να ελέγξεις ονόματα και μεγέθη πριν ξεκινήσει οτιδήποτε. Ξεκίνησέ το από εδώ, ή ενεργοποίησε την αυτόματη έναρξη στις ρυθμίσεις αν δεν θέλεις ποτέ αυτή την παύση.`,"hint.downloads.title":`Τι εκτελείται πραγματικά`,"hint.downloads.body":`Αυτή είναι η ουρά μεταφοράς - σύνδεσμοι που έχεις ξεκινήσει, είτε εκτελούνται είτε περιμένουν τη σειρά τους είτε έχουν ήδη ολοκληρωθεί. Ό,τι έχεις απλώς προετοιμάσει στον συλλέκτη δεν εμφανίζεται ακόμη εδώ.`,"empty.downloadsTitle":`Δεν κατεβαίνει τίποτα ακόμη`,"empty.downloadsHint":`Προσθέστε συνδέσμους στον συλλέκτη και μετά ξεκινήστε τους.`,"collector.title":`Συλλέκτης`,"collector.listTitle":`Λίστα συνδέσμων`,"collector.placeholder":`Επικολλήστε συνδέσμους - έναν ανά γραμμή - ή αφήστε τους εδώ…  (Ctrl+Enter για προσθήκη)`,"collector.package":`Πακέτο (προαιρετικό)`,"collector.add":`Προσθήκη στον συλλέκτη`,"collector.addTitle":`Συλλέκτης συνδέσμων`,"collector.empty":`Ο συλλέκτης είναι άδειος. Επικολλήστε συνδέσμους παραπάνω για να ετοιμαστούν.`,"collector.startSelected":`Έναρξη επιλεγμένων`,"collector.startAll":`Έναρξη όλων`,"collector.toastStaged":`Ετοιμάστηκαν {n} σύνδεσμοι`,"collector.toastSkipped":`Ετοιμάστηκαν {n} σύνδεσμοι, {skipped} ήταν ήδη γνωστοί`,"collector.toastNone":`Δεν βρέθηκαν έγκυροι σύνδεσμοι`,"collector.toastStarted":`Ξεκίνησαν {n} λήψεις`,"collector.toastStartSkipped":`Το φίλτρο συνδέσμων κράτησε πίσω {n} συνδέσμους.`,"collector.toastStartDisabled":`{n} σύνδεσμοι είναι απενεργοποιημένοι και δεν ξεκίνησαν.`,"collector.toastStartedSomeDisabled":`{n} ξεκίνησαν, {disabled} απενεργοποιημένα.`,"collector.toastStartBlocked":`Η ουρά είναι σε παύση λόγω χρονοδιαγράμματος.`,"collector.selectAll":`Επιλογή όλων`,"collector.movePrompt":`Σε ποιο πακέτο να μετακινηθούν οι επιλεγμένοι σύνδεσμοι;`,"downloads.title":`Λήψεις`,"downloads.listTitle":`Λίστα λήψεων`,"downloads.thisInstance":`Αυτό το στιγμιότυπο`,"downloads.pauseAll":`Παύση όλων`,"downloads.resumeAll":`Συνέχιση όλων`,"downloads.retryFailed":`Επανάληψη αποτυχημένων`,"downloads.retryCause":`Δοκιμή ξανά για τις {n} με αυτή την αιτία: {reason}`,"downloads.clearFinished":`Καθαρισμός ολοκληρωμένων`,"downloads.noMatch":`Τίποτα δεν ταιριάζει με το φίλτρο.`,"downloads.finished":`Το {name} ολοκληρώθηκε`,"downloads.failed":`Το {name} απέτυχε`,"instances.title":`Στιγμιότυπα`,"instances.thisInstance":`Αυτό το στιγμιότυπο`,"instances.foundTitle":`Βρέθηκαν στο δίκτυό σας`,"instances.foundHint":`Στιγμιότυπα KnightLoader που ανακοινώνουν την παρουσία τους σε αυτό το δίκτυο. Τίποτα δεν συνδέεται μέχρι να προσθέσετε κάποιο, και η προσθήκη απλώς αποθηκεύει τη διεύθυνση - το να βρίσκεστε στο ίδιο δίκτυο δεν είναι άδεια. Ένα στιγμιότυπο με ορισμένο κωδικό πρόσβασης χρειάζεται επιπλέον κωδικό σύζευξης πριν δεχτεί οτιδήποτε.`,"instances.foundAdd":`Προσθήκη`,"instances.foundKnown":`ήδη προστέθηκε`,"instances.connectButton":`Σύνδεση στιγμιότυπου`,"instances.connectHint":`Προσθέστε ή συζεύξτε άλλο στιγμιότυπο KnightLoader από τις Ρυθμίσεις → Πρόσβαση.`,"instances.offlineWarning":`Προστέθηκε, αλλά το στιγμιότυπο δεν απάντησε (εκτός σύνδεσης;).`,"instances.open":`Άνοιγμα`,"instances.online":`Σε σύνδεση`,"instances.refused":`Προστέθηκε, αλλά εκείνη η παρουσία απέρριψε αυτήν - έχει κωδικό. Δώσε και στις δύο την ίδια φράση σύνδεσης στις Ρυθμίσεις → Πρόσβαση και θα εμπιστεύονται η μία την άλλη.`,"instances.offline":`Εκτός σύνδεσης`,"instances.viaRelay":`Συνδέθηκε μέσω αναμεταδότη`,"instances.metricActive":`Ενεργά`,"instances.metricTasks":`Εργασίες`,"instances.metricSpeed":`Ταχύτητα`,"instances.removeTitle":`Αφαίρεση {name}`,"accounts.title":`Λογαριασμοί`,"accounts.connected":`Συνδεδεμένο`,"accounts.saved":`Αποθηκεύτηκε.`,"accounts.keyLabel":`Κλειδί API για {service}`,"accounts.keyHint":`Ισχύει αμέσως· αποθηκεύεται κρυπτογραφημένο σε αυτό το στιγμιότυπο.`,"accounts.placeholder":`Επικολλήστε το κλειδί σας…`,"settings.title":`Ρυθμίσεις`,"settings.maxConcurrent":`Ταυτόχρονες λήψεις`,"settings.maxConcurrentHint":`Πόσες λήψεις τρέχουν ταυτόχρονα. Οι υπόλοιπες περιμένουν τη σειρά τους.`,"settings.maxPerHost":`Ταυτόχρονες λήψεις ανά πάροχο`,"settings.maxPerHostHint":`Το ανώτατο όριο για έναν πάροχο, πέρα από το σύνολο παραπάνω. Οι περισσότεροι επιτρέπουν ελάχιστες ταυτόχρονα.`,"settings.speedLimit":`Όριο ταχύτητας (KiB/s, 0 = ∞)`,"settings.speedHint":`Συνολικό όριο για όλες τις λήψεις, ισχύει και εν ώρα λειτουργίας.`,"settings.extract":`Αποσυμπίεση αρχείων μετά τη λήψη`,"settings.autoStart":`Άμεση έναρξη των συνδέσμων που προστίθενται (παράκαμψη συλλέκτη)`,"settings.save":`Αποθήκευση`,"settings.saved":`Αποθηκεύτηκε.`,"settings.downloadDir":`Φάκελος λήψεων`,"settings.downloadDirHint":`Απόλυτη διαδρομή. Αφήστε το κενό για τον ενσωματωμένο φάκελο.`,"settings.subfolderByPackage":`Κάθε πακέτο σε δικό του υποφάκελο`,"settings.maxRetries":`Αυτόματες επαναλήψεις`,"settings.resumeOnStart":`Μετά από επανεκκίνηση`,"settings.resumeOnStartHint":`Μια μεταφορά που ξεκινά ξανά αρχίζει από την αρχή, και το ήδη υπάρχον μερικό αρχείο συναντά τον κανόνα σύγκρουσης. Γι’ αυτό η προσεκτική ρύθμιση είναι η προεπιλογή.`,"settings.resume.never":`Τίποτα`,"settings.resume.running":`Ό,τι εκτελούνταν`,"settings.resume.all":`Ό,τι δεν ολοκληρώθηκε`,"settings.keepFinishedDays":`Διατήρηση ολοκληρωμένων (ημέρες)`,"settings.keepFinishedDaysHint":`Το 0 τα κρατά στη λίστα για πάντα. Το αρχείο στον δίσκο δεν αγγίζεται και το ιστορικό κρατά την εγγραφή.`,"settings.historyMax":`Εγγραφές ιστορικού`,"settings.historyMaxHint":`Το 0 κρατά κάθε εγγραφή.`,"settings.maxRetriesHint":`Μια αποτυχημένη λήψη επαναλαμβάνεται με αυξανόμενη καθυστέρηση.`,"settings.archivePasswords":`Κωδικοί αρχείων`,"settings.archives.extractionTitle":`Αποσυμπίεση`,"settings.archivePasswordsHint":`Ένας ανά γραμμή. Δοκιμάζονται με τη σειρά όταν ένα αρχείο είναι κρυπτογραφημένο.`,"settings.lockOn":`Έχει οριστεί κωδικός.`,"settings.lockOff":`Δεν έχει οριστεί κωδικός πρόσβασης.`,"settings.lockHint":`Προστατεύει αυτό το στιγμιότυπο από οποιονδήποτε μπορεί να το προσεγγίσει – στο ίδιο δίκτυο, μέσω domain ή μέσω relay. Μόλις οριστεί, πρέπει να εισαχθεί προτού ανοίξει καν αυτό το στιγμιότυπο – για οποιονδήποτε, ακόμη και για εσάς την επόμενη φορά. Χωρίς κωδικό, όποιος βρει τη διεύθυνση μπορεί να δει κάθε λήψη και να προσθέσει, να θέσει σε παύση ή να διαγράψει δικές του.`,"settings.passwordCurrent":`Τρέχων κωδικός`,"settings.passwordNew":`Νέος κωδικός`,"settings.passwordHint":`Τουλάχιστον 8 χαρακτήρες. Αφήστε το κενό για να αφαιρέσετε το κλείδωμα.`,"settings.setPassword":`Ορισμός κωδικού`,"settings.passwordSaved":`Ο κωδικός ενημερώθηκε.`,"auth.title":`Αυτό το στιγμιότυπο είναι κλειδωμένο`,"auth.subtitle":`Εισαγάγετε τον κωδικό για να συνεχίσετε.`,"auth.password":`Κωδικός`,"auth.signIn":`Σύνδεση`,"auth.signOut":`Αποσύνδεση`,"auth.wrong":`Λάθος κωδικός.`,"accounts.ok":`Λειτουργεί`,"accounts.failed":`Δεν λειτουργεί`,"accounts.unchecked":`Δεν ελέγχθηκε`,"accounts.hosts":`υποστηριζόμενοι πάροχοι`,"task.recheck":`Νέος έλεγχος`,"task.online":`Διαθέσιμο`,"task.offline":`Μη διαθέσιμο`,"task.retryPending":`Θα επαναληφθεί αυτόματα`,"task.folder":`Φάκελος`,"task.password":`Κωδικός αρχείου`,"task.priorityUp":`Αύξηση προτεραιότητας`,"task.priorityDown":`Μείωση προτεραιότητας`,"task.moveTop":`Μετακίνηση στην κορυφή`,"task.moveBottom":`Μετακίνηση στο τέλος`,"task.removeWithFiles":`Αφαίρεση και διαγραφή αρχείων`,"task.applied":`Εφαρμόστηκε.`,"select.all":`Επιλογή όλων`,"select.none":`Καθαρισμός επιλογής`,"select.count":`επιλεγμένα`,"settings.removePassword":`Αφαίρεση κωδικού`,"common.cancel":`Άκυρο`,"pkg.moveTitle":`Μετακίνηση σε πακέτο`,"pkg.name":`Όνομα πακέτου`,"pkg.merge":`Συγχώνευση σε ένα πακέτο`,"pkg.splitByHost":`Διαχωρισμός ανά πάροχο`,"settings.pathVars":`Μεταβλητές: <jd:packagename>, <jd:hoster>, <jd:filename>, <jd:date>`,"settings.watchDir":`Παρακολουθούμενος φάκελος`,"settings.watchDirHint":`Σύνδεσμοι που αφήνονται εδώ ως .txt ή .crawljob λαμβάνονται αυτόματα.`,"settings.crawl":`Άνοιγμα σελίδων και συλλογή των αρχείων στα οποία παραπέμπουν`,"settings.crawl.title":`Σάρωση σελίδων`,"settings.crawl.depth":`Βάθος σάρωσης`,"settings.crawl.depthHint":`Πόσο βαθιά θα πάει. Το 1 είναι μόνο η σελίδα που επικολλήσατε, το 2 ανοίγει και τις σελίδες που συνδέει, το 3 τις δικές τους. Μια σελίδα δεν ανοίγει ποτέ δύο φορές, οπότε αμοιβαίοι σύνδεσμοι τερματίζουν τη σάρωση αντί να την κάνουν κύκλους.`,"settings.crawl.maxPages":`Όριο σελίδων`,"settings.crawl.maxPagesHint":`Πόσες σελίδες μπορεί να ανοίξει το πολύ μία σάρωση. Μετρά τις σελίδες που ζητήθηκαν, όχι τους συνδέσμους που βρέθηκαν. Στο βάθος 1 υπάρχει μία μόνο σελίδα, οπότε δεν κάνει τίποτα.`,"settings.crawl.sameHost":`Παραμονή στον ίδιο κόμβο`,"settings.crawl.sameHostHint":`Ακολούθησε μόνο σελίδες του κόμβου που επικόλλησες. Ο κόμβος συγκρίνεται ακριβώς, οπότε ένας υποτομέας μετρά ως αλλού. Τα αρχεία δεν περιορίζονται ποτέ έτσι, γιατί οι λήψεις βρίσκονται συχνά σε ξεχωριστό διακομιστή.`,"settings.crawl.include":`Μόνο αυτοί οι σύνδεσμοι`,"settings.crawl.includeHint":`Μία κανονική έκφραση ανά γραμμή, συγκρίνεται με ολόκληρη τη διεύθυνση. Ένας σύνδεσμος πρέπει να ταιριάζει σε μία από αυτές για να συλλεχθεί. Οι σελίδες δεν φιλτράρονται, οπότε αυτό δεν εμποδίζει ποτέ τη σάρωση να πάει βαθύτερα.`,"settings.crawl.exclude":`Ποτέ αυτοί οι σύνδεσμοι`,"settings.crawl.excludeHint":`Μία κανονική έκφραση ανά γραμμή, συγκρίνεται με ολόκληρη τη διεύθυνση. Ό,τι ταιριάζει παραλείπεται, μαζί με τις σελίδες, οπότε μια αποκλεισμένη διεύθυνση δεν ανοίγει ποτέ.`,"task.checksumOk":`Το άθροισμα ελέγχου επαληθεύτηκε`,"task.checksumFail":`Το άθροισμα ελέγχου δεν ταιριάζει`,"settings.verifyChecksums":`Έλεγχος ολοκληρωμένης λήψης με το άθροισμα ελέγχου που τη συνόδευε`,"settings.shape":`Γωνίες`,"settings.shapeHint":`Ισχύει ταυτόχρονα για κάρτες, κουμπιά, καρτέλες, πεδία και σήματα.`,"settings.shape.round":`Στρογγυλές`,"settings.shape.soft":`Ελαφριές`,"settings.shape.square":`Ορθές`,"settings.accent":`Χρώμα τονισμού`,"settings.accentHint":`Το μοναδικό χρώμα δραστηριότητας. Το κείμενο πάνω επιλέγεται με βάση την αντίθεση.`,"settings.colours":`Χρώματα`,"settings.accentReset":`Προεπιλογή`,"queue.stop":`Διακοπή ουράς`,"queue.start":`Έναρξη ουράς`,"queue.stopMark":`Διακοπή μετά από αυτό`,"queue.stopMarkOn":`Θα σταματήσει μετά από αυτό`,"queue.limit":`Όριο`,"queue.limitWheelHint":`Κάνε κλικ στο πεδίο και άλλαξε τον αριθμό με τη ρόδα, με Shift ανά δέκα.`,"queue.play":`Αναπαραγωγή`,"queue.pause":`Παύση`,"queue.hardStop":`Διακοπή`,"queue.hardStopConfirmTitle":`Διακοπή όλων των μεταφορών τώρα;`,"queue.hardStopConfirmBody":`{n} ενεργή(-ές) μεταφορά(-ές) θα διακοπεί(-ούν) αμέσως αντί να ολοκληρωθεί(-ούν). {detail}`,"queue.hardStopConfirmLoss":`{bytes} που έχουν ήδη ληφθεί δεν μπορούν να συνεχιστούν και θα πρέπει να ληφθούν ξανά.`,"queue.hardStopConfirmUnknown":`{n} ακόμη δεν έχουν ελεγχθεί για υποστήριξη συνέχισης.`,"queue.hardStopConfirmSafe":`Οτιδήποτε εκτελείται μπορεί να συνεχιστεί από εκεί που σταμάτησε.`,"queue.hardStopConfirmCancel":`Ακύρωση`,"queue.hardStopConfirmProceed":`Διακοπή τώρα`,"settings.rainbow":`Λειτουργία ουράνιου τόξου`,"settings.rainbowHint":`Αντί για ένα χρώμα τονισμού, μια παλέτα οκτώ χρωμάτων ανά θέση, ώστε μια μεγάλη λίστα να διαβάζεται ως ξεχωριστές γραμμές.`,"settings.rainbowOn":`Χρήση παλέτας`,"settings.rainbowReactive":`Αντιδραστική λειτουργία`,"settings.rainbowReactiveHint":`Ήσυχο μέχρι να το αγγίξεις: χρώμα στο πέρασμα και σε ό,τι τρέχει`,"settings.rainbowRotate":`Περιστροφή χρωμάτων`,"settings.rainbowRotateHint":`Ανακάτεμα του σημείου εκκίνησης της παλέτας`,"settings.rainbowPalette":`Χρώμα παλέτας`,"settings.rainbowPaletteLabel":`Παλέτα χρωμάτων`,"settings.rainbowPaletteHint":`Τα οκτώ χρώματα που αποδίδονται ανά θέση. Επεξεργάσιμα μεμονωμένα.`,"settings.look.saveFailed":`Δεν ήταν δυνατή η αποθήκευση: {error}`,"settings.theme":`Θέμα`,"settings.motion.full":`Πλήρες`,"settings.motion.subtle":`Διακριτικό`,"settings.motion.off":`Ανενεργό`,"settings.motion.hint":`Το Ανενεργό απενεργοποιεί κάθε μη απαραίτητη κίνηση· το Διακριτικό κρατά τις εμφανίσεις σύντομες· το Πλήρες είναι η πλουσιότερη εμπειρία.`,"settings.motion.title":`Κίνηση`,"settings.navLabels.title":`Ετικέτες πλοήγησης`,"settings.navLabels.hint":`Πόσο σχεδιάζεται από κάθε καταχώριση: πλαϊνή μπάρα, στήλη ρυθμίσεων, κουμπιά της κεφαλίδας, γραμμές εργαλείων των λιστών και κουμπιά του συλλέκτη. Στο πέρασμα του δείκτη το μέγεθος μένει ίδιο και το όνομα εμφανίζεται από κάτω.`,"settings.navLabels.both":`Εικονίδιο και κείμενο`,"settings.navLabels.glyph":`Μόνο εικονίδιο`,"settings.navLabels.text":`Μόνο κείμενο`,"settings.navLabels.hover":`Στο πέρασμα του δείκτη`,"queue.limitUnit":`Μονάδα`,"common.show":`Εμφάνιση`,"common.hide":`Απόκρυψη`,"common.showPassword":`Εμφάνιση κωδικού`,"common.hidePassword":`Απόκρυψη κωδικού`,"common.dismiss":`Κλείσιμο`,"columns.name":`Όνομα`,"columns.size":`Μέγεθος`,"columns.progress":`Πρόοδος`,"columns.speed":`Ταχύτητα`,"columns.eta":`Απομένουν`,"columns.status":`Κατάσταση`,"columns.availability":`Διαθεσιμότητα`,"columns.host":`Πάροχος`,"columns.added":`Προστέθηκε`,"columns.finished":`Ολοκληρώθηκε`,"columns.comment":`Σχόλιο`,"columns.resolver":`Backend`,"columns.source":`Προέλευση`,"columns.enabled":`Ενεργό`,"columns.menuTitle":`Στήλες`,"columns.reset":`Επαναφορά στηλών`,"columns.headerHint":`Κάντε κλικ σε μια επικεφαλίδα για ταξινόμηση, σύρετέ την για αναδιάταξη της στήλης, σύρετε την άκρη της για αλλαγή μεγέθους, διπλό κλικ στην άκρη επαναφέρει το πλάτος. Δεξί κλικ στην επικεφαλίδα για τη λίστα στηλών.`,"columns.alwaysShown":`Αυτή η στήλη εμφανίζεται πάντα.`,"columns.lastVisible":`Μια λίστα χρειάζεται τουλάχιστον μία στήλη.`,"columns.resizeHint":`Σύρετε για αλλαγή πλάτους, διπλό κλικ για επαναφορά`,"list.sortedView":`Ταξινομημένη προβολή`,"list.sortedViewTip":`Η ταξινόμηση αλλάζει τη σειρά που βλέπετε, όχι τη σειρά που εκτελείται. Οι λήψεις ξεκινούν πάντα με τη σειρά της ουράς.`,"list.queueOrder":`Πίσω στη σειρά της ουράς`,"list.controls":`Χειριστήρια λίστας`,"list.actions":`Ενέργειες λίστας`,"list.failed":`Αυτό δεν πέτυχε: {error}`,"task.waiting.slot":`Όλες οι θέσεις κατειλημμένες`,"task.waiting.host":`Όριο αυτού του hoster`,"task.waiting.forced":`Οι θέσεις άμεσης εκκίνησης γεμάτες`,"task.waiting.disabled":`Απενεργοποιημένο`,"task.waiting.hold":`Σταματημένο χειροκίνητα`,"task.waiting.captcha":`Περιμένει captcha`,"task.waiting.account":`Ο λογαριασμός δεν είναι διαθέσιμος`,"task.waiting.halted":`Η ουρά είναι σταματημένη`,"list.dropChangedPriority":`Μετακινήθηκε: {n} λήψεις πήραν την προτεραιότητα της γραμμής όπου έπεσαν.`,"list.optionsFailed":`Δεν φορτώθηκαν οι καταχωρίσεις εκκαθάρισης από τον διακομιστή.`,"task.enable":`Ενεργοποίηση`,"task.disable":`Απενεργοποίηση`,"task.switchFailed":`Ο διακόπτης δεν άλλαξε.`,"task.uncheckable":`Ο πάροχος δεν απάντησε`,"task.expand":`Ανάπτυξη`,"task.collapse":`Σύμπτυξη`,"search.placeholder":`Αναζήτηση σε αυτή τη λίστα…`,"search.in":`Αναζήτηση σε`,"search.any":`Παντού`,"search.name":`Όνομα`,"search.host":`Πάροχος`,"search.package":`Πακέτο`,"search.comment":`Σχόλιο`,"search.url":`Σύνδεσμος`,"search.clear":`Καθαρισμός αναζήτησης`,"search.hint":`Διαλέξτε ένα πεδίο για αναζήτηση ή «Παντού» για να ψάξετε σε όλα μαζί.`,"search.syntax":`Πολλές λέξεις πρέπει να ταιριάζουν όλες, ένα μείον μπροστά αποκλείει μία. Τα host:, package: και name: ψάχνουν σε ένα μόνο πεδίο, τα >500mb και older:7d ρωτούν για μέγεθος και ηλικία. Οτιδήποτε άλλο αναζητείται ως απλό κείμενο.`,"search.shown":`{n} από {total} εμφανίζονται`,"filter.label":`Γρήγορα φίλτρα`,"filter.clear":`Εμφάνιση όλων`,"filter.running":`Σε εξέλιξη`,"filter.queued":`Στην ουρά`,"filter.paused":`Σε παύση`,"filter.finished":`Ολοκληρωμένα`,"filter.failed":`Απέτυχαν`,"filter.online":`Διαθέσιμα`,"filter.offline":`Μη διαθέσιμα`,"filter.uncheckable":`Δεν ελέγχονται`,"filter.unchecked":`Χωρίς έλεγχο`,"filter.disabled":`Απενεργοποιημένα`,"filter.held":`Σε αναμονή`,"filter.stalled":`Κολλημένο`,"cleanup.menu":`Εκκαθάριση…`,"cleanup.menuLabel":`Καταχωρίσεις εκκαθάρισης`,"cleanup.finished":`Αφαίρεση ολοκληρωμένων`,"cleanup.offline":`Αφαίρεση μη διαθέσιμων`,"cleanup.disabled":`Αφαίρεση απενεργοποιημένων συνδέσμων`,"cleanup.duplicates":`Αφαίρεση διπλότυπων`,"cleanup.incompleteArchives":`Αφαίρεση ημιτελών αρχειοθηκών`,"cleanup.what.finished":`Κάθε λήψη σε αυτή την εγκατάσταση που έχει ολοκληρωθεί.`,"cleanup.what.offline":`Κάθε σύνδεσμος αυτής της εγκατάστασης για τον οποίο ένας πάροχος απάντησε ότι χάθηκε. Οι σύνδεσμοι που δεν μπόρεσε να ελέγξει κανείς μένουν.`,"cleanup.what.disabled":`Κάθε σύνδεσμος αυτής της εγκατάστασης που είναι απενεργοποιημένος.`,"cleanup.what.duplicates":`Δεύτερα αντίγραφα μιας λήψης που ήδη βρίσκεται στη λίστα. Κρατιέται το αντίγραφο που έχει προχωρήσει περισσότερο.`,"cleanup.what.incompleteArchives":`Σετ πολλών τόμων με ένα νεκρό μέρος. Τα υπόλοιπα δεν θα αποσυμπιεστούν ποτέ.`,"cleanup.finishedKeepsFiles":`Οι ολοκληρωμένες λήψεις απλώς βγαίνουν από τη λίστα. Τα αρχεία είναι ο λόγος που κατέβηκαν, οπότε αυτή η καταχώριση δεν σβήνει ποτέ τίποτα από τον δίσκο.`,"cleanup.localOnly":`Η εκκαθάριση τρέχει πάντα σε αυτή την εγκατάσταση, όχι σε αυτή που βλέπετε. Γυρίστε στο «Αυτή η εγκατάσταση» για να τη χρησιμοποιήσετε.`,"cleanup.nothing":`Τίποτα δεν ταιριάζει με «{what}» αυτή τη στιγμή, οπότε δεν αφαιρέθηκε τίποτα.`,"cleanup.failed":`Δεν βρέθηκε τι θα αφαιρούσε αυτό: {error}`,"remove.title":`Να διαγραφούν και τα ληφθέντα αρχεία;`,"remove.count":`{n} λήψεις θα βγουν από τη λίστα.`,"remove.fromList":`Αφαίρεση από τη λίστα`,"remove.withFiles":`Αφαίρεση και διαγραφή αρχείων`,"remove.filesKept":`Τα αρχεία που βρίσκονται ήδη στον δίσκο μένουν εκεί που είναι.`,"remove.filesGone":`Αυτό σβήνει επίσης {files} αρχεία, {bytes} στον δίσκο. Δεν αναιρείται.`,"remove.noFiles":`Δεν έχει γραφτεί ακόμη τίποτα στον δίσκο.`,"remove.done":`Αφαιρέθηκαν {n} λήψεις.`,"remove.keys":`Το Del βγάζει τις επιλεγμένες γραμμές από τη λίστα. Το Shift+Del σβήνει και τα αρχεία τους.`,"remove.undo":`Αναίρεση`,"remove.undone":`{n} λήψεις πίσω στη λίστα.`,"remove.undoTooLate":`Πολύ αργά, αυτές οι γραμμές χάθηκαν οριστικά.`,"menu.label":`Ενέργειες για τις επιλεγμένες λήψεις`,"menu.packageLabel":`Ενέργειες για αυτό το πακέτο`,"menu.more":`Περισσότερα`,"menu.enable":`Ενεργοποίηση`,"menu.disable":`Απενεργοποίηση`,"menu.hold":`Κράτηση`,"menu.release":`Αποδέσμευση`,"menu.unforce":`Τέλος προώθησης`,"menu.setFolder":`Ορισμός φακέλου λήψεων…`,"menu.collapseAll":`Σύμπτυξη όλων των πακέτων`,"menu.expandAll":`Ανάπτυξη όλων των πακέτων`,"collector.checkAll":`Έλεγχος όλων`,"collector.searchToggle":`Αναζήτηση`,"skipped.summary":`{n} σύνδεσμοι δεν προστέθηκαν`,"skipped.info":`Σύνδεσμοι που ο συλλέκτης αναγνώρισε ως ήδη έτοιμους. Δεν χάθηκε τίποτα: το αντίγραφο που είναι ήδη στη λίστα είναι αυτό που θα κατέβει. Ο καθαρισμός ξεχνά μόνο αυτή τη σημείωση, δεν προσθέτει τίποτα πίσω.`,"skipped.clear":`Καθαρισμός`,"skipped.clearFailed":`Δεν έγινε καθαρισμός της λίστας. Είναι προσβάσιμος ο διακομιστής;`,"container.choose":`Επιλογή αρχείου`,"container.uploading":`Μεταφόρτωση…`,"container.tooBig":`είναι μεγαλύτερο από {max}, και κανένα container δεν είναι`,"container.staged":`Ετοιμάστηκαν {n} σύνδεσμοι από {file}.`,"container.stagedIn":`Ετοιμάστηκαν {n} σύνδεσμοι από {file} στο «{pkg}».`,"container.alsoKnown":`Άλλοι {n} ήταν ήδη στη λίστα.`,"container.allKnown":`Και οι {n} σύνδεσμοι στο {file} ήταν ήδη στη λίστα.`,"container.handed":`Το {file} είναι κρυπτογραφημένο. Παραδόθηκε στο backend του JDownloader· οι σύνδεσμοί του εμφανίζονται εδώ μόλις το πάρει (εντός {n} δευτ.).`,"container.failed":`Το {file} δεν έγινε δεκτό: {reason}`,"settings.nav.modules":`Λειτουργικές μονάδες`,"settings.nav.downloads":`Λήψεις`,"settings.nav.archives":`Συμπιεσμένα αρχεία`,"settings.nav.rules":`Κανόνες`,"settings.nav.connections":`Συνδέσεις`,"settings.nav.reconnect":`Επανασύνδεση`,"settings.nav.accounts":`Λογαριασμοί`,"settings.nav.captcha":`Captcha`,"settings.nav.schedule":`Χρονοδιάγραμμα`,"settings.nav.look":`Γενικά`,"settings.nav.appearance":`Εμφάνιση`,"settings.nav.access":`Απομακρυσμένη πρόσβαση`,"settings.nav.advanced":`Για προχωρημένους`,"settings.railLabel":`Ενότητες ρυθμίσεων`,"settings.empty":`Εδώ δεν υπάρχει ακόμη κάτι να ρυθμιστεί.`,"settings.emptyHint":`Η σελίδα είναι δηλωμένη ώστε η διεύθυνσή της να συνεχίσει να δουλεύει και ώστε τα χειριστήρια να προσγειωθούν εδώ μόλις υπάρξει το υποσύστημα.`,"settings.downloads.watchOff":`Η παρακολούθηση φακέλου είναι απενεργοποιημένη στη σελίδα των λειτουργικών μονάδων, γι’ αυτό εδώ δεν γίνεται επεξεργασία. Αν την ξαναανάψετε, ο φάκελος που ορίστηκε εδώ επανέρχεται.`,"settings.downloads.locationTitle":`Τοποθεσία`,"settings.downloads.limitsTitle":`Όρια & συμπεριφορά`,"settings.downloads.watchTitle":`Παρακολούθηση φακέλου`,"settings.downloads.idleTitle":`Αδράνεια`,"settings.downloads.idleAction":`Ενέργεια στο τέλος της ουράς`,"settings.downloads.idleActionNone":`Καμία ενέργεια`,"settings.downloads.idleActionPause":`Παύση της ουράς`,"settings.downloads.idleActionHint":`Τι γίνεται μόλις δεν μένει τίποτα σε εξέλιξη, στην ουρά ή σε αναμονή εκκίνησης. Ένας σύνδεσμος που έχεις απενεργοποιήσει δεν μετράει: δεν λογαριάζεται ποτέ ως δουλειά που απομένει, οπότε δεν μπορεί να το καθυστερεί για πάντα. Ένας σύνδεσμος σε χειροκίνητη παύση μετράει ακόμα, και τα δύο σημαίνουν «περίμενε λίγο» και όχι «ποτέ».`,"settings.downloads.idleCountdown":`Αντίστροφη μέτρηση (δευτερόλεπτα)`,"settings.downloads.idleCountdownHint":`Πόσο χρόνο έχεις για ακύρωση πριν εκτελεστεί η ενέργεια, μόλις η ουρά αδειάσει πραγματικά.`,"settings.modules.fixedAtBuild":`Το σύνολο των μονάδων καθορίζεται όταν χτίζεται το εκτελέσιμο. Σε ένα στιγμιότυπο που τρέχει δεν εγκαθίσταται τίποτα, άρα αυτή η λίστα είναι όλο κι όλο.`,"settings.modules.sectionShipped":`Σε αυτή την έκδοση`,"settings.modules.sectionDesktop":`Μόνο εκδόσεις για υπολογιστή`,"settings.modules.sectionNotBuilt":`Δεν υπάρχει σε αυτή την έκδοση`,"settings.modules.on":`Ενεργό`,"settings.modules.off":`Ανενεργό`,"settings.modules.notBuilt":`Δεν χτίστηκε`,"settings.modules.desktopOnly":`Μόνο σε υπολογιστή`,"settings.modules.noSwitch":`Εδώ δεν υπάρχει διακόπτης`,"settings.modules.configuredOn":`Ρυθμίζεται στη σελίδα {page}`,"settings.modules.switchFailed":`Ο διακόπτης απορρίφθηκε: {reason}`,"settings.modules.configureFirst":`Δεν υπάρχει ακόμη κάτι να ανάψει. Ρυθμίστε το πρώτα στη σελίδα {page}· μετά ο διακόπτης εδώ το σταματά και το ξεκινά ξανά χωρίς να χαθεί ό,τι ορίσατε.`,"settings.module.extraction":`Αποσυμπίεση αρχείων`,"settings.module.watch":`Παρακολούθηση φακέλου`,"settings.module.crawler":`Σάρωση σελίδων`,"settings.module.checksums":`Έλεγχος αθροισμάτων ελέγχου`,"settings.module.scheduler":`Χρονοπρογραμματιστής`,"settings.module.reconnect":`Επανασύνδεση`,"settings.module.packagizer":`Packagizer`,"settings.module.linkfilter":`Φίλτρο συνδέσμων`,"settings.module.connections":`Εξερχόμενες συνδέσεις`,"settings.module.cnl":`Click'n'Load`,"settings.module.federation":`Αδελφά στιγμιότυπα`,"settings.module.jd":`Υποδομή JDownloader`,"settings.module.captcha":`Captcha`,"settings.module.scripting":`Σενάρια συμβάντων`,"settings.module.tray":`Εικονίδιο στην περιοχή ειδοποιήσεων`,"settings.module.windowpolicy":`Συμπεριφορά παραθύρων`,"settings.module.updater":`Ενημερώσεις μέσα στην εφαρμογή`,"settings.advanced.search":`Φιλτράρισμα κατά όνομα ή τιμή`,"settings.advanced.allSettings":`Όλες οι ρυθμίσεις`,"settings.advanced.onlyModified":`Μόνο ό,τι διαφέρει από την προεπιλογή`,"settings.advanced.resetTitle":`Επαναφορά αυτού του κλειδιού στην προεπιλογή του`,"settings.look.updatesTitle":`Ενημερώσεις`,"settings.look.updatesAuto":`Αυτόματος έλεγχος κατά την εκκίνηση`,"settings.look.updatesCheck":`Έλεγχος για ενημερώσεις`,"settings.look.updatesChecking":`Έλεγχος…`,"settings.look.updatesFailed":`Δεν ήταν δυνατός ο έλεγχος για ενημερώσεις.`,"settings.look.updatesCurrent":`Η έκδοση {version} είναι η πιο πρόσφατη.`,"settings.look.updatesAvailable":`Η έκδοση {version} είναι διαθέσιμη`,"settings.look.updatesAvailableContainer":`Η έκδοση {version} είναι διαθέσιμη - ενημερώστε την εικόνα του container με τον τρόπο που το αναπτύξατε (docker pull, Unraid Community Applications, ...)`,"settings.look.updatesAutoInstall":`Εγκατάσταση αυτόματα όταν βρεθεί`,"settings.look.updatesAutoInstallHint":`Κατεβάζει, επαληθεύει και εφαρμόζει μια νεότερη έκδοση μόλις ο αυτόματος έλεγχος τη βρει, και μετά κάνει επανεκκίνηση. Απαιτεί ενεργοποιημένο το "Αυτόματος έλεγχος κατά την εκκίνηση" παραπάνω.`,"settings.look.updatesAutoInstallContainerHint":`Δυνατό μόνο στην έκδοση επιφάνειας εργασίας - ένα container δεν μπορεί να αντικαταστήσει τον εαυτό του από μέσα· ενημερώστε το αντ' αυτού με τον τρόπο που το αναπτύξατε (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.look.updatesAutoInstalling":`Εγκατάσταση {version}…`,"settings.look.updatesInstalling":`Εγκατάσταση…`,"settings.look.updatesInstallNow":`Εγκατάσταση τώρα`,"settings.look.updatesInstalled":`Εγκαταστάθηκε - γίνεται επανεκκίνηση…`,"settings.look.updatesInstallFailed":`Δεν ήταν δυνατή η εγκατάσταση της ενημέρωσης: {error}`,"settings.look.updatesHint":`Συγκρίνει την έκδοση αυτού του build με την πιο πρόσφατη έκδοση στο GitHub. Το desktop build μπορεί επίσης να κατεβάσει και να εγκαταστήσει αυτόματα μια νεότερη έκδοση· ένα container ενημερώνεται αντ' αυτού με τον τρόπο που αναπτύχθηκε (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.advanced.modified":`άλλαξε`,"settings.advanced.noMatch":`Κανένα κλειδί δεν ταιριάζει.`,"settings.advanced.badJson":`Αυτό πρέπει να είναι έγκυρο JSON, γι’ αυτό δεν εφαρμόζεται.`,"settings.advanced.secret":`Ένα αποθηκευμένο μυστικό δεν στέλνεται ποτέ στον περιηγητή. Αφήστε το σύμβολο κράτησης για να το κρατήσετε, ή γράψτε νέα τιμή για να το αντικαταστήσετε.`,"settings.advanced.listHint":`Εδώ επεξεργάζεται ως JSON. Η δική του σελίδα έχει τον κανονικό επεξεργαστή.`,"settings.advanced.defaultsUnavailable":`Οι εργοστασιακές τιμές δεν μπόρεσαν να ανακτηθούν, οπότε από εδώ δεν γίνεται καμία επαναφορά.`,"settings.advanced.type.boolean":`ναι / όχι`,"settings.advanced.type.number":`αριθμός`,"settings.advanced.type.text":`κείμενο`,"settings.advanced.type.list":`λίστα`,"settings.advanced.type.object":`ομάδα`,"settings.sectionLinkIntake":`Είσοδος συνδέσμων`,"settings.linkIntakeHint":`Οι τρόποι με τους οποίους ένας σύνδεσμος φτάνει μόνος του στον συλλέκτη, χωρίς να τον επικολλήσεις εδώ.`,"settings.connections.add":`Προσθήκη σύνδεσης`,"settings.connections.import":`Εισαγωγή λίστας`,"settings.connections.listTitle":`Εξερχόμενες συνδέσεις`,"settings.connections.empty":`Όλα βγαίνουν από αυτό το μηχάνημα`,"settings.connections.emptyHint":`Δεν έχει ρυθμιστεί καμία εξερχόμενη σύνδεση, οπότε κάθε λήψη χρησιμοποιεί τη δική του γραμμή αυτού του μηχανήματος. Προσθέστε έναν διαμεσολαβητή για να περνούν οι λήψεις, ή μια απευθείας γραμμή για να μένουν ορισμένοι πάροχοι εκτός.`,"settings.connections.use":`Χρήση αυτής της σύνδεσης`,"settings.connections.moveUp":`Μετακίνηση πάνω`,"settings.connections.moveDown":`Μετακίνηση κάτω`,"settings.connections.remove":`Αφαίρεση αυτής της σύνδεσης`,"settings.connections.edit":`Επεξεργασία αυτής της σύνδεσης`,"settings.connections.type":`Τύπος`,"settings.connections.typeHint":`Το «Καμία» και το «Απευθείας» δεν είναι η ίδια γραμμή. Το «Καμία» είναι αδρανές: δεν ονομάζει καμία σύνδεση και δεν χρησιμοποιείται ποτέ, οπότε επιβιώνει μόνο ώσπου να τη συμπληρώσετε. Το «Απευθείας» είναι πραγματική επιλογή - να βγαίνετε από τη δική του γραμμή αυτού του μηχανήματος και να παρακάμπτετε σκόπιμα κάθε διαμεσολαβητή για τους παρόχους που ονομάζονται πιο κάτω, έτσι εξαιρείται ένα NAS από έναν διαμεσολαβητή που ισχύει για όλη την εφαρμογή. Μια γραμμή της οποίας το φίλτρο ταιριάζει με τον πάροχο νικά μια γραμμή χωρίς φίλτρο, άρα μια απευθείας γραμμή με φίλτρο κερδίζει πάντα έναν διαμεσολαβητή που τα πιάνει όλα.`,"settings.connections.kind.none":`Καμία`,"settings.connections.kind.direct":`Απευθείας`,"settings.connections.stateNone":`Αδρανής. Από αυτή τη γραμμή δεν στέλνεται ποτέ τίποτα.`,"settings.connections.stateDirect":`Παρακάμπτει κάθε διαμεσολαβητή για τους παρόχους πιο κάτω.`,"settings.connections.warnDirectCatchAll":`Αυτή η απευθείας γραμμή δεν έχει φίλτρο παρόχων, οπότε παίρνει τη σειρά της στην εναλλαγή και στέλνει λήψεις έξω χωρίς διαμεσολαβητή στην τύχη. Ονομάστε τους παρόχους που πρέπει να αναλαμβάνει.`,"settings.connections.stateSocks4":`Το SOCKS4 μεταφέρει αναγνωριστικό χρήστη και δεν έχει καθόλου πεδίο κωδικού, οπότε για αυτή τη γραμμή δεν αποθηκεύεται κωδικός.`,"settings.connections.host":`Πάροχος`,"settings.connections.port":`Θύρα`,"settings.connections.username":`Όνομα χρήστη`,"settings.connections.usernameHint":`Τα διαπιστευτήρια του ίδιου του διαμεσολαβητή, όχι λογαριασμός παρόχου. Αν σβήσετε το όνομα χρήστη, σβήνεται μαζί και ο αποθηκευμένος κωδικός.`,"settings.connections.password":`Κωδικός`,"settings.connections.passwordStored":`αποθηκευμένος - αφήστε το κενό για να τον κρατήσετε`,"settings.connections.passwordHint":`Ένας αποθηκευμένος κωδικός δεν στέλνεται ποτέ σε αυτή τη σελίδα, γι’ αυτό το πλαίσιο είναι κενό. Αφήστε το κενό και ο αποθηκευμένος διατηρείται. Ένας αποθηκευμένος κωδικός δεν ακολουθεί τη γραμμή σε άλλον υπολογιστή, θύρα ή τύπο: αν αλλάξετε κάποιο από αυτά, πρέπει να οριστεί ξανά.`,"settings.connections.filter":`Φίλτρο παρόχων`,"settings.connections.filterHint":`Ένας πάροχος ανά γραμμή. Ένας γυμνός τομέας καλύπτει ό,τι βρίσκεται από κάτω του, οπότε το example.org αρκεί για το dl2.example.org, και τα * ? [ ] λειτουργούν ως μπαλαντέρ. Κενό σημαίνει ότι αυτή η γραμμή τα πιάνει όλα, κάτι πιο αδύναμο από μια γραμμή της οποίας το φίλτρο ταιριάζει με τον πάροχο.`,"settings.connections.filterAll":`όλοι οι πάροχοι`,"settings.connections.filterCount":`{n} πάροχοι`,"settings.connections.cap":`Ταυτόχρονες λήψεις`,"settings.connections.capHint":`Πόσες λήψεις μπορούν να μοιράζονται αυτή τη σύνδεση ταυτόχρονα. Το 0 χρησιμοποιεί την προεπιλογή του 2 - η λίστα υπάρχει για να μοιράζεται το φορτίο, και μία σύνδεση που παίρνει όλη την ουρά θα το ακύρωνε.`,"settings.connections.capDefault":`προεπιλογή`,"settings.connections.test":`Δοκιμή`,"settings.connections.testing":`Γίνεται δοκιμή…`,"settings.connections.testTarget":`Δοκιμή προς`,"settings.connections.testTargetHint":`Προαιρετικό. Αν μείνει κενό, η δοκιμή δείχνει μόνο ότι ο διαμεσολαβητής απαντά. Ονομάστε έναν προορισμό και ζητείται από τον διαμεσολαβητή να προωθήσει εκεί, κάτι που ελέγχει στ’ αλήθεια τα διαπιστευτήρια και δείχνει αν απορρίπτεται συγκεκριμένα εκείνος ο πάροχος.`,"settings.connections.testFailed":`Η δοκιμή δεν μπόρεσε να εκτελεστεί: {error}`,"settings.connections.importTitle":`Εισαγωγή λίστας διαμεσολαβητών`,"settings.connections.importLabel":`Λίστα διαμεσολαβητών`,"settings.connections.importHint":`Ένας ανά γραμμή, ως socks5://user:pass@host:port. Δουλεύουν και τα https, socks4 και socks4a, και μια γραμμή που δεν διαβάζεται εμφανίζεται πιο κάτω με τον λόγο αντί να πεταχτεί.`,"settings.connections.importPlaceholder":`socks5://user:pass@proxy.example.org:1080`,"settings.connections.importRead":`Ανάγνωση λίστας`,"settings.connections.importReading":`Γίνεται ανάγνωση…`,"settings.connections.importReady":`{n} έτοιμα για προσθήκη`,"settings.connections.importAdd":`Προσθήκη {n}`,"settings.connections.importRefused":`{n} απορρίφθηκαν`,"settings.connections.importNothing":`Από αυτή τη λίστα δεν διαβάστηκε τίποτα.`,"settings.connections.importLine":`Γραμμή {n}`,"settings.connections.importFailed":`Η λίστα δεν μπόρεσε να διαβαστεί: {error}`,"settings.connections.cancel":`Άκυρο`,"collector.filtered.summary":`{n} σύνδεσμοι κρατούνται από το φίλτρο συνδέσμων`,"collector.filtered.info":`Σύνδεσμοι που απέρριψε ένας κανόνας φίλτρου. Μένουν εδώ και όχι στη λίστα από πάνω, ώστε ένα φίλτρο που δουλεύει να μη μοιάζει με συλλέκτη γεμάτο σκουπίδια - τίποτα δεν χάθηκε. Η «Επαναφορά» βάζει τον σύνδεσμο πίσω και τον αφήνει να περάσει τον κανόνα που τον έπιασε, που είναι αυτό που θέλετε όταν ο κανόνας αποδείχθηκε πολύ πλατύς. Το «Καθάρισμα» τον σβήνει· έτσι κι αλλιώς κανένα αρχείο δεν κατέβηκε.`,"collector.filtered.restore":`Επαναφορά`,"collector.filtered.restoreAll":`Επαναφορά όλων`,"collector.filtered.clear":`Καθάρισμα`,"collector.filtered.noRule":`το φίλτρο συνδέσμων`,"collector.filtered.originTitle":`Από πού ήρθε αυτός ο σύνδεσμος`,"collector.filtered.origin.paste":`επικολλήθηκε`,"collector.filtered.origin.crawl":`από σάρωση σελίδας`,"collector.filtered.origin.cnl":`Click'n'Load`,"collector.filtered.origin.watch":`παρακολουθούμενος φάκελος`,"collector.filtered.origin.container":`περιέκτης`,"collector.filtered.restoreFailed":`Δεν έγινε επαναφορά αυτών των συνδέσμων. Είναι προσβάσιμος ο διακομιστής;`,"collector.filtered.clearFailed":`Δεν έγινε καθάρισμα αυτών των συνδέσμων. Είναι προσβάσιμος ο διακομιστής;`,"collector.filtered.toastHeld":`{n} σύνδεσμοι σε ετοιμότητα· {held} κρατούνται από το φίλτρο συνδέσμων`,"collector.filtered.toastAllHeld":`Τίποτα δεν μπήκε σε ετοιμότητα: το φίλτρο συνδέσμων κρατά {held} συνδέσμους`,"settings.rules.flavour.packagizer":`Packagizer`,"settings.rules.flavour.filter":`Φίλτρο συνδέσμων`,"settings.rules.flavourLabel":`Ποια λίστα κανόνων`,"settings.rules.setupTitle":`Σύνολο κανόνων`,"settings.rules.packagizerHint":`Τρέχει σε κάθε σύνδεσμο καθώς μπαίνει σε ετοιμότητα και ξαναγράφει ό,τι μπορεί: πακέτο, φάκελο, σχόλιο, προτεραιότητα, συνδέσεις, αυτόματη αποσυμπίεση. Κάθε κανόνας που ταιριάζει συνεισφέρει και, ανά πεδίο, κερδίζει ο μεταγενέστερος.`,"settings.rules.filterHint":`Αποφασίζει αν ένας σύνδεσμος θα μπει καν στον συλλέκτη. Ένας σύνδεσμος που απορρίπτεται δεν διαγράφεται: κρατείται μαζί με τον κανόνα και τον λόγο που τον σταμάτησαν, ώστε τίποτα να μην εξαφανίζεται χωρίς να λέει γιατί.`,"settings.rules.setOn":`Αυτή η λίστα εφαρμόζεται`,"settings.rules.setOff":`Αυτή η λίστα είναι ανενεργή`,"settings.rules.setSwitchHint":`Ο κεντρικός διακόπτης όλης της λίστας. Ανενεργός, κανένας κανόνας παρακάτω δεν τρέχει - αλλά όλοι εξακολουθούν να επεξεργάζονται και να δοκιμάζονται στα ξηρά κανονικά, γιατί μια λίστα δεν επισκευάζεται αν το να είναι κλειστή κρύβει και το τι πάει στραβά μ’ αυτήν.`,"settings.rules.stopAfterMatch":`Σταμάτα στον πρώτο κανόνα που ταιριάζει`,"settings.rules.stopHint":`Ανενεργό, κάθε κανόνας που ταιριάζει συνεισφέρει και ανά πεδίο κερδίζει ο μεταγενέστερος, που είναι αυτό που θέλει ο Packagizer. Ενεργό, η αξιολόγηση τελειώνει στο πρώτο ταίριασμα, που είναι αυτό που συνήθως θέλει ένα φίλτρο: μια αποδοχή τοποθετημένη πάνω από μια πλατιά απόρριψη προστατεύει τότε πραγματικά τον σύνδεσμο.`,"settings.rules.listTitle":`Κανόνες, με τη σειρά που τρέχουν`,"settings.rules.add":`Προσθήκη κανόνα`,"settings.rules.import":`Εισαγωγή`,"settings.rules.export":`Εξαγωγή`,"settings.rules.exportTitle":`Αποθήκευση αυτής της λίστας ως αρχείο JSON`,"settings.rules.importTitle":`Αντικατάσταση αυτής της λίστας από αρχείο JSON`,"settings.rules.importFailed":`Αυτό το αρχείο δεν είναι λίστα κανόνων: {reason}`,"settings.rules.importedCount":`Φορτώθηκαν {n} κανόνες. Τίποτα δεν αποθηκεύεται μέχρι να αποθηκεύσετε τη σελίδα.`,"settings.rules.empty":`Δεν υπάρχουν κανόνες ακόμη`,"settings.rules.emptyPackagizer":`Κάθε σύνδεσμος κρατά το πακέτο, τον φάκελο και τις επιλογές με τα οποία ήρθε. Προσθέστε κανόνα για να τακτοποιούνται καθώς μπαίνουν.`,"settings.rules.emptyFilter":`Όλοι οι σύνδεσμοι γίνονται δεκτοί. Προσθέστε κανόνα για να κρατηθούν κάποιοι.`,"settings.rules.unnamed":`Κανόνας {n}`,"settings.rules.duplicate":`Διπλασιασμός αυτού του κανόνα`,"settings.rules.remove":`Αφαίρεση αυτού του κανόνα`,"settings.rules.moveUp":`Μετακίνηση πάνω`,"settings.rules.moveDown":`Μετακίνηση κάτω`,"settings.rules.ruleOn":`Αυτός ο κανόνας τρέχει`,"settings.rules.ruleOff":`Αυτός ο κανόνας είναι ανενεργός`,"settings.rules.problemCount":`{n} προβλήματα`,"settings.rules.problemOne":`1 πρόβλημα`,"settings.rules.notRunning":`Αυτός ο κανόνας δεν εφαρμόζεται. Διορθώστε όσα αναφέρονται και αρχίζει πάλι να δουλεύει.`,"settings.rules.matchedCount":`ταίριαξαν {n} από {total}`,"settings.rules.name":`Όνομα`,"settings.rules.namePlaceholder":`Για τι χρησιμεύει αυτός ο κανόνας`,"settings.rules.nameHint":`Φαίνεται μόνο σε εσάς - σε αυτή τη λίστα, σε ένα πρόβλημα και στον λόγο για τον οποίο κρατήθηκε ένας σύνδεσμος. Ένας ανώνυμος κανόνας αναφέρεται με τη θέση του, και αυτή αλλάζει όταν αναδιατάσσετε τη λίστα.`,"settings.rules.sectionIf":`Αν ισχύουν όλα αυτά`,"settings.rules.ifHint":`Κάθε συνθήκη πρέπει να ισχύει. Ένα «είτε το ένα είτε το άλλο» γράφεται ως δύο κανόνες, κι έτσι η λίστα διαβάζεται από πάνω προς τα κάτω. Ένας κανόνας ΧΩΡΙΣ συνθήκες ταιριάζει σε κάθε σύνδεσμο - έτσι γράφεται ένας φάκελος για τα υπόλοιπα ή μια γενική απόρριψη στο τέλος.`,"settings.rules.fieldPicker":`Τι να κοιτάξει`,"settings.rules.opPicker":`Πώς να το συγκρίνει`,"settings.rules.sectionThen":`Τότε`,"settings.rules.thenHintPackagizer":`Ένα άδειο πλαίσιο σημαίνει «άφησέ το ήσυχο», ποτέ «σβήσ’ το»: ένας κανόνας που ορίζει μόνο τον φάκελο δεν πρέπει να σβήνει το όνομα πακέτου που διάλεξε προηγούμενος κανόνας.`,"settings.rules.thenHintFilter":`Ένας κανόνας που απορρίπτει κρατά τον σύνδεσμο με τον λόγο του. Και ένας κανόνας που δέχεται αξίζει: τοποθετημένος πάνω από μια πλατιά απόρριψη, με το «σταμάτα στο πρώτο ταίριασμα» ενεργό, έτσι περνάει ένας μόνο πάροχος.`,"settings.rules.addCondition":`Προσθήκη συνθήκης`,"settings.rules.removeCondition":`Αφαίρεση αυτής της συνθήκης`,"settings.rules.noConditions":`Καμία συνθήκη - αυτός ο κανόνας ταιριάζει σε κάθε σύνδεσμο.`,"settings.rules.value":`Τιμή`,"settings.rules.min":`Τουλάχιστον`,"settings.rules.max":`Το πολύ`,"settings.rules.noUpperBound":`χωρίς άνω όριο`,"settings.rules.sizeHint":`Ένας σκέτος αριθμός είναι byte. Κατανοείται και μονάδα - 700 MB, 1.5 GiB - και οι δύο διαβάζονται με βάση το 1024, όπως κάθε μέγεθος που τυπώνει η υπόλοιπη εφαρμογή.`,"settings.rules.badSize":`Αυτό δεν είναι μέγεθος.`,"settings.rules.pattern":`Μοτίβο`,"settings.rules.patternHint":`Μια κανονική έκφραση της Go, χωρίς αγκυρώσεις, και ο μοναδικός τελεστής που ΔΕΝ αγνοεί πεζά-κεφαλαία - βάλτε (?i) μπροστά αν θέλετε να τα αγνοεί. Ένα μοτίβο που δεν διαβάζεται απορρίπτεται με τον λόγο, αντί να μην ταιριάζει σιωπηλά σε τίποτα.`,"settings.rules.category":`Τύπος αρχείου`,"settings.rules.categoryCustom":`Δικό σας μοτίβο`,"settings.rules.categoryHint":`Μια συντόμευση που συμπληρώνει το μοτίβο για μια ολόκληρη οικογένεια καταλήξεων. Αποθηκεύεται ως συνηθισμένο μοτίβο, οπότε μπορείτε να διαλέξετε ένα και μετά να το επεξεργαστείτε - μετά από αυτό εδώ ξαναγράφει «δικό σας μοτίβο», γιατί δεν λέει πια τι κάνει ο κανόνας.`,"settings.rules.categoryExtensions":`Καλύπτει: {list}`,"settings.rules.unchanged":`Αμετάβλητο`,"settings.rules.yes":`Ενεργό`,"settings.rules.no":`Ανενεργό`,"settings.rules.reject":`Απόρριψη του συνδέσμου`,"settings.rules.accept":`Αποδοχή του συνδέσμου`,"settings.rules.priorityHint":`Ψηλότερη τρέχει νωρίτερα. Το εύρος είναι αυτό που δέχεται η ίδια η ουρά, οπότε ένας κανόνας δεν μπορεί να δώσει σε μια εργασία προτεραιότητα που δεν έχετε τρόπο να αναιρέσετε. Αφήστε το κενό για να μην αλλάξει τίποτα.`,"settings.rules.chunksHint":`Με πόσες συνδέσεις κατεβαίνει αυτό το ένα αρχείο. Αφήστε το κενό για να χρησιμοποιηθεί η γενική ρύθμιση. Πάνω από λίγες δεν προσφέρουν τίποτα σε πάροχο που βάζει όριο ανά αρχείο και είναι σίγουρος τρόπος να επισημανθεί ένας λογαριασμός.`,"settings.rules.emptyMeansUnchanged":`κενό = αμετάβλητο`,"settings.rules.variables":`Μεταβλητές`,"settings.rules.variablesTitle":`Εισαγωγή μεταβλητής`,"settings.rules.variablesHint":`Καθεμία από αυτές αναλύεται πάνω στον σύνδεσμο ΟΠΩΣ ΗΡΘΕ, άρα οι κανόνες δεν αλυσοδένονται: ένα πρότυπο φακέλου στον τέταρτο κανόνα βλέπει το όνομα που έδωσε ο πάροχος, όχι αυτό που έκανε ο δεύτερος κανόνας. Το τι κάνει ένας κανόνας διαβάζεται από τον κανόνα και μόνο.`,"settings.rules.varParams":`αντικαταστήστε {params}`,"settings.rules.field.filename":`Όνομα αρχείου`,"settings.rules.field.url":`Διεύθυνση συνδέσμου`,"settings.rules.field.hoster":`Πάροχος`,"settings.rules.field.source":`Σελίδα προέλευσης`,"settings.rules.field.filetype":`Τύπος αρχείου`,"settings.rules.field.filesize":`Μέγεθος αρχείου`,"settings.rules.field.package":`Πακέτο`,"settings.rules.op.contains":`περιέχει`,"settings.rules.op.contains-not":`δεν περιέχει`,"settings.rules.op.equals":`είναι`,"settings.rules.op.equals-not":`δεν είναι`,"settings.rules.op.matches":`ταιριάζει σε μοτίβο`,"settings.rules.op.is-between":`είναι ανάμεσα`,"settings.rules.action.packageName":`Όνομα πακέτου`,"settings.rules.action.downloadDir":`Φάκελος λήψεων`,"settings.rules.action.comment":`Σχόλιο`,"settings.rules.action.priority":`Προτεραιότητα`,"settings.rules.action.autoExtract":`Αυτόματη αποσυμπίεση`,"settings.rules.action.chunks":`Συνδέσεις`,"settings.rules.action.reject":`Ετυμηγορία`,"settings.rules.action.reason":`Λόγος`,"settings.rules.action.reasonHint":`Φαίνεται δίπλα στον σύνδεσμο που κρατήθηκε. Αν μείνει κενός, γράφεται ένας για εσάς, γιατί μια απόρριψη που κανείς δεν μπορεί να εξηγήσει είναι ακριβώς αυτό που η λίστα υπάρχει για να αποφεύγει.`,"settings.rules.action.folderHint":`Το μόνο πλαίσιο που επιτρέπεται να γράψει επίπεδα διαδρομής. Όλα τα άλλα κόβονται σε ένα μόνο όνομα, γιατί ένα όνομα αρχείου με κάθετο δεν είναι όνομα, είναι τρόπος να βγεις από τον φάκελο που διάλεξες.`,"settings.rules.category.video":`Βίντεο`,"settings.rules.category.audio":`Ήχος`,"settings.rules.category.image":`Εικόνες`,"settings.rules.category.archive":`Συμπιεσμένα`,"settings.rules.category.document":`Έγγραφα και βιβλία`,"settings.rules.category.subtitle":`Υπότιτλοι`,"settings.rules.category.disc":`Είδωλα δίσκων`,"settings.rules.category.program":`Προγράμματα και πακέτα`,"settings.rules.var.packagename":`Το πακέτο στο οποίο ήρθε ο σύνδεσμος`,"settings.rules.var.hoster":`Ο πάροχος, χωρίς www.`,"settings.rules.var.filename":`Το όνομα αρχείου όπως ήρθε`,"settings.rules.var.orgfilename":`Το όνομα αρχείου όπως ήρθε`,"settings.rules.var.orgfilenamewithoutext":`Το όνομα αρχείου χωρίς την κατάληξή του`,"settings.rules.var.orgfiletype":`Η κατάληξη χωρίς την τελεία, κενή όταν δεν υπάρχει`,"settings.rules.var.date":`Σήμερα, ως YYYY-MM-DD`,"settings.rules.var.year":`Το έτος, ως YYYY`,"settings.rules.var.month":`Ο μήνας, ως MM`,"settings.rules.var.day":`Η ημέρα, ως DD`,"settings.rules.var.simpledate":`Η ημερομηνία σε μοτίβο που γράφετε εσείς, στη σύνταξη ημερομηνιών της Java`,"settings.rules.var.source":`Το N-οστό τμήμα διαδρομής της διεύθυνσης της σελίδας προέλευσης, με αρίθμηση από το 1: στο https://site.org/tv/s01/list.html, το 1 είναι tv και το 2 είναι s01. ΔΕΝ είναι αυτό που εννοεί ο JDownloader με αυτή την ετικέτα - δείτε τη σημείωση παρακάτω.`,"settings.rules.var.match":`Η ομάδα σύλληψης N του μοτίβου «ταιριάζει σε μοτίβο» αυτού του κανόνα στο FIELD. Αυτό είναι το <jd:source:N> του JDownloader, με όνομα που λέει ποιο μοτίβο διαβάζει. Κανόνας χωρίς μοτίβο που ταιριάζει σε αυτό το πεδίο απορρίπτεται στην αποθήκευση, αντί να παράγει σιωπηλά φάκελο με όνομα <jd:match:url:1>.`,"settings.rules.var.append":`Τίποτα την πρώτη φορά που εμφανίζεται αυτή η τιμή, μετά _2, _3 και ούτω καθεξής`,"settings.rules.sourceDivergence":`Αντιγράφετε πρότυπο από ρυθμίσεις του JDownloader; Το <jd:source:N> σημαίνει κάτι άλλο εδώ - τμήμα διαδρομής της διεύθυνσης προέλευσης, όχι ομάδα σύλληψης. Η σημασία του JD γράφεται <jd:match:FIELD:N>. Τα δύο συμπίπτουν αρκετά συχνά ώστε να είναι επικίνδυνο, οπότε ένα αντιγραμμένο πρότυπο αξίζει μια δοκιμή στα ξηρά παρακάτω πριν το αποθηκεύσετε.`,"settings.rules.testTitle":`Δοκιμάστε το σε έναν σύνδεσμο`,"settings.rules.testHint":`Τίποτα εδώ δεν κατεβαίνει, δεν αποθηκεύεται και δεν καταγράφεται. Η λίστα όπως είναι σε αυτή τη σελίδα τρέχει πάνω σε αυτά τα δείγματα, με τον ίδιο κώδικα που τρέχει όταν παραλαμβάνονται οι σύνδεσμοι.`,"settings.rules.testUrl":`Διεύθυνση συνδέσμου`,"settings.rules.testFilename":`Όνομα αρχείου`,"settings.rules.testSource":`Σελίδα προέλευσης`,"settings.rules.testSourceHint":`Η σελίδα όπου μια σάρωση βρήκε τον σύνδεσμο. Αξίζει να συμπληρωθεί μόνο για κανόνα που ελέγχει το πεδίο προέλευσης ή χρησιμοποιεί το <jd:source:N>.`,"settings.rules.testSize":`Μέγεθος`,"settings.rules.testPackage":`Πακέτο`,"settings.rules.testPackageHint":`Το πακέτο στο οποίο θα ερχόταν ο σύνδεσμος, πριν τρέξει οποιοσδήποτε κανόνας. Σε αυτό αναλύεται το <jd:packagename>, και αξίζει να το ξέρετε: ένα πρότυπο φακέλου δεν βλέπει το όνομα πακέτου που ορίζει ένας κανόνας στο ίδιο πέρασμα.`,"settings.rules.testAdd":`Προσθήκη δείγματος`,"settings.rules.testRemove":`Αφαίρεση αυτού του δείγματος`,"settings.rules.testEmpty":`Επικολλήστε έναν σύνδεσμο και ένα όνομα αρχείου για να δείτε πού θα κατέληγε.`,"settings.rules.testRunning":`Γίνεται έλεγχος…`,"settings.rules.testFailed":`Η δοκιμή στα ξηρά δεν ήταν προσβάσιμη: {reason}`,"settings.rules.resultMatched":`Ταιριάσματα, με σειρά`,"settings.rules.resultNone":`Κανένας κανόνας δεν ταίριαξε`,"settings.rules.resultPackage":`Πακέτο`,"settings.rules.resultFolder":`Φάκελος`,"settings.rules.resultFilename":`Όνομα αρχείου`,"settings.rules.resultRejected":`Κρατήθηκε`,"settings.rules.resultAccepted":`Έγινε δεκτός`,"settings.rules.resultBy":`από {rule}`,"settings.rules.folderFromSettings":`από τις ρυθμίσεις λήψης`,"settings.rules.folderFromSettingsHint":`Κανένας κανόνας δεν όρισε φάκελο, οπότε ο σύνδεσμος καταλήγει στον ρυθμισμένο φάκελο λήψεων - ενδεχομένως μέσα σε υποφάκελο ανά πακέτο, αν αυτή η ρύθμιση είναι ενεργή. Αυτή η σελίδα δεν θα μαντέψει την πλήρη διαδρομή: αυτό που μπορεί να πει με βεβαιότητα είναι ότι κανένας κανόνας δεν την άλλαξε.`,"settings.rules.alsoSets":`Ορίζει επίσης`,"settings.reconnect.method":`Μέθοδος`,"settings.reconnect.setupTitle":`Ρύθμιση`,"settings.reconnect.methodHint":`Ο τρόπος με τον οποίο λέγεται στον δρομολογητή να ρίξει τη γραμμή και να επιστρέψει με νέα διεύθυνση. Η «Εντολή» τρέχει ένα πρόγραμμα, τα «Αιτήματα» αναπαράγουν μια καταγεγραμμένη συνομιλία HTTP, το UPnP ρωτά την πύλη μέσω δικτύου χωρίς καμία σύνδεση, και το «Σενάριο» παραδίδει ένα αρχείο σε έναν διερμηνέα. Εμφανίζονται μόνο τα πεδία που χρειάζεται η μέθοδος που επιλέξατε· τα υπόλοιπα κρατούν ό,τι πληκτρολογήσατε και επανέρχονται όταν γυρίσετε σε αυτά.`,"settings.reconnect.method.none":`Ανενεργό`,"settings.reconnect.method.command":`Εντολή`,"settings.reconnect.method.http":`Αιτήματα`,"settings.reconnect.method.upnp":`UPnP`,"settings.reconnect.method.script":`Σενάριο`,"settings.reconnect.offState":`Η επανασύνδεση είναι ανενεργή. Τίποτα δεν ζητά νέα διεύθυνση από τον δρομολογητή, και ένα όριο του hoster αφήνεται στη συνηθισμένη αναμονή μεταξύ των προσπαθειών.`,"settings.reconnect.command":`Πρόγραμμα`,"settings.reconnect.commandHint":`Η πλήρης διαδρομή του προγράμματος που θα εκτελεστεί. Ξεκινά απευθείας και όχι μέσω κελύφους, άρα μια διοχέτευση, μια ανακατεύθυνση ή δύο εντολές στη σειρά ανήκουν στη μέθοδο «Σενάριο». Τα %%router%%, %%username%%, %%password%% και %%ip%% συμπληρώνονται πριν την εκκίνηση.`,"settings.reconnect.args":`Ορίσματα`,"settings.reconnect.argsHint":`Ένα ανά γραμμή, ώστε ένα όρισμα με κενό να παραμείνει ένα όρισμα. Εδώ συμπληρώνονται οι ίδιες τέσσερις μεταβλητές.`,"settings.reconnect.upnpState":`Δεν χρειάζεται τίποτε άλλο. Η πύλη εντοπίζεται ρωτώντας το δίκτυο, και ακριβώς αυτό κάνει τούτη τη μέθοδο εκείνη που δουλεύει χωρίς να ξέρετε τίποτα για τον δρομολογητή.`,"settings.reconnect.upnpLocation":`URL περιγραφής της πύλης`,"settings.reconnect.upnpLocationHint":`Προαιρετικό, και κανονικά κενό. Συμπληρώστε το μόνο εκεί όπου η αναζήτηση multicast φιλτράρεται ενώ η ίδια η πύλη είναι μια χαρά προσβάσιμη, κάτι που η ανίχνευση από μόνη της δεν μπορεί ποτέ να διορθώσει.`,"settings.reconnect.interpreter":`Διερμηνέας`,"settings.reconnect.interpreterHint":`Το πρόγραμμα στο οποίο παραδίδεται το σενάριο, με πλήρη διαδρομή: /bin/sh, /bin/bash, /usr/bin/python3.`,"settings.reconnect.interpreterArgs":`Ορίσματα διερμηνέα`,"settings.reconnect.interpreterArgsHint":`Ένα ανά γραμμή, τοποθετούνται πριν από το αρχείο του σεναρίου. Συνήθως κενό.`,"settings.reconnect.script":`Σενάριο`,"settings.reconnect.scriptHint":`Γράφεται σε ιδιωτικό προσωρινό αρχείο και στον διερμηνέα δίνεται η διαδρομή του, οπότε τίποτα από εδώ δεν καταλήγει ποτέ μέσα σε εισαγωγικά σε γραμμή εντολών. Οι μεταβλητές συμπληρώνονται πριν γραφτεί το αρχείο, που σημαίνει ότι ένας κωδικός πληκτρολογημένος σε αυτό το πλαίσιο φτάνει σε εκείνο το αρχείο: με %%password%% μένει στο πεδίο του κωδικού.`,"settings.reconnect.router":`Διεύθυνση δρομολογητή`,"settings.reconnect.routerHint":`Ο δρομολογητής στο δικό σας δίκτυο, χωρίς σχήμα: 192.168.1.1, όχι http://192.168.1.1/. Σε αυτό αναπτύσσεται το %%router%%. Δεν είναι η δημόσια διεύθυνση, και οι δύο δεν πρέπει ποτέ να μπερδευτούν: ένα αίτημα σύνδεσης στραμμένο στη δημόσια στέλνει τον κωδικό του δρομολογητή σας στο διαδίκτυο.`,"settings.reconnect.routerFind":`Βρες τον δρομολογητή μου`,"settings.reconnect.routerFinding":`Αναζήτηση…`,"settings.reconnect.routerFound":`Βρέθηκε {address}.`,"settings.reconnect.routerFoundVia":`Βρέθηκε {address} μέσω {iface}. Αξίζει μια ματιά: σε κοντέινερ αυτό είναι συχνά η γέφυρα και όχι ο δρομολογητής.`,"settings.reconnect.routerFailed":`Δεν διαβάστηκε καμία διεύθυνση δρομολογητή εδώ: {reason}`,"settings.reconnect.username":`Όνομα χρήστη δρομολογητή`,"settings.reconnect.usernameHint":`Τα στοιχεία σύνδεσης στον δρομολογητή, όχι λογαριασμός σε hoster. Σε αυτό αναπτύσσεται το %%username%%.`,"settings.reconnect.password":`Κωδικός δρομολογητή`,"settings.reconnect.passwordStored":`αποθηκευμένος, και δεν επιστρέφει ποτέ εδώ`,"settings.reconnect.passwordHint":`Ένας αποθηκευμένος κωδικός δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα, γι' αυτό και το πλαίσιο είναι κενό: αφήστε το κενό και ο αποθηκευμένος διατηρείται. Πληκτρολογήστε νέον για να τον αντικαταστήσετε. Για να τον αφαιρέσετε εντελώς, γράψτε κάτι και μετά αδειάστε ξανά το πλαίσιο.`,"settings.reconnect.requests":`Αιτήματα`,"settings.reconnect.requestsHint":`Αναπαράγονται με τη σειρά, και η εκτέλεση σταματά στο πρώτο που δεν απαντά ο δρομολογητής. Είναι η μέθοδος LiveHeader του JDownloader: συνήθως μια σύνδεση και μετά η επανεκκίνηση ή η αποσύνδεση. Κάθε πεδίο δέχεται τις μεταβλητές.`,"settings.reconnect.requestsEmpty":`Δεν υπάρχουν ακόμη αιτήματα. Προσθέστε ένα, ή επικολλήστε ένα καταγεγραμμένο σενάριο.`,"settings.reconnect.requestAdd":`Προσθήκη αιτήματος`,"settings.reconnect.requestStep":`Βήμα {n}`,"settings.reconnect.requestUp":`Μετακίνηση αυτού του αιτήματος πάνω`,"settings.reconnect.requestDown":`Μετακίνηση αυτού του αιτήματος κάτω`,"settings.reconnect.requestRemove":`Αφαίρεση αυτού του αιτήματος`,"settings.reconnect.requestMethod":`Μέθοδος`,"settings.reconnect.requestUrl":`URL`,"settings.reconnect.requestUrlHint":`Ολόκληρο το URL, μαζί με το σχήμα. Το http://%%router%%/login.cgi είναι η συνηθισμένη μορφή.`,"settings.reconnect.requestHeaders":`Κεφαλίδες`,"settings.reconnect.requestHeadersHint":`Μία ανά γραμμή, ως Όνομα: τιμή. Μια κεφαλίδα Host τηρείται και φτάνει όντως στο καλώδιο, κάτι που χρειάζονται τα firmware δρομολογητών που σερβίρουν τη σελίδα διαχείρισης ως εικονικό host.`,"settings.reconnect.requestBody":`Σώμα`,"settings.reconnect.requestBodyHint":`Στέλνεται όπως είναι. Ένα σώμα χωρίς δικό του τύπο περιεχομένου φεύγει ως υποβολή φόρμας, και αυτό ακριβώς είναι μια καταγεγραμμένη σύνδεση σε δρομολογητή.`,"settings.reconnect.import":`Εισαγωγή σεναρίου`,"settings.reconnect.importLabel":`Σενάριο LiveHeader ή curl`,"settings.reconnect.importHint":`Επικολλήστε ένα σενάριο επανασύνδεσης του JDownloader, μαζί με τους δείκτες του. Οι μεταβλητές του μεταφράζονται κατά την είσοδο, και το %%%routerip%%% γίνεται η διεύθυνση του δρομολογητή αντί για τη δημόσια, γιατί εδώ αυτά είναι δύο διαφορετικά πράγματα.`,"settings.reconnect.importRead":`Ανάγνωση σεναρίου`,"settings.reconnect.importReading":`Γίνεται ανάγνωση…`,"settings.reconnect.importClose":`Κλείσιμο`,"settings.reconnect.importMapped":`{n} αντιστοιχίστηκαν`,"settings.reconnect.importRefusedCount":`{n} απορρίφθηκαν`,"settings.reconnect.importUse":`Αντικατάσταση της λίστας με {n}`,"settings.reconnect.importLine":`Γραμμή {n}`,"settings.reconnect.importBlocked":`Από σενάριο που έχει μέσα μια απορριφθείσα γραμμή δεν κρατιέται τίποτα. Μισό σενάριο δρομολογητή είναι μια σύνδεση χωρίς επανεκκίνηση, και αυτό φαίνεται μέρες αργότερα, ως διεύθυνση που δεν αλλάζει ποτέ.`,"settings.reconnect.importFailed":`Το σενάριο δεν μπόρεσε να διαβαστεί: {reason}`,"settings.reconnect.checkTitle":`Έλεγχος της διεύθυνσης`,"settings.reconnect.checkUrl":`URL ελέγχου IP`,"settings.reconnect.checkUrlHint":`Ανακτάται πριν τρέξει η μέθοδος και ξανά μετά· η εκτέλεση θεωρείται ολοκληρωμένη μόλις αλλάξει η διεύθυνση που τυπώνει. Δεν υπάρχει προεπιλογή, και αυτό είναι σκόπιμο: ένας διαχειριστής λήψεων που φιλοξενείτε μόνοι σας δεν πρέπει να αρχίσει να αναφέρει τη διεύθυνσή σας σε υπηρεσία που δεν επιλέξατε ποτέ. Αυτό που τυπώνει πρέπει να είναι η διεύθυνση που βλέπει το διαδίκτυο, γιατί μια σελίδα που επιστρέφει τη διεύθυνση του δικού σας δικτύου δεν ξεχωρίζει μια επανασύνδεση από το τίποτα.`,"settings.reconnect.checkPresets":`Γνωστές υπηρεσίες`,"settings.reconnect.checkPresetsHint":`Μια συντόμευση για όποιον δεν έχει προτίμηση, όχι προεπιλογή: καμία τους δεν επιλέγεται για εσάς, και οποιαδήποτε σελίδα τυπώνει τη δημόσια διεύθυνσή σας κάνει την ίδια δουλειά.`,"settings.reconnect.interval":`Δευτερόλεπτα μεταξύ των ελέγχων (1 έως 60)`,"settings.reconnect.intervalHint":`Πόσο αναμονή ανάμεσα σε δύο ματιές στο URL ελέγχου, αφού τρέξει η μέθοδος. Υπάρχει κατώτατο όριο, γιατί ένας βρόχος χωρίς αυτό μετατρέπει την υπηρεσία ελέγχου σε στόχο.`,"settings.reconnect.timeout":`Δευτερόλεπτα συνεχούς ελέγχου (5 έως 900)`,"settings.reconnect.timeoutHint":`Πόσο θα συνεχιστεί ο έλεγχος πριν η εκτέλεση χαρακτηριστεί αποτυχία. Μια επανασύνδεση που ένα τέταρτο αργότερα ακόμη περιμένει έχει αποτύχει, ό,τι κι αν λέει εδώ. Χρονικό όριο μικρότερο από το διάστημα ανεβαίνει σε αυτό, αλλιώς η εκτέλεση θα τελείωνε πριν γίνει ούτε ένας έλεγχος.`,"settings.reconnect.clamped":`Αποθηκεύτηκε ως {n}.`,"settings.reconnect.runTitle":`Εκτέλεση μιας τώρα`,"settings.reconnect.run":`Εκτέλεση τώρα`,"settings.reconnect.running":`Εκτελείται…`,"settings.reconnect.runMoved":`Η διεύθυνση πήγε από {from} σε {to}.`,"settings.reconnect.runDetail":`{n} έλεγχοι, {secs} δευτ.`,"settings.reconnect.runBusy":`Μια επανασύνδεση εκτελείται ήδη, οπότε αυτή δεν ξεκίνησε. Το αποτέλεσμα ανήκει σε όποιον ζήτησε την πρώτη.`,"settings.reconnect.runFailed":`Η επανασύνδεση δεν ολοκληρώθηκε: {reason}`,"settings.reconnect.stateConfigured":`Ρυθμισμένη`,"settings.reconnect.stateNotConfigured":`Μη ρυθμισμένη`,"settings.reconnect.stateIdle":`Αδρανής`,"settings.reconnect.stateBusy":`Εκτελείται τώρα`,"settings.reconnect.stateUnreadable":`Η κατάσταση της επανασύνδεσης δεν διαβάστηκε. Είναι προσβάσιμος ο διακομιστής;`,"settings.reconnect.notReady":`Δεν είναι έτοιμη: {reason}`,"settings.reconnect.reason.off":`Η επανασύνδεση είναι απενεργοποιημένη`,"settings.reconnect.reason.noCommand":`Η μέθοδος εντολής δεν έχει πρόγραμμα προς εκτέλεση`,"settings.reconnect.reason.noRequests":`Η μέθοδος αιτημάτων δεν έχει κανένα αίτημα`,"settings.reconnect.reason.requestNoURL":`Το αίτημα {n} δεν έχει URL`,"settings.reconnect.reason.noInterpreter":`Η μέθοδος σεναρίου δεν έχει διερμηνέα για να το εκτελέσει`,"settings.reconnect.reason.noScript":`Η μέθοδος σεναρίου δεν έχει σενάριο`,"settings.reconnect.reason.noCheckURL":`Δεν υπάρχει URL για τον έλεγχο IP`,"settings.reconnect.reason.unknownMethod":`Άγνωστη μέθοδος «{method}»`,"settings.reconnect.reason.noRouter":`Το σενάριο χρησιμοποιεί %%{var}%% αλλά δεν έχει οριστεί διεύθυνση δρομολογητή`,"settings.reconnect.runUsesSaved":`Εκτελείται το αποθηκευμένο, όχι αυτό που βλέπετε. Αποθηκεύστε πρώτα.`,"settings.reconnect.policy":`Πότε γίνεται από μόνη της`,"settings.reconnect.policyHint":`Οι αυτόματες επανασυνδέσεις πυροδοτούνται σε ένα και μόνο σημείο, και αυτή η σελίδα δεν είναι εκείνο. Μία ξεκινά όταν μια μηχανή λήψης ζητήσει η ίδια νέα προσπάθεια μετά από αναμονή, που είναι ο τρόπος με τον οποίο ένας hoster λέει ότι το όριο είναι δεμένο σε αυτή τη διεύθυνση. Δεν τρέχει ποτέ όσο η ουρά είναι σταματημένη, γιατί η επανεκκίνηση του δρομολογητή ρίχνει τις λήψεις που ακόμη τρέχουν. Δεν τρέχει ποτέ όσο η επανασύνδεση δεν είναι πλήρως ρυθμισμένη. Τρέχει μόνο μία κάθε φορά: ένα δεύτερο αίτημα περιμένει την ετυμηγορία του πρώτου αντί να του διεκδικεί τον δρομολογητή. Και αν η διεύθυνση δεν αλλάξει, τίποτα δεν επισπεύδεται και η συνηθισμένη αναμονή μεταξύ των προσπαθειών αφήνεται να τρέξει.`,"shell.bar":`Ουρά και γραμμή κατάστασης`,"shell.scope":`Ελέγχει`,"shell.scopeHint":`Η σελίδα από κάτω δείχνει αυτό το αδελφό στιγμιότυπο, οπότε και η γραμμή στοχεύει σε αυτό. Ένα αδελφό στιγμιότυπο κρατά τη δική του ουρά και το δικό του όριο ταχύτητας, γι’ αυτό ό,τι δεν μπορεί να προωθήσει αυτό εδώ το στιγμιότυπο εμφανίζεται ως μη διαθέσιμο αντί να εφαρμοστεί σε αυτό το μηχάνημα.`,"task.moveUp":`Μετακίνηση πάνω`,"task.moveDown":`Μετακίνηση κάτω`,"menu.priority":`Προτεραιότητα`,"menu.move":`Μετακίνηση`,"menu.forceStart":`Εξαναγκασμός στην αρχή`,"menu.queueStopped":`Η ουρά σταμάτησε`,"pkg.queueOrder":`Μετακίνηση όλου του πακέτου`,"priority.highest":`Ύψιστη`,"priority.higher":`Υψηλότερη`,"priority.high":`Υψηλή`,"priority.default":`Προεπιλογή`,"priority.low":`Χαμηλή`,"priority.lower":`Χαμηλότερη`,"priority.lowest":`Ελάχιστη`,"settings.chunks":`Συνδέσεις ανά λήψη (0 = αυτόματα)`,"settings.chunksHint":`Πόσες συνδέσεις ανοίγει μία λήψη όταν δεν ισχύει κάτι πιο συγκεκριμένο. Ένας κανόνας, ή μια μεμονωμένη λήψη, μπορεί να ορίσει δικό του αριθμό και υπερισχύει αυτού. Ένας πάροχος που αντέχει λιγότερες παίρνει έτσι κι αλλιώς λιγότερες: το όριο του παρόχου μπορεί μόνο να μειώσει τον αριθμό, ποτέ να τον αυξήσει. Με 0 αποφασίζει η εφαρμογή. Πάνω από μια χούφτα συνδέσεις δεν κερδίζουν τίποτα σε πάροχο που περιορίζει ανά αρχείο και είναι σίγουρος τρόπος να επισημανθεί ένας λογαριασμός.`,"task.chunks":`Συνδέσεις (0 = η γενική ρύθμιση)`,"task.chunksHint":`Πόσες συνδέσεις ανοίγει αυτή η μία λήψη. Υπερισχύει της γενικής ρύθμισης και κάθε κανόνα που την όρισε, αλλά ποτέ του παρόχου: ένας πάροχος που αντέχει λιγότερες παίρνει έτσι κι αλλιώς λιγότερες. Με 0 η εξαίρεση αίρεται και ο αριθμός αποφασίζεται ξανά αλλού.`,"columns.connection":`Σύνδεση`,"props.title":`Ιδιότητες`,"props.mixed":`Πολλές τιμές`,"props.mixedHint":`Αυτές οι γραμμές δεν συμφωνούν, γι’ αυτό το πλαίσιο είναι κενό. Αν δεν το αγγίξετε δεν αλλάζει τίποτα. Γράψτε μέσα και κάθε επιλεγμένη γραμμή παίρνει ό,τι γράψατε.`,"props.name":`Όνομα`,"props.nameHint":`Ένα όνομα αρχείου, ποτέ διαδρομή: ό,τι γράφει φακέλους κόβεται σε ένα μόνο όνομα. Μια λήψη που τελείωσε μετονομάζεται και στον δίσκο, ώστε η λίστα και ο φάκελος να μη διαφωνούν. Μια που τρέχει κρατά το αρχείο που έχει ανοιχτό το backend της και παίρνει το νέο όνομα όταν τελειώσει. Μια που δεν ξεκίνησε το παίρνει αμέσως. Ένα όνομα ανήκει σε ένα αρχείο, γι’ αυτό αυτό το πλαίσιο προσφέρεται μόνο για μία γραμμή.`,"props.comment":`Σχόλιο`,"props.commentHint":`Η δική σου σημείωση για αυτόν τον σύνδεσμο. Αποθηκεύεται και εμφανίζεται στη λίστα· τίποτα στην εφαρμογή δεν ενεργεί βάσει αυτής.`,"props.priority":`Προτεραιότητα`,"props.priorityHint":`Η υψηλότερη τρέχει πρώτη. Αναδιατάσσει ό,τι περιμένει ακόμη. Μια λήψη που ήδη τρέχει δεν στέλνεται πίσω στην ουρά.`,"props.autoExtract":`Αποσυμπίεση αρχείων`,"props.autoExtractHint":`Αν ένα αρχείο αποσυμπιέζεται μόλις τελειώσει η λήψη. Η «Κληρονόμηση» αφήνει την απόφαση στη σελίδα ρυθμίσεων αρχείων, που δεν είναι το ίδιο με το «Ανενεργό». Ο διακόπτης διαβάζεται τη στιγμή της αποσυμπίεσης, οπότε αν τον ανάψεις τώρα αποσυμπιέζεται και κάτι που τελείωσε νωρίτερα.`,"props.inherit":`Κληρονόμηση`,"props.on":`Ενεργό`,"props.off":`Ανενεργό`,"strip.label":`Σύνολα λήψεων`,"strip.of":`από`,"strip.hint":`Byte που ήρθαν έναντι byte που οφείλονται. Οι τελειωμένοι, οι αποτυχημένοι και οι απλώς συλλεγμένοι σύνδεσμοι μένουν εκτός συνόλου, όπως και ό,τι το μέγεθός του δεν το έχει δηλώσει ακόμη ο πάροχος - μια εικασία εκεί θα ήταν ένας αριθμός με τον οποίο κανείς δεν κάνει τίποτα.`,"strip.scope":`Τι καλύπτουν οι αριθμοί`,"strip.total":`Σύνολο`,"strip.visible":`Ορατά`,"strip.selected":`Επιλεγμένα`,"strip.includeDisabled":`Να μετρώνται και τα ανενεργά`,"strip.includeDisabledHint":`Μετρά τα byte των συνδέσμων που είναι σβηστοί. Από τον χρόνο που απομένει μένουν εκτός έτσι κι αλλιώς: κανείς δεν πρόκειται να τους φέρει, οπότε καμία αναμονή δεν τους ξεμπερδεύει.`,"quick.title":`Γρήγορες ρυθμίσεις`,"quick.chunksHint":`Συνδέσεις που ανοίγει μία λήψη. Δεν είναι καταμέτρηση των συνδέσεων που είναι ανοιχτές αυτή τη στιγμή: ένα backend αναφέρει την ταχύτητά του και τα byte του, ποτέ πόσα sockets κρατά, οπότε τέτοιος αριθμός δεν υπάρχει για να δειχτεί. Με 0 η επιλογή επιστρέφει στην εφαρμογή.`,"folders.title":`Επιλέξτε φάκελο`,"folders.browse":`Περιήγηση στους φακέλους`,"folders.path":`Διαδρομή`,"folders.up":`Ένα επίπεδο επάνω`,"folders.use":`Χρήση αυτού του φακέλου`,"folders.empty":`Δεν υπάρχουν υποφάκελοι εδώ.`,"folders.new":`Αυτός ο φάκελος δεν υπάρχει ακόμη. Δημιουργείται μόλις προσγειωθεί μέσα του η πρώτη λήψη.`,"folders.tail":`Διατηρείται`,"folders.tailHint":`Η περιήγηση αντικαθιστά μόνο το σταθερό μέρος του φακέλου. Οι μεταβλητές μπαίνουν ξανά στο τέλος, οπότε το σχήμα ονομασίας σας δεν χάνεται.`,"folders.roots":`Ρίζες`,"folders.truncated":`Εμφανίζονται μόνο οι πρώτοι {n} φάκελοι. Πληκτρολογήστε μια διαδρομή για να πάτε κατευθείαν σε έναν.`,"archive.menu":`Συμπιεσμένο`,"archive.unpackNow":`Αποσυμπίεση τώρα`,"archive.stop":`Διακοπή αποσυμπίεσης`,"archive.title":`Συμπιεσμένα αρχεία`,"archive.queued":`Αναμένει αποσυμπίεση`,"archive.running":`Αποσυμπιέζεται`,"archive.failed":`Δεν αποσυμπιέστηκε`,"archive.progress":`{files} αρχεία · {bytes}`,"archive.volumes":`{volumes} τόμοι`,"archive.needsPassword":`Χρειάζεται κωδικό`,"settings.archives.handles":`Ανοίγει`,"settings.archives.destination":`Αποσυμπίεση σε`,"settings.archives.destinationHint":`Πού προσγειώνονται τα αποσυμπιεσμένα αρχεία. Αφήστε το κενό και μπαίνουν δίπλα στο συμπιεσμένο.`,"settings.archives.besideArchive":`Δίπλα στο συμπιεσμένο`,"settings.archives.subfolder":`Ένας φάκελος ανά πακέτο`,"settings.archives.subfolderHint":`Βάζει κάθε πακέτο σε δικό του φάκελο κάτω από τον προορισμό. Δεν κάνει τίποτα όσο τα αρχεία προσγειώνονται δίπλα στο συμπιεσμένο, όπου ο φάκελος του πακέτου είναι ήδη ο προορισμός τους.`,"settings.archives.collision":`Αν υπάρχει ήδη αρχείο`,"settings.archives.collisionHint":`Τι κάνει ο αποσυμπιεστής όταν στον φάκελο υπάρχει ήδη αρχείο με αυτό το όνομα. Αποφασίζει μόνος του, και για ολόκληρο τον φάκελο: στη μέση μιας αποσυμπίεσης δεν υπάρχει κανείς να ρωτήσει.`,"settings.archives.collision.overwrite":`Αντικατάσταση`,"settings.archives.collision.rename":`Διατήρηση και των δύο`,"settings.archives.collision.skip":`Παράλειψη`,"settings.archives.afterwards":`Μετά`,"settings.archives.disposal":`Το ίδιο το συμπιεσμένο`,"settings.archives.disposalHint":`Τι απογίνεται το συμπιεσμένο μόλις αποσυμπιεστεί. Σε ένα container δεν υπάρχει κάδος ανακύκλωσης, οπότε η μεσαία απάντηση είναι μια μετακίνηση στο {folder} δίπλα στα αρχεία, που σαρώνεται αργότερα κατά ηλικία.`,"settings.archives.disposal.keep":`Διατήρηση`,"settings.archives.disposal.trash":`Μετακίνηση στον κάδο`,"settings.archives.disposal.delete":`Διαγραφή`,"settings.archives.retention":`Άδειασμα του κάδου μετά από (ημέρες)`,"settings.archives.retentionHint":`Πόσο μένει ένα συμπιεσμένο στο {folder} πριν το πάρει η σάρωση. Με 0 δεν σαρώνεται τίποτα, οπότε ο φάκελος αδειάζει με το χέρι.`,"settings.archives.infoFiles":`Πάρε και τις σημειώσεις δίπλα`,"settings.archives.infoFilesHint":`Αρχεία που ήρθαν μαζί με το συμπιεσμένο και όχι από μέσα του, όπως .nfo, .sfv και .txt. Αγγίζονται μόνο τα αρχεία του ίδιου του πακέτου και ποτέ ολόκληρος ο φάκελος: στην προεπιλεγμένη διάταξη ένας φάκελος κρατά πολλές κυκλοφορίες, και μια σάρωση που διάβαζε τον φάκελο θα έπαιρνε τις σημειώσεις των γειτόνων.`,"settings.archives.optionsFailed":`Δεν ήταν δυνατή η λήψη των λιστών του ίδιου του αποσυμπιεστή, οπότε οι επιλογές που προέρχονται από αυτόν δεν εμφανίζονται.`,"accounts.accountLabel":`Όνομα λογαριασμού`,"accounts.accountLabelHint":`Αυτή η υπηρεσία έχει ήδη έναν προεπιλεγμένο λογαριασμό. Ονομάστε αυτόν για να προσθέσετε μια δεύτερη σύνδεση δίπλα του.`,"accounts.accountLabelPlaceholder":`π.χ. δουλειά`,"accounts.buyPremium":`Αγορά Premium`,"accounts.changeService":`Επιλογή άλλης υπηρεσίας`,"accounts.col.enabled":`Ενεργό`,"accounts.col.expiry":`Λήξη`,"accounts.col.label":`Ετικέτα`,"accounts.col.service":`Υπηρεσία`,"accounts.col.status":`Κατάσταση`,"accounts.col.tier":`Πλάνο`,"accounts.col.traffic":`Απομένουσα κίνηση`,"accounts.tier.premium":`Premium`,"accounts.tier.free":`Δωρεάν`,"accounts.trafficLeftOf":`Απομένουν {left} από {total}`,"accounts.trafficLeftPercent":`Απομένει {n}%`,"accounts.trafficUsedTotal":`{used} έχουν ληφθεί`,"accounts.trafficUnknown":`Αυτή η υπηρεσία δεν αναφέρει όγκο.`,"accounts.credentialFromEnv":`Ορίζεται από τη μεταβλητή περιβάλλοντος {env} του container. Αφαιρέστε τη εκεί για να το αλλάξετε.`,"accounts.debrid.empty":`Δεν υπάρχουν ακόμη λογαριασμοί debrid`,"accounts.debrid.emptyHint":`Πρόσθεσε ένα κλειδί από μία από τις υποστηριζόμενες υπηρεσίες debrid για να ξεκλειδώνονται αυτόματα οι σύνδεσμοι των hoster.`,"accounts.debrid.title":`Λογαριασμοί debrid`,"accounts.debrid.hint":`Μια υπηρεσία debrid είναι ένας πληρωμένος λογαριασμός που ξεκλειδώνει πολλούς filehoster ταυτόχρονα. Το KnightLoader της στέλνει τον σύνδεσμο και κατεβάζει τον απευθείας σύνδεσμο που παίρνει πίσω: πλήρης ταχύτητα, χωρίς αναμονή, χωρίς captcha. Είναι ο προτεινόμενος δρόμος, γιατί αλλιώς χρειάζεσαι ξεχωριστό premium λογαριασμό σε κάθε hoster.`,"accounts.edit":`Επεξεργασία διαπιστευτηρίου`,"accounts.editTitle":`Λογαριασμός {service}`,"accounts.enableAccount":`Ενεργοποίηση {account}`,"accounts.hoster.empty":`Δεν υπάρχουν ακόμη λογαριασμοί hoster`,"accounts.hoster.multihoster":`Multihoster`,"accounts.hoster.title":`Λογαριασμοί hoster`,"accounts.hoster.hint":`Ο δικός σου premium λογαριασμός σε έναν μόνο hoster. Τα στοιχεία δίνονται στον ενσωματωμένο JDownloader, που κάνει τη σύνδεση. Χρησιμοποίησέ το για hoster που δεν καλύπτει καμία από τις debrid υπηρεσίες σου. Απενεργοποίησε μια γραμμή για να μείνει η σύνδεση αποθηκευμένη και να μη χρησιμοποιείται.`,"accounts.newAccount":`Προσθήκη λογαριασμού`,"accounts.newAccountTitle":`Προσθήκη λογαριασμού`,"accounts.noServicesFound":`Καμία υπηρεσία δεν ταιριάζει με την αναζήτησή σας.`,"accounts.passwordField":`Κωδικός`,"accounts.pickService":`Επιλογή υπηρεσίας`,"accounts.refresh":`Ανανέωση`,"accounts.refreshing":`Ανανέωση…`,"accounts.remove":`Αφαίρεση`,"accounts.removed":`Αφαιρέθηκε.`,"accounts.rename":`Μετονομασία`,"accounts.renew":`Ανανέωση συνδρομής`,"accounts.rowActions":`Ενέργειες λογαριασμού`,"accounts.save":`Αποθήκευση`,"accounts.saveAnyway":`Αποθήκευση ούτως ή άλλως`,"accounts.saving":`Αποθήκευση…`,"accounts.searchServices":`Αναζήτηση υπηρεσιών…`,"accounts.usernameField":`Όνομα χρήστη`,"accounts.verifyFailed":`Δεν ήταν δυνατή η επαλήθευση: {detail}`,"accounts.verifying":`Επαλήθευση…`,"accounts.whereToFind":`Από πού το βρίσκω αυτό;`,"accounts.hostsRefreshed":`Η λίστα hoster ανανεώθηκε {when}`,"accounts.routing.priorityTitle":`Σειρά προτεραιότητας`,"accounts.routing.priorityHint":`Ποια υπηρεσία ρωτιέται πρώτη όταν περισσότερες από μία μπορούν να κατεβάσουν τον ίδιο σύνδεσμο. Σύρε για αναδιάταξη.

Εδώ βρίσκονται όλες οι υπηρεσίες που μπορούν να φέρουν έναν σύνδεσμο, όχι μόνο οι λογαριασμοί debrid: TorBox, AllDebrid και συναφή, το JDownloader για εκατοντάδες hoster, το yt-dlp για ιστότοπους βίντεο και η απευθείας λήψη για έναν απλό σύνδεσμο. Γι' αυτό TorBox και yt-dlp είναι στην ίδια λίστα - και τα δύο είναι δρόμοι που μπορεί να πάρει ένας σύνδεσμος.

Η σειρά αποφασίζει μόνο ανάμεσα στις υπηρεσίες που μπορούν πράγματι να πάρουν τον συγκεκριμένο σύνδεσμο. Βάζοντας το yt-dlp πρώτο δεν στέλνεις εκεί έναν σύνδεσμο filehoster.`,"accounts.routing.priorityEmpty":`Δεν έχουν καταχωριστεί ακόμη resolvers.`,"accounts.routing.moveUp":`Μετακίνηση πάνω`,"accounts.routing.moveDown":`Μετακίνηση κάτω`,"accounts.routing.priorityAuto":`Αυτόματα`,"accounts.routing.priorityAutoHint":`Απορρίπτει τη δική σου σειρά και επιστρέφει στην αυτόματη. Η διαφορά μετράει: η αυτόματη ακολουθεί τις αλλαγές - ένα νέο κλειδί debrid, ένας λογαριασμός που γίνεται premium - ενώ η δική σου μένει όπως την άφησες.`,"accounts.routing.dragHandle":`Μετακίνηση {name}`,"accounts.routing.jdTitle":`Sidecar JDownloader`,"accounts.routing.jdHint":`Ο ενσωματωμένος, αόρατος JDownloader που ανοίγει κρυπτογραφημένα containers και καλύπτει hosts που κανένας άλλος resolver δεν καλύπτει.`,"accounts.routing.jdNotConfigured":`Μη ρυθμισμένο`,"accounts.routing.jdReachable":`Προσβάσιμο, αναθεώρηση {version}`,"accounts.routing.jdUnreachable":`Μη προσβάσιμο`,"accounts.routing.resolver.direct":`Απευθείας σύνδεσμος`,"accounts.routing.resolver.http":`Απλή εναλλακτική HTTP`,"accounts.routing.resolver.torrent":`Torrent και magnet`,"accounts.hoster.col.host":`Hoster`,"accounts.hoster.col.username":`Όνομα χρήστη`,"accounts.hoster.status.active":`Ενεργό`,"accounts.hoster.enableLogin":`Χρήση της σύνδεσης για το {host}`,"accounts.hoster.status.off":`Ανενεργό`,"accounts.hoster.status.queued":`Σε αναμονή`,"accounts.hoster.status.rejected":`Απορρίφθηκε`,"accounts.hoster.removed":`Αφαιρέθηκε.`,"accounts.hoster.pickHost":`Επιλογή hoster`,"accounts.hoster.searchHosts":`Αναζήτηση hoster…`,"accounts.hoster.loginTitle":`Σύνδεση στο {host}`,"accounts.hoster.custodyNotice":`Ο κωδικός αποστέλλεται και αποθηκεύεται από το headless sidecar του JDownloader, το οποίο εκτελεί την πραγματική σύνδεση - όχι το ίδιο το KnightLoader.`,"captcha.title":`Απαιτείται captcha`,"captcha.titleMore":`Απαιτείται captcha (ακόμη {n} σε αναμονή)`,"captcha.forHost":`Το {host} ζητά captcha πριν αυτή η λήψη μπορέσει να συνεχίσει.`,"captcha.answerLabel":`Απάντηση`,"captcha.answerPlaceholder":`Πληκτρολογήστε ό,τι βλέπετε…`,"captcha.clickHint":`Κάντε κλικ σε κάθε σημείο που ζητά η εικόνα και μετά πατήστε Συνέχεια.`,"captcha.clickCount":`Σημεία που έχουν επισημανθεί: {n}`,"captcha.clickClear":`Εκκαθάριση σημείων`,"captcha.widgetHint":`Λύστε την πρόκληση παρακάτω - συνεχίζει μόνη της μόλις το κάνετε.`,"captcha.widgetUnavailable":`Αυτή η πρόκληση δεν μπόρεσε να φορτωθεί.`,"captcha.unsupported":`Το KnightLoader δεν μπορεί να εμφανίσει αυτό το είδος πρόκλησης (αναφέρθηκε ως {vendor}).`,"captcha.unsupportedHint":`Χρησιμοποιήστε το Άκυρο παρακάτω, ή αποκλείστε τα captcha αυτού του hoster για αυτήν τη συνεδρία.`,"captcha.continue":`Συνέχεια`,"captcha.cancel":`Άκυρο`,"captcha.refresh":`Ανανέωση`,"captcha.moreOptions":`Περισσότερες επιλογές`,"captcha.blockHoster":`Να σταματήσει επίσης η ερώτηση για {host} σε αυτήν τη συνεδρία`,"captcha.blockEverywhere":`Να σταματήσει επίσης η ερώτηση για κάθε hoster σε αυτήν τη συνεδρία`,"captcha.tooLate":`Αυτή η απάντηση έφτασε πολύ αργά.`,"captcha.networkError":`Δεν ήταν δυνατή η επικοινωνία με τον διακομιστή. Δοκιμάστε ξανά.`,"captcha.timedOut":`Το captcha για το {host} έληξε.`,"captcha.resolvedElsewhere":`Το captcha για το {host} λύθηκε αλλού.`,"settings.captcha.title":`Captcha`,"settings.captcha.subtitle":`Οι αυτόματοι επιλυτές δοκιμάζονται με αυτή τη σειρά πριν σας εμφανιστεί ποτέ captcha.`,"settings.captcha.orderTitle":`Σειρά επιλυτών`,"settings.captcha.orderHint":`Κάθε ενεργοποιημένος επιλυτής παρακάτω δοκιμάζεται με τη σειρά που φαίνεται, από πάνω προς τα κάτω. Αν κανένας δεν είναι ενεργοποιημένος, ή αν όλοι αποτύχουν ή αρνηθούν, θα ερωτηθείτε απευθείας.`,"settings.captcha.orderEmpty":`Κανένας επιλυτής δεν είναι ενεργοποιημένος - κάθε captcha φτάνει απευθείας σε εσάς.`,"settings.captcha.use":`Δοκιμή αυτού του επιλυτή`,"settings.captcha.enableSolver":`Αυτόματη δοκιμή {service}`,"settings.captcha.moveUp":`Μετακίνηση πάνω`,"settings.captcha.moveDown":`Μετακίνηση κάτω`,"settings.captcha.set":`Το κλειδί έχει οριστεί`,"settings.captcha.notSet":`Δεν έχει οριστεί κλειδί`,"settings.captcha.setKey":`Ορισμός κλειδιού`,"settings.captcha.change":`Αλλαγή`,"settings.captcha.remove":`Αφαίρεση`,"settings.captcha.cancel":`Άκυρο`,"settings.captcha.save":`Αποθήκευση`,"settings.captcha.saving":`Αποθήκευση…`,"settings.captcha.placeholder":`Επικολλήστε το κλειδί API`,"settings.captcha.whereToFind":`Απόκτηση κλειδιού`,"settings.captcha.saved":`Το κλειδί API αποθηκεύτηκε.`,"settings.captcha.removed":`Το κλειδί API αφαιρέθηκε.`,"settings.captcha.saveFailed":`Δεν ήταν δυνατή η αποθήκευση του κλειδιού: {error}`,"collector.options":`Επιλογές`,"collector.destination":`Φάκελος προορισμού`,"collector.destinationRecent":`Πρόσφατα χρησιμοποιημένα`,"collector.archivePasswordHint":`Δοκιμάζεται πριν από τη λίστα που είναι αποθηκευμένη στις Ρυθμίσεις, όταν ένα αρχείο σε αυτήν την παρτίδα είναι κρυπτογραφημένο.`,"collector.linkPassword":`Κωδικός συνδέσμου`,"collector.linkPasswordHint":`Αυτό που ζητά η ίδια η σελίδα του hoster πριν παραδώσει το αρχείο, όχι ο κωδικός αρχείου παραπάνω. Δύο διαφορετικά μυστικά για δύο διαφορετικά μέρη.`,"collector.overrule":`Παράκαμψη αντίστοιχου κανόνα Packagizer`,"collector.overruleHint":`Ανενεργό: ένας αντίστοιχος κανόνας Packagizer υπερισχύει έναντι της προτεραιότητας, της αποσυμπίεσης και του σχολίου παραπάνω. Ενεργό: υπερισχύουν αυτές οι τιμές. Ο φάκελος προορισμού παραπάνω δεν αποτελεί ποτέ μέρος αυτού: ισχύει πάντα ακριβώς όπως καταχωρίστηκε.`,"collector.facets.title":`Φίλτρα`,"collector.facets.hint":`Περιορίζει τη συγκεντρωμένη λίστα ανάλογα με το πού οδηγεί ένας σύνδεσμος, τι τύπος αρχείου είναι ή σε ποιο πακέτο κατέληξε.`,"collector.facets.fileType":`Τύπος αρχείου`,"collector.facets.clearAll":`Καθαρισμός`,"collector.facets.unknownHost":`Άγνωστος πάροχος`,"collector.facets.type.archive":`Συμπιεσμένα`,"collector.facets.type.video":`Βίντεο`,"collector.facets.type.audio":`Ήχος`,"collector.facets.type.image":`Εικόνες`,"collector.facets.type.document":`Έγγραφα`,"collector.facets.type.other":`Άλλο`,"collector.stats.label":`Σύνολα συλλέκτη`,"collector.stats.packages":`Πακέτα`,"collector.stats.links":`Σύνδεσμοι`,"collector.stats.totalSize":`Συνολικό μέγεθος`,"collector.stats.hosts":`Πάροχοι`,"collector.hosterPreset":`Ρυθμίσεις παραλλαγής`,"collector.hosterPresetIntro":`Ποιες παραλλαγές συλλέγουν οι νέοι σύνδεσμοι από {host}, και σε ποια ποιότητα.`,"collector.hosterPresetAudioFormat":`Μορφή ήχου`,"settings.preParser":`Αναζήτηση συνδέσμων στο επικολλημένο ή αφημένο κείμενο`,"settings.preParserHint":`Βρίσκει συνδέσμους οπουδήποτε σε ό,τι επικολλάτε ή αφήνετε, όχι μόνο ένα καθαρό URL ανά γραμμή: επανασυνδέει μια γραμμή που έσπασε ένα πρόγραμμα αλληλογραφίας, και διαβάζει ως σύνδεσμο και έναν γυμνό υπολογιστή με διαδρομή χωρίς http:// μπροστά. Ανενεργό παίρνει κάθε γραμμή ακριβώς όπως πληκτρολογήθηκε, όπως λειτουργούσε πάντα πριν.`,"intake.pasteButton":`Επικόλληση από το πρόχειρο`,"intake.clipboardWatch":`Παρακολούθηση προχείρου`,"intake.clipboardWatchHint":`Κάθε σύνδεσμος που αντιγράφεις οπουδήποτε πηγαίνει κατευθείαν στον συλλέκτη, όσο αυτή η καρτέλα είναι ανοιχτή και σε πρώτο πλάνο. Το Ctrl+V μέσα στο KnightLoader δουλεύει πάντα και δεν χρειάζεται τίποτα από αυτά.`,"intake.clipboardWatchUnavailable":`Δεν είναι διαθέσιμο εδώ: ο περιηγητής επιτρέπει σε μια σελίδα να διαβάσει το πρόχειρο μόνο μέσω HTTPS ή σε localhost. Το Ctrl+V μέσα στο KnightLoader δουλεύει ούτως ή άλλως.`,"intake.clipboardWatchDenied":`Η παρακολούθηση προχείρου απενεργοποιήθηκε: {reason}`,"activity.crawl":`Σάρωση σελίδων`,"activity.linkcheck":`Έλεγχος συνδέσμων`,"activity.captcha":`Captcha`,"activity.autoconfirm":`Αυτόματη επιβεβαίωση`,"activity.container":`Κοντέινερ`,"activity.pending":`{n} σε αναμονή`,"activity.ofTotal":`{n} από {total}`,"activity.tooltipHint":`{active} ενεργά από {total} σε αυτόν τον γύρο`,"activity.stop":`Διακοπή αυτής της εκτέλεσης`,"notifications.quiet":`Αθόρυβη λειτουργία`,"notifications.quietHint":`Αποκρύπτει τις ειδοποιήσεις επιτυχίας και ενημέρωσης. Ένα σφάλμα, ένα captcha που σας περιμένει ή ένας λογαριασμός σε αναστολή εξακολουθούν να εμφανίζονται.`,"task.tooltip.url":`URL`,"task.tooltip.changed":`Τελευταία τροποποίηση`,"task.tooltip.infoHash":`Hash`,"task.tooltip.trackers":`Trackers`,"task.tooltip.swarm":`Ομότιμοι / seeds / αναλογία`,"task.tooltip.swarmDetail":`{peers} ομότιμοι, {seeds} seeds, αναλογία {ratio}`,"task.tooltip.uploaded":`Μεταφορτώθηκε`,"task.tooltip.seeding":`Συνεχίζει το seeding`,"columns.peers":`Ομότιμοι`,"columns.seeds":`Seeds`,"columns.ratio":`Αναλογία`,"columns.variant":`Παραλλαγή`,"columns.variant.pick":`Επιλογή παραλλαγής`,"columns.variant.pickBitrate":`Επιλογή ρυθμού bit`,"columns.variant.video":`Βίντεο`,"columns.variant.audio":`Ήχος`,"columns.variant.thumbnail":`Μικρογραφία`,"columns.variant.subtitle":`Υπότιτλοι`,"columns.variant.description":`Περιγραφή`,"columns.variant.bitrateAuto":`Αυτόματο`,"file.open":`Άνοιγμα`,"file.openNatively":`Άνοιγμα με την προεπιλεγμένη εφαρμογή`,"file.revealInFolder":`Εμφάνιση στον φάκελο`,"file.desktopOnly":`Μόνο στην εφαρμογή επιφάνειας εργασίας`,"settings.schedule.title":`Χρονοδιάγραμμα`,"settings.schedule.subtitle":`Παύση, συνέχιση ή περιορισμός της ταχύτητας λήψης σύμφωνα με χρονοδιάγραμμα.`,"settings.schedule.listTitle":`Πίνακας ωραρίων`,"settings.schedule.orderHint":`Οι γραμμές εφαρμόζονται με τη σειρά, από πάνω προς τα κάτω, και όταν δύο παράθυρα επικαλύπτονται, κερδίζει το χαμηλότερο - ένα ευρύ «παύση κάθε βράδυ» πάνω από μια στενότερη εξαίρεση αφήνει την εξαίρεση σε ισχύ, ενώ οι ίδιες δύο γραμμές αντίστροφα όχι.`,"settings.schedule.add":`Προσθήκη παραθύρου`,"settings.schedule.empty":`Η ουρά ακολουθεί το δικό της χρονοδιάγραμμα`,"settings.schedule.emptyHint":`Δεν έχει οριστεί κανένα παράθυρο, οπότε τίποτα εδώ δεν θέτει σε παύση ούτε περιορίζει την ουρά σύμφωνα με το ρολόι. Προσθέστε ένα για να συγκρατείτε τις λήψεις τη νύχτα ή να περιορίζετε την ταχύτητα ενώ εσείς οι ίδιοι χρησιμοποιείτε τη σύνδεση.`,"settings.schedule.use":`Χρήση αυτού του παραθύρου`,"settings.schedule.moveUp":`Μετακίνηση επάνω`,"settings.schedule.moveDown":`Μετακίνηση κάτω`,"settings.schedule.remove":`Αφαίρεση αυτού του παραθύρου`,"settings.schedule.edit":`Επεξεργασία αυτού του παραθύρου`,"settings.schedule.name":`Όνομα`,"settings.schedule.namePlaceholder":`π.χ. Νυχτερινή παύση`,"settings.schedule.days":`Ημέρες`,"settings.schedule.daysHint":`Σε ποιες ημέρες της εβδομάδας ανοίγει αυτό το παράθυρο. Για ένα παράθυρο που διαρκεί μετά τα μεσάνυχτα, σημειώστε την ημέρα που ΞΕΚΙΝΑ - «Παρ 22:00-06:00» τελειώνει το Σάββατο το πρωί χωρίς να είναι σημειωμένο το ίδιο το Σάββατο.`,"settings.schedule.preset.every":`Κάθε ημέρα`,"settings.schedule.preset.weekdays":`Καθημερινές`,"settings.schedule.preset.weekends":`Σαββατοκύριακα`,"settings.schedule.preset.custom":`Προσαρμοσμένο`,"settings.schedule.start":`Έναρξη`,"settings.schedule.end":`Λήξη`,"settings.schedule.endHint":`Πριν από την ώρα έναρξης, αυτό το παράθυρο διαρκεί μετά τα μεσάνυχτα και τελειώνει το επόμενο πρωί. Μια ώρα λήξης ίση με την ώρα έναρξης απορρίπτεται - θα μπορούσε να σημαίνει είτε ολόκληρη ημέρα είτε καθόλου χρόνο, και το να μαντεύετε τι εννοούνταν είναι χειρότερο από το να ρωτήσετε.`,"settings.schedule.action":`Ενέργεια`,"settings.schedule.action.pause":`Παύση`,"settings.schedule.action.resume":`Συνέχιση`,"settings.schedule.action.limit":`Περιορισμός ταχύτητας`,"settings.schedule.limit":`Όριο ταχύτητας`,"settings.schedule.disabledOff":`Αυτό το παράθυρο είναι παρκαρισμένο και δεν ενεργοποιείται ποτέ. Η ουρά συμπεριφέρεται σαν αυτή η γραμμή να μην υπήρχε καθόλου.`,"settings.schedule.activeNow":`Ενεργό τώρα, έως {time}`,"settings.schedule.next":`Επόμενο: {when}`,"settings.schedule.never":`Δεν ενεργοποιείται ποτέ όπως έχει ρυθμιστεί`,"settings.schedule.stateNow.paused":`Η ουρά είναι σε παύση αυτή τη στιγμή από το χρονοδιάγραμμα.`,"settings.schedule.stateNow.limited":`Η ουρά είναι περιορισμένη στα {rate} αυτή τη στιγμή από το χρονοδιάγραμμα.`,"settings.schedule.stateNow.running":`Κανένα παράθυρο δεν ισχύει αυτή τη στιγμή.`,"settings.schedule.nextChange":`Επόμενη αλλαγή: {when}`,"settings.schedule.noNextChange":`Τίποτα στον πίνακα δεν θα αλλάξει ποτέ την ουρά όπως έχει ρυθμιστεί.`,"settings.schedule.saveFailed":`Δεν ήταν δυνατή η αποθήκευση του χρονοδιαγράμματος: {error}`,"settings.schedule.rowError":`Γραμμή {row}: {error}`,"idleAction.title":`Η ουρά είναι ανενεργή`,"idleAction.action.pause":`Τίθεται σε παύση`,"idleAction.actionFallback":`«{action}» σε εξέλιξη`,"idleAction.in":`σε {countdown}`,"idleAction.cancel":`Ακύρωση`,"idleAction.cancelling":`Ακύρωση σε εξέλιξη…`,"idleAction.cancelFailed":`Η ακύρωση απέτυχε: ο διακομιστής δεν απάντησε.`,"settings.nav.diagnostics":`Διαγνωστικά`,"settings.diagnostics.subtitle":`Τι είναι αυτό το build, σε τι τρέχει, και η δική του πρόσφατη έξοδος καταγραφής - για επισύναψη σε μια αναφορά σφάλματος.`,"settings.diagnostics.version":`Έκδοση`,"settings.diagnostics.deployment":`Build`,"settings.diagnostics.deployment.container":`Κοντέινερ`,"settings.diagnostics.deployment.desktop":`Επιφάνεια εργασίας`,"settings.diagnostics.goVersion":`Go`,"settings.diagnostics.platform":`Πλατφόρμα`,"settings.diagnostics.goroutines":`Goroutines`,"settings.diagnostics.download":`Λήψη πακέτου διαγνωστικών`,"settings.diagnostics.downloading":`Προετοιμασία…`,"settings.diagnostics.downloadHint":`Ένα αρχείο JSON με τα παραπάνω πεδία, τις ρυθμίσεις σας με κάθε κωδικό πρόσβασης αφαιρεμένο, και τις γραμμές καταγραφής παρακάτω.`,"settings.diagnostics.downloadFailed":`Δεν ήταν δυνατή η δημιουργία του πακέτου: {error}`,"settings.diagnostics.logTitle":`Πρόσφατες γραμμές καταγραφής`,"settings.diagnostics.logHint":`Οι τελευταίες {n} γραμμές που έχει καταγράψει αυτή η διεργασία, οι παλαιότερες πρώτα. Τίποτα εδώ δεν γράφεται στον δίσκο.`,"settings.diagnostics.logEmpty":`Δεν έχει καταγραφεί ακόμη τίποτα.`,"settings.diagnostics.refresh":`Ανανέωση`,"settings.diagnostics.loadFailed":`Δεν ήταν δυνατή η φόρτωση των διαγνωστικών. Είναι προσβάσιμος ο διακομιστής;`,"settings.nav.help":`Βοήθεια`,"settings.help.intake.title":`Προσθήκη λήψεων`,"settings.help.intake.body":`Επικολλήστε συνδέσμους στον Συλλέκτη - έναν ανά γραμμή, ή ακατάστατο κείμενο: μια σάρωση βρίσκει συνδέσμους όπου κι αν βρίσκονται, στη μέση μιας πρότασης, πολλούς ανά γραμμή, ή σπασμένους σε δύο γραμμές από ένα πρόγραμμα αλληλογραφίας.`,"settings.help.intake.b1":`Αφήστε ένα αρχείο κοντέινερ συνδέσμων (.dlc, .ccf, .rsdf) ή μια απλή λίστα συνδέσμων.`,"settings.help.intake.b2":`Τα κουμπιά Click'n'Load σε σελίδες φιλοξενίας και φόρουμ λειτουργούν αμετάβλητα - το KnightLoader απαντά στο 127.0.0.1:9666, την ίδια θύρα που χρησιμοποιεί κάθε άλλος διαχειριστής λήψεων.`,"settings.help.intake.b3":`Επικολλήστε ένα URL σελίδας αντί για σύνδεσμο αρχείου και ενεργοποιήστε την Ανίχνευση για να εξαγάγετε κάθε αρχείο στο οποίο παραπέμπει, αντί να κατεβάσετε την ίδια τη σελίδα.`,"settings.help.intake.b4":`Ένας παρακολουθούμενος φάκελος παραλαμβάνει αυτόματα αρχεία .txt/.crawljob που τοποθετούνται σε αυτόν.`,"settings.help.intake.link1":`Άνοιγμα ρυθμίσεων Λήψεων`,"settings.help.intake.link2":`Άνοιγμα ρυθμίσεων Πρόσβασης (Click'n'Load)`,"settings.help.collector.title":`Ο Συλλέκτης, πριν κατέβει οτιδήποτε`,"settings.help.collector.body":`Οι νέοι σύνδεσμοι φτάνουν πρώτα στον Συλλέκτη, όχι στην ουρά: μια ενδιάμεση ζώνη για τον έλεγχο ονομάτων, μεγεθών και προειδοποιήσεων διπλότυπων πριν ξεκινήσει οτιδήποτε. Η αυτόματη επιβεβαίωση μπορεί να παραλείψει αυτό το βήμα, με προαιρετική καθυστέρηση· μόλις επιβεβαιωθεί, ένας σύνδεσμος είτε ξεκινά αμέσως είτε περιμένει στην ουρά, ανάλογα με την αυτόματη εκκίνηση.`,"settings.help.collector.link":`Άνοιγμα Γενικών ρυθμίσεων`,"settings.help.rules.title":`Κανόνες: πακέτα, φάκελοι και τι διατηρείται`,"settings.help.rules.body":`Το Packagizer μετονομάζει έναν σύνδεσμο, επιλέγει τον φάκελό του και ορίζει τις επιλογές λήψης του κατά την άφιξη, με βάση συνθήκες που γράφετε εσείς. Το Φίλτρο συνδέσμων αποφασίζει αν ένας σύνδεσμος διατηρείται καθόλου - και σε αντίθεση με ένα φίλτρο που απλώς κάνει τους συνδέσμους να εξαφανίζονται, μια απόρριψη πάντα κατονομάζει τον κανόνα που την προκάλεσε, και γιατί.`,"settings.help.rules.link":`Άνοιγμα Κανόνων`,"settings.help.queue.title":`Διαχείριση ουράς`,"settings.help.queue.body":`Θέστε σε παύση, συνεχίστε ή αναδιατάξτε οποιονδήποτε σύνδεσμο, μεμονωμένα ή ως ολόκληρο πακέτο. Η διακοπή της ουράς είναι δύο διαφορετικές ενέργειες: η διακοπή αφήνει ό,τι ήδη τρέχει άθικτο ώστε να ολοκληρωθεί μόνο του, ενώ η άμεση διακοπή όλων των μεταφορών δείχνει πρώτα τι θα χανόταν, και προχωρά μόνο μετά την επιβεβαίωσή σας - ακριβώς γι’ αυτό υπάρχει αυτή η προειδοποίηση σε μια μεταφορά που δεν μπορεί να συνεχίσει από εκεί που σταμάτησε.`,"settings.help.queue.b1":`Ένας μεμονωμένος σύνδεσμος μπορεί να παρακάμψει τον γενικό αριθμό συνδέσεων ή τον διακόπτη εξαγωγής μετά τη λήψη.`,"settings.help.queue.b2":`Ένα διπλότυπο ενός συνδέσμου που ήδη υπάρχει στη λίστα απορρίπτεται πάντα, πριν καν φτάσει στον Συλλέκτη.`,"settings.help.limits.title":`Παράκαμψη ορίων φιλοξενίας`,"settings.help.limits.body":`Τρεις ανεξάρτητοι τρόποι για να μην αποτελεί ένα δωρεάν όριο το ταβάνι:`,"settings.help.limits.b1":`Συνδέσεις - κατανείμετε τις λήψεις σε περισσότερες από μία εξερχόμενες διαδρομές (μια δεύτερη γραμμή, έναν διακομιστή μεσολάβησης, SOCKS) αντί να βγαίνετε πάντα από τη δική σας διεύθυνση αυτού του μηχανήματος.`,"settings.help.limits.b2":`Επανασύνδεση - ζητήστε από τον δρομολογητή μια νέα δημόσια διεύθυνση, το μόνο πράγμα που πραγματικά αίρει ένα όριο δεμένο στην ίδια τη διεύθυνση (UPnP, ένα εξωτερικό πρόγραμμα, ένα σενάριο, ή επανάληψη αιτημάτων HTTP προς τη σελίδα διαχείρισης του δρομολογητή - τα υπάρχοντα σενάρια JDownloader LiveHeader/curl λειτουργούν αμετάβλητα).`,"settings.help.limits.b3":`Λογαριασμοί - αποθηκεύστε στοιχεία σύνδεσης premium ή debrid (Real-Debrid, AllDebrid, TorBox και άλλα) ώστε ένας κατάλληλος σύνδεσμος να λαμβάνεται με πλήρη ταχύτητα αντί για το δωρεάν όριο.`,"settings.help.limits.link1":`Άνοιγμα Συνδέσεων`,"settings.help.limits.link2":`Άνοιγμα Επανασύνδεσης`,"settings.help.limits.link3":`Άνοιγμα Λογαριασμών`,"settings.help.captcha.title":`Captcha`,"settings.help.captcha.body":`Όταν μια φιλοξενία ζητά captcha, δοκιμάζεται πρώτα ένας αυτόματος επιλυτής που έχετε ρυθμίσει, με τη σειρά που έχετε ορίσει. Ό,τι δεν μπορεί να λύσει - ή αν δεν έχει ρυθμιστεί κανένας - παρουσιάζεται σε εσάς αντί να αποτύχει σιωπηλά.`,"settings.help.captcha.link":`Άνοιγμα ρυθμίσεων Captcha`,"settings.help.after.title":`Μετά τη λήψη`,"settings.help.after.body":`Τα αρχεία συμπίεσης αποσυμπιέζονται αυτόματα: zip (συμπεριλαμβανομένων κρυπτογραφημένων, τόσο WinZip AES όσο και το παλαιότερο ZipCrypto), rar με σύνολα πολλαπλών τόμων, 7z, tar, καθώς και gzip/bzip2/xz/zstd είτε τυλίγουν ένα tar είτε όχι - καθαρή Go, χωρίς εξωτερικά προγράμματα unrar ή 7z. Για ένα κρυπτογραφημένο αρχείο δοκιμάζεται μια λίστα κωδικών με τη σειρά. Ένα ολοκληρωμένο αρχείο ελέγχεται έναντι οποιουδήποτε checksum έχει συνοδεύσει: μια λίστα .sfv, ένα αρχείο md5/sha1/sha256sum, ή ένα CRC32 που φέρει το ίδιο το όνομα της έκδοσης.`,"settings.help.after.link1":`Άνοιγμα ρυθμίσεων Αρχείων συμπίεσης`,"settings.help.after.link2":`Άνοιγμα ρυθμίσεων Λήψεων`,"settings.help.schedule.title":`Λειτουργία χωρίς επίβλεψη`,"settings.help.schedule.body":`Ένα εβδομαδιαίο χρονοδιάγραμμα θέτει σε παύση ή περιορίζει την ουρά σύμφωνα με το ρολόι - ένα νυχτερινό παράθυρο, σωστό ακόμα και κατά τη μετάβαση στη θερινή ώρα - η ίδια ιδέα με τον Scheduler του JDownloader.`,"settings.help.schedule.link":`Άνοιγμα Χρονοδιαγράμματος`,"settings.help.instances.title":`Εκτέλεση περισσότερων από μία περιπτώσεων`,"settings.help.instances.body":`Πρόσθεσε ένα ακόμη KnightLoader ως ομότιμο και η ουρά του εμφανίζεται και σε αυτόν τον πίνακα. Στο ίδιο δίκτυο πρόκειται για απευθείας κλήση στο API της άλλης εγκατάστασης, όπως θα έκανε ένας περιηγητής. Ανάμεσα σε δίκτυα, δώδεκα λέξεις τις ζευγαρώνουν μέσω ενός relay που μπορείς να φιλοξενήσεις μόνος σου.`,"settings.help.instances.link":`Άνοιγμα Περιπτώσεων`,"settings.help.access.title":`Πρόσβαση και αντιμετώπιση προβλημάτων`,"settings.help.access.body":`Ένας κωδικός πρόσβασης κλειδώνει ολόκληρη τη διεπαφή πίσω από ένα cookie συνεδρίας. Η σελίδα Πρόσβαση απαριθμεί επίσης τις θύρες υποδοχής και τις μεθόδους πρόσβασης αυτού του build, και γιατί - ώστε μια άγνωστη ανοιχτή θύρα να έχει απάντηση αντί για εικασία. Η σελίδα Διαγνωστικά δημιουργεί ένα αρχείο για επισύναψη σε αναφορά σφάλματος: έκδοση και πληροφορίες build, τις τρέχουσες ρυθμίσεις με κάθε κωδικό πρόσβασης αφαιρεμένο, τις πρόσφατες γραμμές καταγραφής αυτής της διεργασίας, και πόσα goroutines εκτελούνται.`,"settings.help.access.link1":`Άνοιγμα ρυθμίσεων Πρόσβασης`,"settings.help.access.link2":`Άνοιγμα Διαγνωστικών`,"settings.help.advanced.title":`Όλα τα υπόλοιπα`,"settings.help.advanced.body":`Κάθε ρύθμιση αυτού του build μπορεί να διαβαστεί και να αλλάξει μέσω του ακατέργαστου ονόματός της στη σελίδα Για προχωρημένους, συμπεριλαμβανομένων μερικών - πώς αντιμετωπίζεται ένα είδωλο ενός ήδη ληφθέντος αρχείου, τι συμβαίνει όταν μια λήψη θα κατέληγε σε ένα ήδη χρησιμοποιούμενο όνομα - που δεν έχουν ακόμη ειδικό στοιχείο ελέγχου αλλού.`,"settings.help.advanced.link":`Άνοιγμα ρυθμίσεων Για προχωρημένους`,"task.mode.free":`Δωρεάν`,"task.mode.premium":`Premium`,"settings.about.title":`Σχετικά με το KnightLoader`,"settings.about.body":`Ένας ιππότης, μία σταυροφορία: ελεύθερα εργαλεία ανοιχτού κώδικα που δεν υπήρχαν έτσι. Κανένας λογαριασμός, καμία τηλεμετρία, και τίποτα αναγνώσιμο δεν φεύγει ποτέ από τα δικά σου τείχη. Σφυρηλατημένο τα βράδια και τα σαββατοκύριακα με πολλή καρδιά, γιατί η αναμονή δεν ήταν επιλογή.`,"settings.about.coffeeButton":`Κέρασέ με έναν καφέ`,"settings.about.coffee":`Το KnightLoader είναι δωρεάν και θα παραμείνει. Μια δωρεά κρατά το έργο ζωντανό και καλύπτει όσα κοστίζει: το domain, τον διακομιστή και τα βράδια που πηγαίνουν σε αυτό.`,"settings.about.report":`Προβλήματα, επιθυμίες ή προτάσεις; Άνοιξε ένα ζήτημα στο GitHub ή στείλε ένα email.`,"settings.about.version":`Έκδοση`,"settings.about.github":`GitHub`,"settings.about.mail":`Στείλε email`,"settings.about.mailSubject":`Σχόλια`,"settings.nav.scripts":`Σενάρια`,"settings.scripts.title":`Σενάρια`,"settings.scripts.subtitle":`Αυτοματοποιήστε το KnightLoader με τη δική σας JavaScript, εκτελούμενη σε ένα συμβάν ή κατ’ απαίτηση.`,"settings.scripts.listTitle":`Τα σενάριά σας`,"settings.scripts.add":`Προσθήκη σεναρίου`,"settings.scripts.empty":`Δεν υπάρχουν ακόμη σενάρια`,"settings.scripts.emptyHint":`Ένα σενάριο εκτελεί τη δική σας JavaScript όταν συμβαίνει κάτι - μια λήψη ολοκληρώνεται, μία αποτυγχάνει, η ουρά αδρανοποιείται - ή κατ’ απαίτηση, από τη Δοκιμαστική εκτέλεση εδώ και από την καταχώριση «Εκτέλεση σεναρίου» που αυτό το κύμα προσθέτει στο μενού δεξιού κλικ της λίστας λήψεων. Προσθέστε ένα για να ξεκινήσετε.`,"settings.scripts.loadFailed":`Δεν ήταν δυνατή η φόρτωση των σεναρίων. Αν αυτό το build δεν περιλαμβάνει ακόμη τη μηχανή αυτοματισμού, αυτή η σελίδα δεν έχει τίποτα να εμφανίσει ακόμη - δοκιμάστε ξανά μόλις την αποκτήσει.`,"settings.scripts.name":`Όνομα`,"settings.scripts.namePlaceholder":`π.χ. Ειδοποίηση σε αποτυχία`,"settings.scripts.unnamed":`Ανώνυμο σενάριο {n}`,"settings.scripts.trigger":`Εκτελείται σε`,"settings.scripts.triggerHint":`Τι ξεκινά αυτό το σενάριο. Το Χειροκίνητο εκτελείται μόνο όταν το ζητήσετε - από τη Δοκιμαστική εκτέλεση παρακάτω, ή από την καταχώριση «Εκτέλεση σεναρίου» που αυτό το κύμα προσθέτει στο μενού δεξιού κλικ της λίστας λήψεων.`,"settings.scripts.trigger.manual":`Χειροκίνητο (μόνο κατ’ απαίτηση)`,"settings.scripts.trigger.taskDone":`Μια λήψη ολοκληρώνεται`,"settings.scripts.trigger.taskFailed":`Μια λήψη αποτυγχάνει`,"settings.scripts.trigger.queueIdle":`Η ουρά αδρανοποιείται`,"settings.scripts.use":`Ενεργοποίηση αυτού του σεναρίου`,"settings.scripts.code":`Κώδικας`,"settings.scripts.codeStarter":`// Αυτό το σενάριο εκτελείται στη σκανδάλη που επιλέχθηκε παραπάνω.
// Το API sandbox έναντι του οποίου εκτελείται εξακολουθεί να ολοκληρώνεται - δείτε Ρυθμίσεις › Βοήθεια μόλις είναι έτοιμο.
`,"settings.scripts.timeout":`Χρονικό όριο`,"settings.scripts.timeoutHint":`Πόση ώρα μπορεί να εκτελείται αυτό το σενάριο πριν σταματήσει. Μεταξύ 100 ms και 30 s· το 0 χρησιμοποιεί την προεπιλογή των 5000 ms.`,"settings.scripts.timeoutUnit":`ms`,"settings.scripts.saveFailed":`Δεν ήταν δυνατή η αποθήκευση: {error}`,"settings.scripts.remove":`Αφαίρεση`,"settings.scripts.removeNew":`Άκυρο`,"settings.scripts.removeFailed":`Δεν ήταν δυνατή η αφαίρεση: {error}`,"settings.scripts.unsaved":`Μη αποθηκευμένο`,"settings.scripts.run":`Δοκιμαστική εκτέλεση`,"settings.scripts.running":`Εκτελείται…`,"settings.scripts.runNeedsSaveHint":`Δώσε του ένα όνομα ή λίγο κώδικα για να δημιουργηθεί, μετά δοκίμασέ το εδώ.`,"settings.scripts.runDirtyHint":`Οι αλλαγές σου αποθηκεύονται ακόμη - η δοκιμαστική εκτέλεση θα τις χρησιμοποιήσει σε λίγο.`,"settings.scripts.runOk":`Εκτελέστηκε με επιτυχία`,"settings.scripts.runOkDuration":`Εκτελέστηκε με επιτυχία σε {ms} ms`,"settings.scripts.runTimedOut":`Διακόπηκε: διήρκεσε περισσότερο από το χρονικό του όριο`,"settings.scripts.runFailed":`Απέτυχε: {error}`,"settings.scripts.output":`Έξοδος`,"task.runScript":`Εκτέλεση σεναρίου`,"task.runScriptUnnamed":`Ανώνυμο σενάριο`,"task.runScriptDone":`Το «{name}» εκτελέστηκε`,"task.runScriptFailed":`Το «{name}» απέτυχε: {error}`,"settings.access.relay.title":`Αναμεταδότης του έργου`,"settings.access.relay.body":`Το relay είναι ένας μεσάζων που κάνει όλες τις εγκαταστάσεις σου προσβάσιμες έξω από το οικιακό δίκτυο, άρα από παντού. Αυτό το παρέχει το έργο δωρεάν.`,"settings.access.relay.use":`Χρήση του αναμεταδότη του έργου`,"settings.access.relay.leadProject":`Λειτουργεί χωρίς ρυθμίσεις. Ό,τι λένε μεταξύ τους τα στιγμιότυπά σου είναι κρυπτογραφημένο, και το κλειδί το έχεις μόνο εσύ.`,"settings.access.relay.address":`Διεύθυνση`,"settings.access.relay.seesButton":`Τι βλέπει;`,"settings.access.relay.seesTip":`Δεν είναι ορατά στο relay: οι σύνδεσμοί σου, οι λήψεις σου, τα αρχεία σου και το διακριτικό πρόσβασής σου.

Είναι ορατά στο relay: οι διευθύνσεις IP των instances σου και πότε στέλνουν κάτι.

Αυτό δεν κρυπτογραφείται. Αν σε ενοχλεί, στήσε δικό σου relay.`,"settings.access.relay.none":`Χωρίς αναμεταδότη`,"settings.access.relay.noneHint":`Κανένα relay ενεργό. Στο ίδιο δίκτυο, δηλαδή στο σπίτι σου, οι εγκαταστάσεις εξακολουθούν να βρίσκονται μόνες τους. Ανάμεσα σε διαφορετικά δίκτυα δεν φτάνουν η μία στην άλλη, άρα δεν υπάρχει απομακρυσμένη πρόσβαση.`,"settings.access.relay.own":`Δικός σου αναμεταδότης`,"settings.access.relay.project":`Αναμεταδότης του έργου`,"settings.access.relay.whichHint":`Περνάει από {address}`,"settings.access.relay.savedProject":`Ο αναμεταδότης του έργου είναι ενεργός`,"settings.access.relay.savedOwn":`Ο δικός σου αναμεταδότης είναι ενεργός`,"settings.access.relay.savedOff":`Ο αναμεταδότης απενεργοποιήθηκε`,"settings.access.ownRelay.title":`Ο δικός σου αναμεταδότης`,"settings.access.ownRelay.body":`Τρέξε δικό σου relay αντί για αυτό του έργου.`,"settings.access.ownRelay.use":`Χρήση του δικού μου αναμεταδότη`,"settings.access.ownRelay.lead":`Δύο δρόμοι: αυτό το στιγμιότυπο αναλαμβάνει τον αναμεταδότη, ή δίνεις μια διεύθυνση.`,"settings.access.ownRelay.serveLabel":`Χρήση αυτής της εγκατάστασης ως relay`,"settings.access.ownRelay.serveHint":`Λειτουργεί μόνο αν αυτή η εγκατάσταση είναι προσβάσιμη από έξω, για παράδειγμα μέσω Nginx Proxy Manager και δικού σου domain.`,"settings.access.ownRelay.serveClients":`{count} συνδεδεμένα αυτή τη στιγμή.`,"settings.access.ownRelay.addressLabel":`Διεύθυνση`,"settings.access.ownRelay.addressPlaceholder":`π.χ. https://relay.mydomain.tld`,"settings.access.ownRelay.save":`Αποθήκευση`,"settings.access.ownRelay.everyInstance":`Αυτή η διεύθυνση ισχύει μόνο για αυτό το στιγμιότυπο. Καταχώρισέ την σε καθένα.`,"settings.access.ownRelay.containerLabel":`Ως ξεχωριστό κοντέινερ`,"settings.access.ownRelay.containerHint":`Αν καμία εγκατάστασή σου δεν είναι προσβάσιμη από έξω, το relay πρέπει να βρίσκεται αλλού: στον διακομιστή σου ή σε ένα μικρό VPS. Εγκατέστησε το container από τα Unraid Community Applications ή με την εντολή παρακάτω.

Το container δεν χρειάζεται ρύθμιση: ξεκίνα το, γράψε τη διεύθυνσή του παραπάνω, τέλος. Δεν αποθηκεύει τίποτα, άρα δεν υπάρχει τίποτα για backup.`,"settings.access.tokens.title":`Διακριτικά API`,"settings.access.tokens.intro":`Επώνυμα διαπιστευτήρια για ένα σενάριο, μια επέκταση περιηγητή ή ένα τηλέφωνο. Καθένα μπορεί να ανακληθεί ξεχωριστά, χωρίς να αλλάξει ο κοινόχρηστος κωδικός πρόσβασης που χρησιμοποιεί κάθε άλλος πελάτης.`,"settings.access.tokens.empty":`Δεν έχει εκδοθεί ακόμη κανένα διακριτικό.`,"settings.access.tokens.new":`Νέο διακριτικό`,"settings.access.tokens.namePlaceholder":`π.χ. το τηλέφωνό μου`,"settings.access.tokens.cancel":`Άκυρο`,"settings.access.tokens.create":`Δημιουργία`,"settings.access.tokens.creating":`Δημιουργία…`,"settings.access.tokens.created":`Δημιουργήθηκε`,"settings.access.tokens.lastUsed":`Τελευταία χρήση`,"settings.access.tokens.neverUsed":`ποτέ`,"settings.access.tokens.revoke":`Ανάκληση`,"settings.access.tokens.secretTitle":`Αντιγράψτε αυτό το διακριτικό τώρα`,"settings.access.tokens.secretWarning":`Αυτή είναι η μόνη φορά που εμφανίζεται αυτό το διακριτικό. Αποθηκεύεται ως μονόδρομος κατακερματισμός σε αυτήν την περίπτωση, οπότε αν χαθεί δεν υπάρχει τρόπος να το διαβάσετε ξανά, μόνο να το ανακαλέσετε και να δημιουργήσετε ένα νέο.`,"settings.access.tokens.copy":`Αντιγραφή`,"settings.access.tokens.copied":`Αντιγράφηκε`,"settings.access.tokens.done":`Τέλος`,"settings.access.tokens.howToUse":`Στείλτε το ως κεφαλίδα: Authorization: Bearer <token>`,"settings.access.tokens.createFailed":`Δεν ήταν δυνατή η δημιουργία του διακριτικού: {error}`,"settings.access.identity.title":`Ταυτότητα αυτής της παρουσίας`,"settings.access.identity.nameLabel":`Όνομα`,"settings.access.identity.namePlaceholder":`π.χ. Οικιακός διακομιστής`,"settings.access.identity.nameHint":`Προτείνεται πρώτο κατά τη σύζευξη και στον παρακάτω κωδικό QR, αντί για ό,τι τυχαίνει να ονομάζει αυτό το μηχάνημα το λειτουργικό σύστημα ή το περιβάλλον εκτέλεσης του container. Προαιρετικό - αφήστε το κενό για να συνεχίσετε να χρησιμοποιείτε εκείνο το όνομα.`,"settings.access.identity.domainsLabel":`Γνωστοί τομείς`,"settings.access.identity.domainsHint":`Απομνημονεύεται αυτόματα μόλις φτάσει πράγματι ένα αίτημα μέσω αυτού, ώστε να παραμένει καταχωρισμένο εδώ ακόμη και όταν μεταγενέστερα αιτήματα φτάνουν αντ' αυτού μέσω της IP του τοπικού δικτύου. Προσθέστε ένα χειροκίνητα για έναν τομέα που έχει ήδη ρυθμιστεί αλλά δεν έχει επισκεφθεί ακόμη - μία πλήρης διεύθυνση ανά γραμμή, π.χ. https://kl.example.com.`,"settings.access.cardTitle":`Σύνδεση παρουσιών και απομακρυσμένη πρόσβαση`,"settings.access.phrase.body":`Μία φράση συνδέει κάθε KnightLoader που τρέχετε. Δημιουργήστε την εδώ και επικολλήστε την στα άλλα στιγμιότυπα - χωρίς λογαριασμό, χωρίς σύνδεση, χωρίς ρυθμίσεις.`,"settings.access.phrase.noPasswordWarning":`Αυτό το στιγμιότυπο δεν έχει κωδικό. Η φράση φτάνει σε κάθε στιγμιότυπο που συνδέετε μαζί της, οπότε όποιος τη διαβάσει εδώ τα φτάνει όλα, όχι μόνο αυτό. Καλύτερα ορίστε πρώτα έναν κωδικό παραπάνω.`,"settings.access.phrase.activate":`Δημιουργία φράσης`,"settings.access.phrase.howLead":`Δώδεκα λέξεις, τίποτε άλλο. Να τι κάνεις και τι συμβαίνει:`,"settings.access.phrase.howStep1":`Σε αυτή την παρουσία πάτησε «{button}». Εμφανίζονται δώδεκα λέξεις.`,"settings.access.phrase.howStep2":`Άνοιξε το KnightLoader στο άλλο μηχάνημα, πήγαινε σε αυτή τη σελίδα, πάτησε «{button}» και πληκτρολόγησε τις δώδεκα λέξεις.`,"settings.access.phrase.howStep3":`Έτοιμο! Κάθε instance εμφανίζεται τώρα στην άλλη κάτω από «Instances» και μπορείς να χειριστείς οποιαδήποτε από οποιαδήποτε. Με ενεργό relay, τα instances σου είναι προσβάσιμα εκτός του δικτύου σου.`,"settings.access.phrase.howWhat":`Οι λέξεις είναι μυστικό, όχι διεύθυνση. Κάθε εγκατάσταση βγάζει από αυτές δύο κλειδιά: ένα για να βρει τις άλλες, ένα για την κρυπτογράφηση.

Για να βρεθούν, κάθε εγκατάσταση καλεί από μόνη της το ίδιο σημείο συνάντησης στο διαδίκτυο. Όποιος δείξει το ίδιο κλειδί, συνδέεται. Γι’ αυτό καμία εγκατάστασή σου δεν χρειάζεται να είναι προσβάσιμη από έξω.

Το σημείο συνάντησης δεν μπορεί να διαβάσει. Δεν βλέπει ποτέ τις λέξεις σου, και ό,τι περνά από εκεί είναι κρυπτογραφημένο με το δεύτερο κλειδί.`,"settings.access.phrase.statusDisconnected":`Μη συνδεδεμένο`,"settings.access.phrase.statusHintProject":`Συνδεδεμένο στο relay του έργου. Η απομακρυσμένη πρόσβαση είναι έτοιμη.`,"settings.access.phrase.statusHintOwn":`Συνδεδεμένο στο δικό σου relay. Η απομακρυσμένη πρόσβαση είναι έτοιμη.`,"settings.access.phrase.statusHintOff":`Κανένα relay ενεργό. Οι εγκαταστάσεις σου είναι προσβάσιμες μόνο στο τοπικό δίκτυο.`,"settings.access.phrase.statusHintLost":`Καμία επαφή με το relay. Το KnightLoader συνεχίζει να προσπαθεί. Ως τότε οι εγκαταστάσεις σου βρίσκονται μόνο στο τοπικό δίκτυο.`,"settings.access.phrase.statusConnected":`Συνδεδεμένο`,"settings.access.phrase.howButton":`Πώς λειτουργεί αυτό;`,"settings.access.phrase.joinButton":`Εισαγωγή φράσης`,"settings.access.phrase.joinPlaceholder":`Επικολλήστε τις δώδεκα λέξεις από το άλλο στιγμιότυπο`,"settings.access.phrase.joinConfirm":`Σύνδεση`,"settings.access.phrase.errChecksum":`Αυτή η φράση δεν είναι έγκυρη - έλεγξε μήπως κάποια λέξη γράφτηκε λάθος ή μπερδεύτηκε η σειρά.`,"settings.access.phrase.errUnknownWord":`Η λέξη {position} («{word}») δεν ανήκει στις αποδεκτές λέξεις.`,"settings.access.phrase.errWordCount":`Είναι {count} λέξεις - μια φράση χρειάζεται {need}.`,"settings.access.phrase.yourPhrase":`Η φράση σύνδεσής σας`,"settings.access.phrase.pasteHint":`Επικολλήστε αυτές τις δώδεκα λέξεις σε κάθε άλλο στιγμιότυπο που θέλετε συνδεδεμένο.`,"settings.access.phrase.qrHint":`Ή σάρωσε το από την άλλη συσκευή αντί να το πληκτρολογήσεις.`,"settings.access.phrase.revealWhy":`Εισαγάγετε τον κωδικό αυτού του στιγμιότυπου για να εμφανιστεί ξανά η φράση. Ανοίγει κάθε στιγμιότυπο της ομάδας, όχι μόνο αυτό.`,"settings.access.phrase.revealConfirm":`Εμφάνιση`,"settings.access.phrase.showAgain":`Εμφάνιση φράσης`,"settings.access.phrase.hide":`Απόκρυψη της φράσης`,"settings.access.phrase.leave":`Αποχώρηση από την ομάδα`,"settings.browsertools.appTitle":`Εφαρμογή`,"settings.browsertools.appBody":`Εγγενείς εφαρμογές για desktop, Android και iOS - αυτή η σελίδα μπορεί επίσης να εγκατασταθεί απευθείας από τον περιηγητή σας, χωρίς κανένα από τα δύο.`,"settings.browsertools.storeAndroid":`Google Play`,"settings.browsertools.storeIOS":`App Store`,"settings.browsertools.installPwaLabel":`Ή εγκαταστήστε αυτή τη σελίδα ως εφαρμογή`,"settings.browsertools.install":`Εγκατάσταση`,"settings.browsertools.installIOS":`Σε iPhone ή iPad: ανοίξτε αυτήν τη σελίδα στο Safari, πατήστε Κοινοποίηση, και έπειτα «Προσθήκη στην Αρχική οθόνη».`,"settings.access.intakePortsHint":`Άλλοι τρόποι απευθείας πρόσβασης σε αυτή την εγκατάσταση, εκτός της κανονικής σύνδεσης - καθένας με τη δική του διαθεσιμότητα εδώ.`,"settings.nav.browsertools":`Πρόγραμμα περιήγησης και εφαρμογή`,"settings.browsertools.bookmarkletStep1":`Σύρε το παρακάτω κουμπί στη γραμμή σελιδοδεικτών του προγράμματος περιήγησης - αποθηκεύεται όπως κάθε άλλος σελιδοδείκτης, τίποτα δεν εγκαθίσταται.`,"settings.browsertools.bookmarkletStep2":`Σε οποιαδήποτε σελίδα, κάνε κλικ πάνω του (επίλεξε πρώτα κείμενο αν θέλεις μόνο αυτό). Ανοίγει μια μικρή καρτέλα KnightLoader με τον σύνδεσμο αυτής της σελίδας, ή το επιλεγμένο κείμενο, ήδη συμπληρωμένο - έλεγξέ το και πρόσθεσέ το από εκεί ως λήψη.`,"settings.browsertools.installLabel":`Πώς να την εγκαταστήσετε`,"settings.browsertools.apkLabel":`Λήψη του APK`,"settings.browsertools.installChromiumStep1":`Αποσυμπιέστε το ληφθέν αρχείο.`,"settings.browsertools.installChromiumStep2":`Ανοίξτε chrome://extensions (ή edge://extensions, brave://extensions).`,"settings.browsertools.installChromiumStep3":`Ενεργοποιήστε τη λειτουργία προγραμματιστή.`,"settings.browsertools.installChromiumStep4":`Επιλέξτε «Φόρτωση χωρίς συμπίεση» και επιλέξτε τον αποσυμπιεσμένο φάκελο.`,"settings.browsertools.installChromiumStep5":`Κάνε κλικ στο εικονίδιο του παζλ δίπλα στη γραμμή διευθύνσεων και καρφίτσωσε το KnightLoader. ο Chrome δεν βάζει μόνος του νέες επεκτάσεις στη γραμμή.`,"settings.browsertools.installFirefoxStep1":`Για μόνιμη εγκατάσταση: ανοίξτε το about:addons και κάντε κλικ στο εικονίδιο γραναζιού πάνω δεξιά.`,"settings.browsertools.installFirefoxStep2":`Επιλέξτε «Εγκατάσταση προσθέτου από αρχείο…» και επιλέξτε αυτό το αρχείο.`,"settings.browsertools.installFirefoxStep3":`Για γρήγορη δοκιμή αντ’ αυτού, ανοίξτε το about:debugging#/runtime/this-firefox και επιλέξτε «Φόρτωση προσωρινής πρόσθετης λειτουργίας» - εξαφανίζεται με επανεκκίνηση του Firefox.`,"settings.browsertools.bookmarkletTitle":`Bookmarklet`,"settings.browsertools.bookmarkletLink":`Προσθήκη στο KnightLoader`,"settings.browsertools.copyCode":`Αντιγραφή του κώδικα αντ’ αυτού`,"settings.browsertools.copied":`Αντιγράφηκε.`,"settings.browsertools.extensionTitle":`Επέκταση περιηγητή`,"quickadd.title":`Προσθήκη στο KnightLoader`,"quickadd.manualLabel":`Σύνδεσμος (ή επικολλήστε πολλούς, έναν ανά γραμμή)`,"quickadd.manualPlaceholder":`https://example.com/file.zip`,"quickadd.add":`Προσθήκη`,"quickadd.adding":`Προσθήκη…`,"quickadd.emptyHint":`Δεν κοινοποιήθηκε τίποτα - επικολλήστε έναν σύνδεσμο με το χέρι, ή χρησιμοποιήστε αυτήν τη σελίδα από το bookmarklet ή το μενού Κοινοποίησης της συσκευής σας.`,"quickadd.staged":`Προστέθηκε στον συλλέκτη.`,"quickadd.stagedNamed":`Το «{name}» προστέθηκε στον συλλέκτη.`,"quickadd.stagedCount":`Προστέθηκαν {n} σύνδεσμοι στον συλλέκτη.`,"quickadd.none":`Δεν προστέθηκε τίποτα - κάθε σύνδεσμος εδώ ήταν ήδη στον συλλέκτη.`,"quickadd.failed":`Δεν ήταν δυνατή η προσθήκη αυτού: {error}`,"quickadd.undo":`Αναίρεση`,"quickadd.undone":`Αφαιρέθηκε.`,"quickadd.openCollector":`Άνοιγμα συλλέκτη`,"quickadd.toPeer":`Αποστολή στο «{name}».`,"quickadd.undoFailed":`Δεν ήταν δυνατή η αναίρεση - εξακολουθεί να είναι εκεί. ({error})`,"quickadd.close":`Κλείσιμο παραθύρου`,"settings.system.lifecycleTitle":`Έξοδος & επανεκκίνηση`,"settings.system.quit":`Έξοδος`,"settings.system.restart":`Επανεκκίνηση`,"settings.system.quitConfirmTitle":`Έξοδος από το KnightLoader;`,"settings.system.restartConfirmTitle":`Επανεκκίνηση του KnightLoader;`,"settings.system.quitConfirmBody":`Η εργασία σε εξέλιξη ολοκληρώνεται πρώτα, έπειτα η διεργασία τερματίζεται. {note}`,"settings.system.confirmCancel":`Άκυρο`,"settings.system.confirmProceed":`Επιβεβαίωση`,"settings.system.unavailable":`Αυτό το build δεν έχει τρόπο να το κάνει αυτό από τον περιηγητή.`,"settings.system.lifecycleNoteContainer":`Αυτό είναι build container. Το αν η διεργασία θα επιστρέψει μετά την Έξοδο ή την Επανεκκίνηση αποφασίζεται αποκλειστικά από την πολιτική επανεκκίνησης του container σας, όχι από το ποιο από τα δύο πατάτε: και τα δύο κάνουν το ίδιο πράγμα.`,"settings.system.lifecycleNoteDesktop":`Αυτό είναι το desktop build· η έξοδος και η επανεκκίνηση ολοκληρώνονται όπως ακριβώς και το κλείσιμο του παραθύρου.`,"settings.system.acting":`Εργασία σε εξέλιξη…`,"settings.system.shuttingDownTitle":`Τερματισμός`,"settings.system.shuttingDown":`Τερματισμός. Αν αυτή η περίπτωση επιστρέψει μόνη της, η σελίδα θα επανασυνδεθεί μόλις συμβεί αυτό· διαφορετικά κλείστε αυτήν την καρτέλα.`,"settings.system.actionFailed":`Δεν ήταν δυνατή η εκτέλεση αυτού: {error}`,"settings.system.backupButton":`Λήψη αντιγράφου ασφαλείας`,"settings.system.restoreButton":`Μεταφόρτωση αντιγράφου ασφαλείας`,"settings.system.backupRestoreHint":`Κατεβάζει τη βάση δεδομένων και τις ρυθμίσεις ως ένα αρχείο, συμπεριλαμβανομένων των κωδικών πρόσβασης - κρατήστε το κάπου ιδιωτικά - ή τα επαναφέρει από ένα προηγουμένως κατεβασμένο αντίγραφο ασφαλείας, αντικαθιστώντας ό,τι υπάρχει τώρα.`,"settings.system.backupRestoreTitle":`Αντίγραφο ασφαλείας & Επαναφορά`,"settings.system.restoreConfirmTitle":`Επαναφορά από αντίγραφο ασφαλείας;`,"settings.system.restoreConfirmBody":`Αυτό αντικαθιστά την τρέχουσα βάση δεδομένων και τις ρυθμίσεις με τα περιεχόμενα του «{name}». Αυτό δεν μπορεί να αναιρεθεί.`,"settings.system.restoring":`Επικύρωση και προετοιμασία…`,"settings.system.restoreFailed":`Δεν ήταν δυνατή η επαναφορά: {error}`,"settings.system.restoreStaged":`{status}`,"settings.system.loadFailed":`Δεν ήταν δυνατή η φόρτωση. Είναι προσβάσιμος ο διακομιστής;`,"settings.nav.resolvers":`Επιλυτές`,"settings.module.ytdlp":`yt-dlp`,"settings.resolvers.moduleUnavailable":`Η μονάδα δεν είναι διαθέσιμη`,"settings.resolvers.moduleUnavailableHint":`Όλα τα παρακάτω αποθηκεύονται ούτως ή άλλως και ισχύουν μόλις γίνει διαθέσιμο το yt-dlp - δεν χάνεται τίποτα αν τα επεξεργαστείτε ήδη τώρα.`,"settings.resolvers.intro":`Ρυθμίσεις για το backend yt-dlp, το οποίο ανακτά τις τοποθεσίες πολυμέσων και ροής που υποστηρίζει το ίδιο το yt-dlp. Ποια υπηρεσία χειρίζεται καν έναν σύνδεσμο - yt-dlp, λογαριασμός debrid, το sidecar JD χωρίς περιβάλλον εργασίας - αποφασίζεται από τη σειρά δρομολόγησης στη σελίδα Λογαριασμοί· εδώ περιγράφεται μόνο τι κάνει το yt-dlp αφού ένας σύνδεσμος έχει ήδη δρομολογηθεί σε αυτό.`,"settings.resolvers.quality":`Ποιότητα`,"settings.resolvers.qualityHint":`Ποιος επιλογέας -f χρησιμοποιείται κατά την εκκίνηση του yt-dlp. Η καλύτερη διαθέσιμη είναι η προεπιλογή του ίδιου του yt-dlp, και αυτό που χρησιμοποιούσε κάθε λήψη πριν υπάρξει αυτή η ρύθμιση.`,"settings.resolvers.quality.best":`Καλύτερη διαθέσιμη`,"settings.resolvers.quality.2160p":`Έως 2160p (4K)`,"settings.resolvers.quality.1440p":`Έως 1440p`,"settings.resolvers.quality.1080p":`Έως 1080p`,"settings.resolvers.quality.720p":`Έως 720p`,"settings.resolvers.quality.480p":`Έως 480p`,"settings.resolvers.quality.360p":`Έως 360p`,"settings.resolvers.quality.custom":`Προσαρμοσμένη συμβολοσειρά μορφής`,"settings.resolvers.customFormat":`Προσαρμοσμένη μορφή`,"settings.resolvers.customFormatHint":`Η δική του τιμή -f του yt-dlp, π.χ. bestvideo[height<=720]+bestaudio/best. Περνάει χωρίς έλεγχο· μια τιμή που απορρίπτει το yt-dlp αποτυγχάνει με το δικό του σφάλμα στην εργασία.`,"settings.resolvers.playlist":`Λήψη ολόκληρης της λίστας αναπαραγωγής όταν ένας σύνδεσμος οδηγεί σε μία`,"settings.resolvers.subtitles":`Υπότιτλοι`,"settings.resolvers.subtitleLangs":`Γλώσσες`,"settings.resolvers.subtitleLangsHint":`Η δική του τιμή --sub-langs του yt-dlp, π.χ. en,de. Κενό σημαίνει en ως προεπιλογή.`,"settings.resolvers.subtitleAuto":`Λήψη και αυτόματα δημιουργημένων υποτίτλων όταν δεν υπάρχει χειροκίνητο κομμάτι`,"settings.resolvers.outputTitle":`Όνομα αρχείου εξόδου`,"settings.resolvers.outputHint":`Το δικό του πρότυπο -o του yt-dlp. Κενό χρησιμοποιεί το ενσωματωμένο %(title)s.%(ext)s. Μπορεί να περιλαμβάνει υποφακέλους, π.χ. %(uploader)s/%(title)s.%(ext)s.`,"settings.nav.torrents":`Torrents`,"settings.module.torrents":`Torrents`,"settings.torrents.title":`Torrents`,"settings.torrents.subtitle":`Στόχοι seeding, όρια μεταφοράς, προώθηση θύρας και DHT/PEX για συνδέσμους magnet και αρχεία .torrent.`,"settings.torrents.seedingTitle":`Seeding`,"settings.torrents.seedRatio":`Στόχος αναλογίας seeding`,"settings.torrents.seedRatioHint":`Συνεχίζει το seeding ενός ολοκληρωμένου torrent μέχρι να έχει επιστραφεί στο σμήνος αυτό το ποσοστό σε σχέση με το μέγεθός του. 0 = χωρίς στόχο αναλογίας.`,"settings.torrents.seedDuration":`Στόχος διάρκειας seeding`,"settings.torrents.seedDurationHint":`Συνεχίζει το seeding ενός ολοκληρωμένου torrent για τόση ώρα μετά την ολοκλήρωση. 0 = χωρίς χρονικό όριο. Όποιος από τους δύο παραπάνω στόχους επιτευχθεί πρώτος σταματά το seeding.`,"settings.torrents.seedDurationUnit":`ώρες`,"settings.torrents.transferTitle":`Όριο μεταφοράς`,"settings.torrents.uploadLimit":`Όριο μεταφόρτωσης`,"settings.torrents.uploadLimitHint":`Περιορίζει πόσο γρήγορα ένα torrent στέλνει δεδομένα στο σμήνος κατά το seeding. 0 = απεριόριστο.`,"settings.torrents.uploadLimitUnit":`KiB/s`,"settings.torrents.portTitle":`Θύρα και προώθηση`,"settings.torrents.port":`Θύρα`,"settings.torrents.portHint":`Η θύρα στην οποία αυτή η παρουσία ακούει για συνδέσεις σμήνους. 0 αφήνει τη μηχανή torrent να διαλέξει μία.`,"settings.torrents.portMapHint":`Ζητά από τον δρομολογητή να προωθήσει την παραπάνω θύρα σε αυτόν τον υπολογιστή μέσω UPnP, ώστε ομότιμοι πίσω από άλλον δρομολογητή να μπορούν και πάλι να τη φτάσουν. Δεν την υποστηρίζουν όλοι οι δρομολογητές, και κάποιοι δέχονται το αίτημα χωρίς αυτό να λειτουργεί πραγματικά.`,"settings.torrents.portMapButton":`Δοκιμή προώθησης UPnP`,"settings.torrents.portMapping":`Ερώτημα στον δρομολογητή…`,"settings.torrents.portMapNeedsPort":`Ορίστε μια θύρα παραπάνω πριν την προωθήσετε - στο 0 ο δρομολογητής δεν έχει πού να προωθήσει.`,"settings.torrents.portMapConfirmed":`Επιβεβαιώθηκε: η θύρα {port} έχει προωθηθεί και επαληθεύτηκε ως προσβάσιμη.`,"settings.torrents.portMapUnconfirmed":`Ο δρομολογητής δέχτηκε το αίτημα, αλλά δεν ήταν δυνατή η επιβεβαίωση ότι η προώθηση λειτουργεί πραγματικά. Ορισμένοι δρομολογητές το κάνουν αυτό σιωπηλά - δοκιμάστε έναν έλεγχο συνδεσιμότητας από έξω από το δίκτυο.`,"settings.torrents.portMapFailed":`Δεν ήταν δυνατή η προώθηση της θύρας: {error}`,"settings.torrents.portMapUnavailable":`Αυτή η έκδοση δεν προσφέρει ακόμη προώθηση θύρας.`,"settings.torrents.networkTitle":`Ανακάλυψη ομότιμων`,"settings.torrents.dht":`DHT`,"settings.torrents.dhtHint":`Βρίσκει ομότιμους χωρίς κανέναν tracker, χρησιμοποιώντας άλλους πελάτες BitTorrent ως κατανεμημένο ευρετήριο.`,"settings.torrents.pex":`Ανταλλαγή ομότιμων (PEX)`,"settings.torrents.pexHint":`Ανταλλάσσει γνωστούς ομότιμους με όσους είναι ήδη συνδεδεμένοι, ώστε ένα σμήνος με λίγους ομότιμους να βρίσκεται πιο γρήγορα.`,"settings.torrents.privateNote":`Ένα ιδιωτικό torrent απενεργοποιεί και τα δύο αυτόματα μόλις γίνουν γνωστά τα μεταδεδομένα του, ανεξάρτητα από τη ρύθμιση εδώ - αμέσως σε ένα αρχείο .torrent που έχει μεταφορτωθεί, ή, σε έναν σύνδεσμο magnet, μόλις φτάσουν τα δικά του μεταδεδομένα από το σμήνος. Οι περισσότεροι ιδιωτικοί trackers αποκλείουν λογαριασμούς που χρησιμοποιούν οποιοδήποτε από τα δύο.`,"settings.torrents.engineNote":`Ο στόχος αναλογίας seeding, ο στόχος διάρκειας seeding και η θύρα φτάνουν πλέον σε κάθε torrent που ξεκινά αυτή η μηχανή - η θύρα όμως μόνο για το πρώτο torrent από την τελευταία επανεκκίνηση αυτής της παρουσίας, επειδή ο ίδιος ο πελάτης torrent της μηχανής χτίζεται μία φορά και δεν ξαναχτίζεται ποτέ έπειτα· μια μεταγενέστερη αποθήκευση εξακολουθεί ωστόσο να αποθηκεύεται σωστά και ισχύει από την επόμενη επανεκκίνηση και μετά. Το όριο μεταφόρτωσης εξακολουθεί να αποθηκεύεται και να επικυρώνεται μόνο, χωρίς η μηχανή να έχει ακόμη τρόπο να το εφαρμόσει σε μια ενεργή λήψη. Το DHT και το PEX παρακάτω βρίσκονται στην ίδια κατάσταση για ένα συνηθισμένο (μη ιδιωτικό) torrent: η προεπιλογή αυτής της παρουσίας δεν φτάνει επίσης ακόμη σε μια ενεργή λήψη, οπότε ένα torrent εξακολουθεί να κάνει seeding με και τα δύο ενεργά, ανεξάρτητα από τη ρύθμιση εδώ - ένα ιδιωτικό torrent είναι μια εντελώς διαφορετική περίπτωση, δείτε τη σημείωση παρακάτω. Το κουμπί προώθησης παρακάτω κάνει πάντως κάτι πραγματικό: ζητά ειλικρινά από τον δρομολογητή να προωθήσει τον αριθμό θύρας που πληκτρολογήθηκε παραπάνω, είτε ακούει αυτή τη στιγμή κάποιο torrent σε αυτήν είτε όχι.`,"torrent.staging":`Προσθήκη…`,"torrent.staged":`Το {file} προστέθηκε στον συλλέκτη.`,"torrent.stagedIn":`Το {file} προστέθηκε στον συλλέκτη στο «{pkg}».`,"torrent.duplicate":`Το {file} υπάρχει ήδη στη λίστα.`,"torrent.onlyOne":`μπορεί να ελεγχθεί μόνο ένα .torrent τη φορά`,"torrent.tree.summary":`Επιλέχθηκαν {n} από {total} αρχεία ({size})`,"torrent.tree.private":`Ιδιωτικός tracker`,"torrent.tree.selectAll":`Επιλογή όλων`,"torrent.tree.selectNone":`Καμία επιλογή`,"torrent.tree.cancel":`Ακύρωση`,"torrent.tree.add":`Προσθήκη στον συλλέκτη`,"onboarding.step":`Βήμα {n} από {total}`,"onboarding.skip":`Παράλειψη`,"onboarding.back":`Πίσω`,"onboarding.next":`Επόμενο`,"onboarding.finish":`Έναρξη χρήσης του KnightLoader`,"onboarding.welcome.title":`Καλώς όρισες στο KnightLoader`,"onboarding.welcome.body":`Το KnightLoader είναι ένας αυτοφιλοξενούμενος διαχειριστής λήψεων: επικόλλησε ή άφησε έναν σύνδεσμο και ανακτάται από όποιο backend τον χειρίζεται πραγματικά - την ενσωματωμένη μηχανή για απλούς συνδέσμους αρχείων, το yt-dlp για σελίδες πολυμέσων, μια υπηρεσία debrid για hosters που ήδη πληρώνεις, ή ένα JDownloader χωρίς γραφικό περιβάλλον για όλα τα υπόλοιπα. Αυτή η σύντομη περιήγηση καλύπτει τη μία ρύθμιση που αξίζει να ελέγξεις πριν ξεκινήσεις.`,"onboarding.welcome.langLabel":`Γλώσσα διεπαφής`,"onboarding.folder.title":`Πού πρέπει να καταλήγουν τα αρχεία;`,"onboarding.folder.body":`Αυτός είναι ο φάκελος όπου γράφονται οι ολοκληρωμένες λήψεις. Πληκτρολόγησε μια διαδρομή ή περιήγησε τον διακομιστή για να διαλέξεις μία - μπορείς να τον αλλάξεις ξανά όποτε θέλεις από τη σελίδα γενικών ρυθμίσεων.`,"onboarding.accounts.title":`Premium hosters, όποτε τους θελήσεις`,"onboarding.accounts.body":`Η ουρά λειτουργεί χωρίς κανέναν λογαριασμό. Όταν θελήσεις πλήρη ταχύτητα σε έναν hoster ή υπηρεσία debrid που ήδη πληρώνεις, πρόσθεσε τα στοιχεία σύνδεσής της στους Λογαριασμούς - δεν χρειάζεται να ρυθμίσεις τίποτα εδώ τώρα.`,"onboarding.accounts.link":`Άνοιγμα Λογαριασμών`,"onboarding.finished.title":`Είσαι έτοιμος`,"onboarding.finished.body":`Αυτό κλείνει την περιήγηση. Η σελίδα Βοήθειας στις Ρυθμίσεις έχει μια πλήρη παρουσίαση όλων όσων κάνει αυτή η έκδοση, και τα περισσότερα στοιχεία ελέγχου φέρουν τη δική τους εξήγηση πίσω από ένα εικονίδιο (i).`,"commands.openPalette":`Άνοιγμα παλέτας εντολών`,"commands.group.general":`Γενικά`,"commands.group.navigation":`Μετάβαση σε`,"commands.goOverview":`Μετάβαση στην Επισκόπηση`,"commands.goDownloads":`Μετάβαση στις Λήψεις`,"commands.goCollector":`Μετάβαση στον Συλλέκτη`,"commands.goInstances":`Μετάβαση στα Στιγμιότυπα`,"commands.goAccounts":`Μετάβαση στους Λογαριασμούς`,"commands.goSettings":`Μετάβαση στις Ρυθμίσεις`,"commands.group.settings":`Ρυθμίσεις`,"commands.group.queue":`Ουρά`,"commands.group.language":`Γλώσσα`,"commands.group.downloads":`Λήψεις`,"commands.group.collector":`Συλλέκτης`,"commands.paletteLabel":`Παλέτα εντολών`,"commands.searchPlaceholder":`Πληκτρολόγησε μια εντολή…`,"commands.noResults":`Καμία εντολή δεν ταιριάζει`,"settings.nav.shortcuts":`Συντομεύσεις`,"settings.shortcuts.subtitle":`Κάθε εντολή με προεπιλεγμένη συντόμευση πληκτρολογίου, ομαδοποιημένη ανά περιοχή εφαρμογής. Άλλαξε μια αντιστοίχιση, ή επανάφερέ την στην προεπιλογή της.`,"settings.shortcuts.empty":`Καμία εντολή δεν έχει ακόμη προεπιλεγμένη συντόμευση.`,"settings.shortcuts.change":`Αλλαγή`,"settings.shortcuts.reset":`Επαναφορά`,"settings.shortcuts.resetAll":`Επαναφορά όλων στις προεπιλογές`,"settings.shortcuts.resetAllConfirmTitle":`Επαναφορά όλων των συντομεύσεων;`,"settings.shortcuts.resetAllConfirmBody":`Κάθε συντόμευση που έχει αλλάξει επιστρέφει στην προεπιλογή της. Αυτό δεν μπορεί να αναιρεθεί.`,"settings.shortcuts.resetAllConfirm":`Επαναφορά όλων`,"settings.shortcuts.captureTitle":`Πάτησε μια νέα συντόμευση για «{name}»`,"settings.shortcuts.captureHint":`Πάτησε έναν συνδυασμό πλήκτρων, ή Escape για ακύρωση.`,"settings.shortcuts.conflict":`Το «{combo}» χρησιμοποιείται ήδη από {command}.`,"settings.shortcuts.key.ctrl":`Ctrl`,"settings.shortcuts.key.alt":`Alt`,"dialog.dontShowAgain":`Να μην ξαναρωτηθεί`,"dialog.dontShowAgainHint":`Την επόμενη φορά θα γίνει αμέσως. Μπορείς να επαναφέρεις την ερώτηση στις Ρυθμίσεις, Εμφάνιση.`,"settings.dialogs.title":`Απενεργοποιημένες ερωτήσεις`,"settings.dialogs.hint":`Επιβεβαιώσεις που έχεις απενεργοποιήσει. Ενεργοποίησέ την ξανά και θα ρωτήσει πάλι.`,"settings.categories.listTitle":`Κατηγορίες`,"settings.categories.listHint":`Μια κατηγορία είναι ένα πακέτο προεπιλογών με ένα όνομα από πάνω: φάκελος, θέση στην ουρά, διακόπτης αποσυμπίεσης, όριο ταχύτητας και ο κανόνας για ένα αρχείο που υπάρχει ήδη. Διαλέγεις το όνομα μία φορά, όταν μπαίνουν οι σύνδεσμοι, αντί να απαντάς αυτές τις πέντε ερωτήσεις για κάθε παρτίδα. Κάθε πλαίσιο που αφήνεις κενό σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη γι’ αυτό και ισχύει η ρύθμιση ένα επίπεδο πιο πάνω, οπότε μια μισογεμάτη κατηγορία αλλάζει μόνο ό,τι συμπλήρωσες. Το πολύ 64 από αυτές, γιατί αυτό εδώ είναι ένα μενού από το οποίο διαλέγεις.`,"settings.categories.name":`Όνομα`,"settings.categories.nameHint":`Πώς λέγεται αυτό το συρτάρι όπου κι αν προσφέρεται. Μετονόμασέ το όσο συχνά θέλεις: το κλειδί από κάτω δεν ακολουθεί, οπότε ό,τι έχει ήδη μπει εδώ μένει εδώ. Μια γραμμή εντελώς χωρίς όνομα χρειάζεται δικό της κλειδί, αλλιώς η αποθήκευση απορρίπτεται ακριβώς με αυτή την αιτιολογία.`,"settings.categories.id":`Κλειδί`,"settings.categories.idHint":`Η σταθερή ταυτότητα στην οποία δείχνει κάθε λήψη που μπαίνει εδώ. Σε μια νέα κατηγορία άφησέ το κενό: ο διακομιστής την παράγει από το όνομα μία φορά, στην αποθήκευση, και ποτέ ξανά. Τα κεφαλαία γίνονται πεζά, γράμματα και ψηφία μένουν, και κάθε άλλη ακολουθία χαρακτήρων γίνεται μία παύλα, οπότε το «Serien & Filme» αποθηκεύεται ως «serien-filme». Το να την αλλάξεις αργότερα δεν είναι μετονομασία, φτιάχνει ένα δεύτερο συρτάρι: οι λήψεις που μπήκαν με το παλιό κλειδί συνεχίζουν να δείχνουν σε ένα κλειδί στο οποίο δεν απαντά κανείς, συμπεριφέρονται ακριβώς σαν λήψεις που δεν μπήκαν ποτέ πουθενά, και επιστρέφουν τη μέρα που θα υπάρξει ξανά κατηγορία με αυτό το κλειδί.`,"settings.categories.dir":`Φάκελος`,"settings.categories.dirHint":`Πού καταλήγει μια λήψη που μπαίνει εδώ. Κενό σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη και ισχύει ο γενικός φάκελος λήψεων. Μπορεί να είναι πρότυπο, όπως /media/serien/<jd:packagename>, και μόνο το κομμάτι πριν από την πρώτη μεταβλητή χρειάζεται να είναι πραγματικός φάκελος. Πρέπει να είναι απόλυτη διαδρομή, αλλιώς η αποθήκευση απορρίπτεται με την αιτιολογία, το ίδιο και όταν αυτό το στιγμιότυπο δεν μπορεί να δημιουργήσει τον φάκελο ή να γράψει μέσα του. Οι υποφάκελοι ανά πακέτο ισχύουν κανονικά από πάνω, οπότε το να μπει μια παρτίδα εδώ δεν τους απενεργοποιεί. Ένας κανόνας Packagizer που ονομάζει δικό του φάκελο κερδίζει αυτόν εδώ, γιατί εκείνος ο κανόνας κοίταξε τον ίδιο τον σύνδεσμο. Και ο φάκελος γράφεται πάνω στη λήψη τη στιγμή που ξεκινά: αν τον αλλάξεις εδώ, μετακομίζει ό,τι δεν έχει ξεκινήσει, και τίποτα από όσα τρέχουν.`,"settings.categories.priorityHint":`Από πού ξεκινά στην ουρά μια λήψη που μπαίνει εδώ. Ψηλότερη τρέχει νωρίτερα. Η «Καμία προτίμηση» είναι πραγματική απάντηση και δεν είναι το ίδιο με την «Προεπιλογή»: η προεπιλογή είναι η μεσαία θέση και θα τραβούσε πάλι προς τα κάτω έναν σύνδεσμο που ένας κανόνας είχε ήδη ανεβάσει, ενώ η καμία προτίμηση τον αφήνει ακριβώς όπως ήρθε. Το εύρος είναι αυτό που δέχεται η ίδια η ουρά, οπότε μια κατηγορία δεν μπορεί να δώσει σε μια λήψη θέση που δεν έχεις τρόπο να αναιρέσεις. Γράφεται μία φορά, τη στιγμή που ο σύνδεσμος μπαίνει σε ετοιμότητα, και ποτέ ξανά, οπότε μια λήψη που έχεις τραβήξει ψηλότερα στη λίστα μένει εκεί που την έβαλες.`,"settings.categories.extractHint":`Αν ένα συμπιεσμένο που έρχεται κάτω από αυτή την κατηγορία αποσυμπιέζεται. Η «Κληρονόμηση» αφήνει την απόφαση στη σελίδα Συμπιεσμένα αρχεία, που δεν είναι το ίδιο με το «Ανενεργό»: το «Ανενεργό» είναι ένα συρτάρι που κρατά επίτηδες τα αρχεία συμπιεσμένα, ένα συρτάρι μουσικής όπου το συμπιεσμένο είναι η ίδια η παράδοση, και αυτό πρέπει να επιβιώνει μιας γενικής ρύθμισης που λέει «αποσυμπίεσε». Ο διακόπτης της ίδιας της λήψης κερδίζει και πάλι αυτόν εδώ, γιατί εκεί ένας κανόνας ή ένας άνθρωπος μίλησε για μία συγκεκριμένη λήψη.`,"settings.categories.speedLimit":`Όριο ταχύτητας (KiB/s, 0 = καμία προτίμηση)`,"settings.categories.speedLimitHint":`Πόσο γρήγορα επιτρέπεται να τραβάει μια λήψη που μπαίνει εδώ. Το 0 σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη και ισχύει το όριο ολόκληρου του στιγμιότυπου. Τίποτα δεν το επιβάλλει ακόμη, και το να το λέμε είναι καλύτερο από μια σελίδα που λέει ψέματα στα κρυφά: αυτό το build έχει ένα φρένο για όλη την εφαρμογή, μοιρασμένο ανάμεσα στα backend, και κανένα μερίδιο ανά λήψη μέσα στο οποίο θα μπορούσε να γραφτεί αυτός ο αριθμός. Η τιμή αποθηκεύεται και επιλύεται σωστά, και μετά κανείς δεν κάνει τίποτα με αυτήν. Προσφέρεται από τώρα ώστε η ρύθμιση να μην αλλάξει σχήμα αργότερα, όταν ο κόσμος θα έχει ήδη αρχεία στον δίσκο.`,"settings.categories.collision":`Αν υπάρχει ήδη αρχείο`,"settings.categories.collisionHint":`Τι γίνεται όταν το αρχείο που πάει να γράψει μια λήψη από αυτή την κατηγορία υπάρχει ήδη. Η «Κληρονόμηση» παίρνει την απάντηση ολόκληρου του στιγμιότυπου από τις ρυθμίσεις λήψεων, και το κενό σημαίνει πραγματικά κληρονόμηση: δεν είναι ένα σιωπηλό «διατήρηση και των δύο», οπότε μια κατηγορία χωρίς προτίμηση δεν μπορεί να υπερισχύσει ενός στιγμιότυπου ρυθμισμένου σε παράλειψη. Η «Διατήρηση και των δύο» γράφει δίπλα ως «όνομα (2)», η «Παράλειψη» αφήνει αυτό που υπάρχει και δεν γράφει τίποτα, η «Αντικατάσταση» το κόβει και γράφει από πάνω. Δεν υπάρχει επίτηδες «ρώτησέ με»: δεν θα ήταν κανείς εκεί να απαντήσει, και η λήψη θα καθόταν για πάντα στην ουρά χωρίς τίποτα να λέει γιατί.`,"settings.downloads.diskReserve":`Περιθώριο ανά λήψη (GiB)`,"settings.downloads.diskReserveHint":`Χώρος που μένει ελεύθερος επιπλέον από όσα έχει ακόμη να φέρει μια λήψη. Μια λήψη ξεκινά μόνο αν χωρούν τα byte που της απομένουν συν αυτό το ποσό, οπότε έτσι απορρίπτεται μόνο μια λήψη που έτσι κι αλλιώς θα άδειαζε τον δίσκο. Είναι το μόνο από τα τρία που έρχεται αναμμένο, στο 0,5. Το 0 το σβήνει και αφήνει μία μόνο λήψη να γεμίσει τον δίσκο μέχρι το τελευταίο byte. Ένα αρχείο του οποίου το μέγεθος δεν το λέει ο πάροχος εξαιρείται μέχρι να έρθει το μέγεθος, συνήθως δευτερόλεπτα μετά την εκκίνηση.`,"settings.downloads.diskLowSpace":`Να μην ξεκινά τίποτα κάτω από (GiB)`,"settings.downloads.diskLowSpaceHint":`Ελεύθερος χώρος κάτω από τον οποίο δεν ξεκινά τίποτα καινούριο, όσο μεγάλο κι αν είναι και ακόμη κι όταν το μέγεθος είναι άγνωστο. Το 0 είναι σβηστό, και έτσι έρχεται: ο σωστός αριθμός εξαρτάται εντελώς από τον δίσκο, και ένα gigabyte δεν είναι τίποτα σε έναν πίνακα δεκαέξι terabyte και είναι το ένα τρίτο μιας κάρτας μνήμης. Οι λήψεις στην ουρά απλώς περιμένουν και ξεκινούν πάλι μόνες τους μόλις ελευθερωθεί χώρος. Αν βάλεις την τιμή διακοπής από κάτω ψηλότερα από αυτήν εδώ, αυτή εδώ ανεβαίνει μαζί της στην αποθήκευση, γιατί το «σταμάτα τα πάντα κάτω από X» σημαίνει ήδη «μην ξεκινάς τίποτα κάτω από X».`,"settings.downloads.diskCriticalSpace":`Διακοπή των πάντων κάτω από (GiB)`,"settings.downloads.diskCriticalSpaceHint":`Ελεύθερος χώρος κάτω από τον οποίο οι λήψεις που ήδη τρέχουν σταματούν και επιστρέφουν στην ουρά, με έλεγχο κάθε δεκαπέντε δευτερόλεπτα. Το 0 είναι σβηστό, και έτσι έρχεται. Αυτό κοστίζει περισσότερο από την τιμή εκκίνησης παραπάνω: μια μεταφορά που δεν μπορεί να συνεχιστεί χάνει ό,τι είχε ήδη φέρει, οπότε κράτησέ το για δίσκο που πραγματικά κοντεύει να γεμίσει. Αν το βάλεις ψηλότερα από την τιμή εκκίνησης, η τιμή εκκίνησης ανεβαίνει μαζί κατά την αποθήκευση. Ο αριθμός που γράφεις εδώ δεν χαμηλώνει ποτέ στα κρυφά.`,"settings.feeds.title":`Συνδρομές σε ροές`,"settings.feeds.titleHint":`Ροές RSS και Atom που ακολουθεί αυτό το στιγμιότυπο. Καθεμία ανακτάται με δικό της χρονόμετρο, και μια νέα καταχώριση πηγαίνει στον συλλέκτη ακριβώς σαν επικολλημένος σύνδεσμος, οπότε ισχύουν κανονικά το φίλτρο συνδέσμων, η σάρωση σελίδων και ο Packagizer. Η πρώτη ανάκτηση μιας νέας συνδρομής δεν προσθέτει απολύτως τίποτα: ό,τι κουβαλά η ροή εκείνη τη στιγμή σημειώνεται ως ήδη γνωστό, ώστε να μη σου πέσει μονομιάς όλο το παλιό αρχείο ενός εκδότη. Προστίθεται μόνο ό,τι εμφανιστεί από εκεί και πέρα. Κενή λίστα σημαίνει ότι δεν ακολουθείται καμία ροή.`,"settings.feeds.url":`Διεύθυνση ροής`,"settings.feeds.urlHint":`Η διεύθυνση του εγγράφου RSS ή Atom, μόνο http ή https. Είναι επίσης αυτό που ταυτοποιεί τη συνδρομή: αν την αλλάξεις έχεις άλλη συνδρομή, μια που δεν ξέρει πια ποιες καταχωρίσεις έχει ήδη προσθέσει, οπότε ακόμη και η διόρθωση ενός τυπογραφικού λάθους την κάνει να διαβάσει τη ροή σαν καινούρια. Μια διεύθυνση που δεν διαβάζεται, ή που δεν ονομάζει κόμβο, ρίχνει ολόκληρη την αποθήκευση των ρυθμίσεων με τον αριθμό της γραμμής, αντί να εξαφανιστεί στα κρυφά. Δύο γραμμές με την ίδια διεύθυνση συγχωνεύονται στην πρώτη κατά την αποθήκευση.`,"settings.feeds.interval":`Έλεγχος κάθε (λεπτά)`,"settings.feeds.intervalHint":`Πόσο μένει ήσυχη αυτή η ροή ανάμεσα σε δύο ανακτήσεις. Άφησέ το στο 0 και ισχύει το συνηθισμένο ένα τέταρτο της ώρας. Ανάμεσα σε 1 και 10080, δηλαδή μία εβδομάδα, ο αριθμός παίρνεται όπως τον έγραψες. Κάτω από 1 ο διακομιστής τον ανεβάζει στο 1 χωρίς να το πει, πάνω από μία εβδομάδα τον ρίχνει πίσω στη μία εβδομάδα, και ο διορθωμένος αριθμός εμφανίζεται στο πεδίο μόλις γυρίσει η αποθήκευση. Το ένα λεπτό είναι το κατώτατο όριο, γιατί κάθε ανάκτηση είναι ένα αίτημα στον διακομιστή κάποιου άλλου, και ένας γρηγορότερος ρυθμός είναι ο τρόπος με τον οποίο ένα στιγμιότυπο τρώει αποκλεισμό της διεύθυνσής του. Η πρώτη ανάκτηση γίνεται αμέσως μετά την αποθήκευση και όχι μετά την πρώτη αναμονή, και ένα μικρότερο διάστημα ισχύει αμέσως αντί για το τέλος της αναμονής που μόλις μίκρυνες.`,"settings.feeds.filter":`Φίλτρο τίτλων`,"settings.feeds.filterHint":`Μια κανονική έκφραση που δοκιμάζεται πάνω στον τίτλο κάθε καταχώρισης, δηλαδή στο όνομα με το οποίο η καταχώριση εμφανίζεται και στον συλλέκτη. Άφησέ το κενό για να παίρνεις ό,τι δημοσιεύει η ροή. Αποφασίζει τι κατεβαίνει, όχι τι μένει στη μνήμη: οι καταχωρίσεις που διώχνει σημειώνονται έτσι κι αλλιώς ως ιδωμένες, οπότε ένα φίλτρο που θα ανοίξεις τον επόμενο μήνα φέρνει μόνο ό,τι εμφανιστεί από τότε και όχι όλο το τρέχον παράθυρο της ροής. Ένα μοτίβο που δεν είναι έγκυρο ρίχνει την αποθήκευση των ρυθμίσεων με τον αριθμό της γραμμής. Δεν πετιέται ποτέ για λογαριασμό σου, γιατί ένα πεταμένο φίλτρο είναι μια συνδρομή που μαζεύει σιωπηλά ολόκληρη τη ροή.`,"settings.feeds.dir":`Φάκελος λήψεων`,"settings.feeds.dirHint":`Πού καταλήγουν οι λήψεις αυτής της συνδρομής. Άφησέ το κενό και πηγαίνουν εκεί που πηγαίνουν κανονικά οι λήψεις. Ο φάκελος γράφεται πάνω στον σύνδεσμο αφού αυτός συλλεχθεί, όπως ακριβώς και ο φάκελος ενός αρχείου .crawljob που αφήνεις στον παρακολουθούμενο φάκελο, οπότε υπερισχύει ενός κανόνα Packagizer που διάλεξε φάκελο. Οι μεταβλητές διαδρομής δουλεύουν εδώ, και ο επιλογέας φακέλων κρατά το υπόλοιπο πρότυπο. Σε αντίθεση με τον κύριο φάκελο λήψεων, αυτός εδώ δεν ελέγχεται κατά την αποθήκευση: ένας φάκελος που δεν μπορεί να δημιουργηθεί φαίνεται μόνο όταν φτάσει πραγματικά μια καταχώριση, και τότε η λήψη κρατά τον κανονικό φάκελο.`,"settings.feeds.priority":`Προτεραιότητα`,"settings.feeds.priorityHint":`Με ποια προτεραιότητα ξεκινά κάθε λήψη από αυτή τη ροή. Άφησέ το στο «Χωρίς ορισμό» και η συνδρομή δεν λέει απολύτως τίποτα, οπότε αυτές οι λήψεις μπαίνουν στην ουρά όπως όλες οι άλλες. Οτιδήποτε άλλο γράφεται πάνω στον σύνδεσμο αφού αυτός συλλεχθεί, οπότε υπερισχύει ενός κανόνα Packagizer που όρισε προτεραιότητα. Ψηλότερη τρέχει νωρίτερα, αναδιατάσσει ό,τι περιμένει ακόμη και δεν στέλνει ποτέ πίσω στην ουρά μια λήψη που τρέχει. Αν ο φάκελος παραπάνω δεν μπορεί να χρησιμοποιηθεί, δεν εφαρμόζεται ούτε η προτεραιότητα, γιατί τα δύο γράφονται μαζί.`,"settings.hostRules.title":`Εξαιρέσεις ανά πάροχο`,"settings.hostRules.titleHint":`Μία γραμμή για κάθε πάροχο που χρειάζεται άλλους αριθμούς από αυτούς παραπάνω. Ένας πάροχος χωρίς γραμμή κρατά τις γενικές τιμές, οπότε ένας άδειος πίνακας δεν αλλάζει τίποτα. Μια γραμμή καλύπτει τον κόμβο που ονομάζεις και κάθε υποτομέα του: το rapidgator.net καλύπτει και το rg.rapidgator.net, και δεν καλύπτει το notrapidgator.net. Αν δύο γραμμές ταιριάζουν στον ίδιο σύνδεσμο, κερδίζει το μεγαλύτερο όνομα κόμβου.`,"settings.hostRules.pattern":`Πάροχος`,"settings.hostRules.patternHint":`Ο κόμβος για τον οποίο μιλά αυτή η γραμμή, για παράδειγμα rapidgator.net. Αποθηκεύεται με πεζά, χωρίς αρχικό «*.» και χωρίς τελεία στο τέλος, οπότε το «*.Rapidgator.net.» και το «rapidgator.net» είναι μία και η αυτή γραμμή. Μια γραμμή με κενό κόμβο πετιέται κατά την αποθήκευση, χωρίς μήνυμα.`,"settings.hostRules.maxPerHost":`Ταυτόχρονες λήψεις από αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.maxPerHostHint":`Αντικαθιστά το «Ταυτόχρονες λήψεις ανά πάροχο» για αυτόν τον έναν πάροχο, προς τα πάνω όπως και προς τα κάτω: το 8 εδώ δουλεύει σε στιγμιότυπο του οποίου η γενική τιμή είναι 2. Δεν σε βγάζει ποτέ πάνω από τις «Ταυτόχρονες λήψεις» συνολικά, γιατί εκείνο το σύνολο ελέγχεται πρώτο και συμπληρώνεται νωρίτερα. Το 0 σημαίνει ότι αυτή η γραμμή δεν λέει τίποτα γι’ αυτό και ισχύει ο γενικός αριθμός. Πάνω από 64 ο διακομιστής αποθηκεύει 64.`,"settings.hostRules.chunks":`Συνδέσεις ανά λήψη από αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.chunksHint":`Αντικαθιστά το «Συνδέσεις ανά λήψη» για αυτόν τον κόμβο, και σε αντίθεση με ένα όριο που αναφέρει μια υπηρεσία για κάποιον κόμβο, επιτρέπεται να είναι ΥΨΗΛΟΤΕΡΟ από τον γενικό αριθμό. Δύο πράγματα τον κόβουν παρ’ όλα αυτά: μια μεμονωμένη λήψη ή ένας κανόνας που όρισε δικό του αριθμό υπερισχύει αυτής της γραμμής, και μια υπηρεσία που ξέρει ότι ο κόμβος επιτρέπει μόνο δύο ξαναρίχνει τα αισιόδοξα οκτώ στα δύο. Το 0 σημαίνει ότι ισχύει ο γενικός αριθμός. Πάνω από 16 δεν ανοίγει ποτέ η μηχανή, ό,τι κι αν γράψεις.`,"settings.hostRules.retryDelay":`Αναμονή πριν από την πρώτη νέα προσπάθεια, σε δευτερόλεπτα (0 = το επίπεδο από πάνω)`,"settings.hostRules.retryDelayHint":`Πόσο μένει ήσυχη μια αποτυχημένη λήψη από αυτόν τον πάροχο πριν δοκιμαστεί ξανά. Από εκεί και πέρα η αναμονή διπλασιάζεται μέχρι το ανώτατο όριο από κάτω. Το 0 δεν σημαίνει «καμία αναμονή», αλλά δίνει την ερώτηση παρακάτω: πρώτα στον κανόνα για αυτό το είδος σφάλματος, μετά στην αναμονή ολόκληρου του στιγμιότυπου, και τελευταία στα ενσωματωμένα 15 δευτερόλεπτα. Βάλε μία ώρα εδώ για πάροχο που αποκλείει για μία ώρα, αντί να ξοδεύεις έξι απορριφθείσες προσπάθειες μέσα σε δέκα λεπτά και να τα παρατάς πριν τελειώσει ο αποκλεισμός.`,"settings.hostRules.retryMax":`Μεγαλύτερη αναμονή ανάμεσα σε προσπάθειες, σε δευτερόλεπτα (0 = το επίπεδο από πάνω)`,"settings.hostRules.retryMaxHint":`Εδώ σταματά ο διπλασιασμός. Το 0 δίνει την ερώτηση παρακάτω όπως και η αναμονή από πάνω και καταλήγει στα ενσωματωμένα 10 λεπτά. Πρόσεξε αυτό εδώ: ένα ανώτατο όριο ΚΑΤΩ από την πρώτη αναμονή δεν χρησιμοποιείται όπως το έγραψες. Η εφαρμογή το ανεβάζει σιωπηλά σε εκείνη την αναμονή, γιατί αλλιώς ο αριθμός που έβαλες ως αναμονή δεν θα ήταν ποτέ η αναμονή. Η τιμή σου μένει έτσι κι αλλιώς στο πλαίσιο, οπότε ένα 60 εδώ δίπλα σε ένα 3600 από πάνω εξακολουθεί να διαβάζεται ως 60 και συμπεριφέρεται ως 3600.`,"settings.hostRules.retryTries":`Προσπάθειες για αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.retryTriesHint":`Πόσες φορές δοκιμάζεται καν μια αποτυχημένη λήψη από αυτόν τον πάροχο. Το 0 δεν σημαίνει «ποτέ»: δίνει την ερώτηση στον κανόνα για αυτό το είδος σφάλματος και μετά στις «Αυτόματες επαναλήψεις» παραπάνω. Χρησιμοποίησέ το για να δώσεις δέκα προσπάθειες σε έναν ασταθή πάροχο χωρίς να ανεβάσεις τον αριθμό για όλα τα υπόλοιπα. Καμία γραμμή δεν επιτρέπεται να ζητήσει πάνω από 20, το ίδιο ανώτατο όριο που έχει και ο γενικός αριθμός.`,"settings.hostRules.never":`Ποτέ νέα προσπάθεια σε αυτόν τον πάροχο`,"settings.hostRules.neverHint":`Μια λήψη από αυτόν τον πάροχο που αποτυγχάνει μπαίνει οριστικά στην άκρη, χωρίς κανένα χρονόμετρο οπλισμένο. Αυτή είναι δική της τελική κατάσταση και όχι «απέτυχε μετά από τρεις προσπάθειες», και η λίστα τα δείχνει διαφορετικά: αν ανεβάσεις τον αριθμό προσπαθειών οπουδήποτε, φτιάχνει το δεύτερο και δεν κάνει τίποτα για αυτό εδώ. Ο διακόπτης μπορεί μόνο να ΑΝΑΨΕΙ από κάποιο επίπεδο. Το σβηστό εδώ δεν αναιρεί ένα «ποτέ» που έχει ήδη ορίσει ο κανόνας για αυτό το είδος σφάλματος, οπότε μια γραμμή μπορεί να είναι σβηστή και η λήψη να μην ξαναδοκιμαστεί ποτέ.`,"settings.advanced.mirrorPolicy":`Πότε δύο σύνδεσμοι μετρούν ως το ίδιο αρχείο`,"settings.advanced.mirrorPolicyHint":`Αποφασίζει ποιος δεύτερος σύνδεσμος συγχωνεύεται ως αντίγραφο ενός που είναι ήδη στη λίστα. Το «Ποτέ» δεν συγχωνεύει απολύτως τίποτα. Το «Ίδιο όνομα αρχείου» πιάνει την ίδια κυκλοφορία επικολλημένη από πέντε παρόχους, ακόμη κι όταν αυτοί διαφωνούν για το μέγεθος, αλλά ενώνει επίσης δύο άσχετα αρχεία που λέγονται και τα δύο setup.exe. Το «Ίδιο όνομα και ίδιο μέγεθος», η προεπιλογή, θέλει να συμφωνούν και τα δύο, οπότε ένας σύνδεσμος του οποίου το μέγεθος δεν το έχει λύσει ακόμη κανείς δεν ενώνεται ποτέ. Το «Ίδιο άθροισμα ελέγχου» ενώνει μόνο με απόδειξη και χάνει σχεδόν τα πάντα, γιατί ένα άθροισμα ελέγχου σπάνια είναι γνωστό πριν φτάσει το αρχείο. Η ίδια διεύθυνση δύο φορές απορρίπτεται πάντα, ό,τι κι αν διαλέξεις, και τα μέρη ενός χωρισμένου συμπιεσμένου δεν ενώνονται ποτέ μεταξύ τους.`,"settings.advanced.keepMirrors":`Διατήρηση του αντιγράφου αντί για απόρριψη`,"settings.advanced.keepMirrorsHint":`Σβηστό, ένα αντίγραφο που συγχωνεύτηκε χάνεται στην επόμενη επανεκκίνηση. Αναμμένο, στήνεται ως δεύτερη γραμμή δίπλα στη λήψη που αντιγράφει, κρατιέται πίσω και επισημαίνεται ως αντίγραφό της. Από μόνο του δεν ξεκινά τίποτα: η γραμμή περιμένει μέχρι να την αποδεσμεύσεις με το χέρι, ή μέχρι να την αποδεσμεύσει ο διακόπτης από κάτω. Το τίμημα του να το αφήσεις αναμμένο είναι μια γραμμή παραπάνω για κάθε αντίγραφο, σε μια λίστα που είναι ήδη μεγάλη, γι’ αυτό η προεπιλογή είναι σβηστό. Ένα ακριβές διπλότυπο δεν κρατιέται ποτέ, ό,τι κι αν λέει αυτό εδώ.`,"settings.advanced.mirrorFailover":`Μετάβαση στο αντίγραφο όταν πεθάνει η λήψη`,"settings.advanced.mirrorFailoverHint":`Δεν κάνει τίποτα όσο ο διακόπτης από πάνω είναι σβηστός, γιατί τότε δεν υπάρχει παρκαρισμένο αντίγραφο για αποδέσμευση. Αναμμένο, μια λήψη που έχει αποτύχει οριστικά παραδίδει τον φάκελό της, το πακέτο της και την προτεραιότητά της στο παρκαρισμένο αντίγραφο, και εκείνο ξεκινά. Είναι σβηστό από προεπιλογή, γιατί η αποδέσμευση ξεκινά μεταφορά από πάροχο που δεν διάλεξες, με το τέμπο εκείνου του πάροχου, ίσως και με λογαριασμό που δεν έχεις, και τίποτα εδώ δεν μπορεί να σε ρωτήσει πρώτα. Ένας γεμάτος δίσκος και μια λήψη που ακύρωσες δεν το πυροδοτούν ποτέ. Η αποτυχημένη γραμμή μένει στη λίστα με τον δικό της λόγο ανέπαφο, και το αντίγραφο ξεκινά με φρέσκο μετρητή προσπαθειών αντί να κληρονομήσει τον νεκρό.`,"settings.advanced.onOffline":`Σύνδεσμοι που είναι ήδη γνωστοί ως μη διαθέσιμοι`,"settings.advanced.onOfflineHint":`Τι γίνεται με έναν σύνδεσμο που ένας έλεγχος έχει ήδη βρει χαμένο, τη στιγμή που μια παρτίδα φεύγει από τον συλλέκτη. Το «Πρόσθεσέ τον έτσι κι αλλιώς» τον ξεκινά σαν να μην είχε ταιριάξει τίποτα, και είναι η μόνη απάντηση που δεν χάνει ποτέ σύνδεσμο εξαιτίας ενός λανθασμένου σήματος. Το «Άφησέ τον στον συλλέκτη», η προεπιλογή, δεν αλλάζει τίποτα άλλο πάνω του, οπότε μια νέα επιβεβαίωση αργότερα με άλλη απάντηση τον φτάνει κανονικά. Το «Πέταξέ τον» είναι η μόνη απάντηση εδώ που σβήνει κάτι. Το «Ρώτα με» ρωτά μόνο όταν επιβεβαιώνεις με το χέρι: η αυτόματη επιβεβαίωση, ο παρακολουθούμενος φάκελος και το Click'n'Load δεν έχουν κανέναν να απαντήσει, οπότε γι’ αυτούς πέφτει πίσω στο να μείνει ο σύνδεσμος στον συλλέκτη. Μια μεμονωμένη παρτίδα μπορεί να φέρει δική της απάντηση και να υπερισχύσει αυτής εδώ.`,"settings.advanced.reclaimTrust":`Πότε ένα αρχείο που βρίσκεται ήδη στον δίσκο μετρά ως η λήψη`,"settings.advanced.reclaimTrustHint":`Χρησιμοποιείται από το πέρασμα που ψάχνει για ήδη ολοκληρωμένα αρχεία πριν κατέβει οτιδήποτε, και που το ξεκινάς εσύ με το χέρι: δεν τρέχει ποτέ στην εκκίνηση, γιατί σε δέκα χιλιάδες εργασίες θα ήταν ένα πέρασμα του δίσκου μπροστά από μια ουρά που δεν υπάρχει ακόμη. Το «Άθροισμα ελέγχου που ταιριάζει» κλείνει μια εργασία μόνο με άθροισμα ελέγχου που επαληθεύτηκε, που είναι τίμιο και δεν κάνει τίποτα για τα πολλά αρχεία που έρχονται χωρίς δημοσιευμένο hash. Η «Μια καταγραφή ότι αυτή η λήψη το έγραψε», η προεπιλογή, δέχεται επιπλέον το ιστορικό αυτού του στιγμιότυπου, όταν αυτό λέει ότι ολοκλήρωσε αρχείο με ακριβώς αυτό το όνομα και ακριβώς αυτό το μήκος. Το «Το σωστό όνομα και το σωστό μέγεθος» δέχεται ένα αρχείο σε πλήρες μήκος χωρίς τίποτα άλλο από πίσω, και σε αυτό το build είναι παγίδα: η βιβλιοθήκη λήψεων δημιουργεί το αρχείο στο πλήρες τελικό του μέγεθος πριν φτάσει το πρώτο byte, οπότε μια μεταφορά που πέθανε στο δύο τοις εκατό φαίνεται ολοκληρωμένη. Ένα πιο κοντό αρχείο διαβάζεται πάντα ως αρχή, ένα άθροισμα ελέγχου που διαφωνεί κερδίζει πάντα, και τίποτα σε αυτό το πέρασμα δεν σβήνει, δεν μετακινεί και δεν αντικαθιστά τίποτα.`,"settings.advanced.retryTries":`Προσπάθειες ανά είδος σφάλματος`,"settings.advanced.retryTriesHint":`Πόσες προσπάθειες παίρνει μια λήψη όταν απέτυχε ακριβώς για αυτόν τον λόγο. Το 0 σημαίνει καμία άποψη και παίρνει στη θέση του τον γενικό αριθμό επαναλήψεων από τη σελίδα Λήψεις, και αυτό λέει κάθε γραμμή εδώ μέχρι να γράψεις κάτι μέσα της. Ένας κανόνας για έναν πάροχο υπερισχύει αυτού εδώ, και αυτό εδώ υπερισχύει του γενικού αριθμού, και τα τρία επιλύονται πεδίο προς πεδίο, οπότε το να γράψεις εδώ αριθμό προσπαθειών δεν φιμώνει και μια αναμονή που ορίστηκε αλλού. Μια αποθηκευμένη τιμή πάνω από 20 κόβεται στο 20 και μια αρνητική γίνεται 0. Η περίπτωση για την οποία υπάρχει αυτό είναι ένας πάροχος που αποκλείει για μία ώρα: έξι προσπάθειες μέσα σε δέκα λεπτά είναι έξι αρνήσεις, και εκείνη που θα είχε πετύχει δεν γίνεται ποτέ.`,"settings.downloads.workDir":`Φάκελος εργασίας`,"settings.downloads.workDirHint":`Πού γράφεται μια λήψη όσο ακόμη έρχεται. Το ολοκληρωμένο αρχείο μετακινείται μετά στον φάκελο λήψεων, αφού τελειώσουν το άθροισμα ελέγχου και τυχόν αποσυμπίεση, οπότε εκεί δεν φαίνεται ποτέ κάτι μισοτελειωμένο. Άφησέ το κενό και οι λήψεις γράφονται κατευθείαν στον προορισμό τους, όπως γίνεται σήμερα. Όρισέ το όταν κάτι άλλο παρακολουθεί τον φάκελο λήψεων: ο mover του Unraid παίρνει ένα μισό αρχείο από την cache και το αντιγράφει στο array, και ένας σαρωτής βιβλιοθήκης προσθέτει ένα ημιτελές βίντεο, αποτυγχάνει μία φορά να το παίξει και δεν ξανακοιτάζει ποτέ. Μία σταθερή απόλυτη διαδρομή, χωρίς μεταβλητές: κάθε λήψη με τον ίδιο προορισμό μοιράζεται αυτόν τον φάκελο, και ένα πρότυπο θα σκόρπιζε τα μέρη ενός πολύτομου συμπιεσμένου. Μια διαδρομή που δεν είναι απόλυτη πετιέται κατά την αποθήκευση. Τα torrent και οι λήψεις που φέρνει άλλο πρόγραμμα δεν τον χρησιμοποιούν ποτέ.`,"settings.archives.moveTo":`Μετακίνηση των αποσυμπιεσμένων αρχείων σε`,"settings.archives.moveToHint":`Πού μετακινούνται τα αποσυμπιεσμένα αρχεία μόλις τελειώσει η αποσυμπίεση. Άφησέ το κενό και μένουν εκεί όπου αποσυμπιέστηκαν. Δεν είναι ένα δεύτερο «Αποσυμπίεση σε»: εκεί γράφει ο αποσυμπιεστής, οπότε μια μισοτελειωμένη κυκλοφορία κάθεται σε εκείνον τον προορισμό όσο τρέχει. Εδώ τα αρχεία μετακινούνται μετά, οπότε στον στόχο δεν φαίνεται ποτέ κάτι ημιτελές. Και μετακινείται το ΠΕΡΙΕΧΟΜΕΝΟ, όχι ο φάκελος της κυκλοφορίας, οπότε το «Show.S01.COMPLETE.WEB/ep01.mkv» φτάνει ως «ep01.mkv», χωρίς τον φάκελο που δεν ζήτησε καμία βιβλιοθήκη. Οι μεταβλητές επιτρέπονται εδώ. Ένας κανόνας Packagizer που όρισε φάκελο για έναν συγκεκριμένο σύνδεσμο κερδίζει αυτό εδώ.`,"settings.downloads.collision":`Αν το αρχείο υπάρχει ήδη`,"settings.downloads.collisionHint":`Τι κάνει μια λήψη όταν το όνομα που θέλει είναι ήδη πιασμένο στον φάκελο προορισμού. Η «Διατήρηση και των δύο» γράφει δίπλα το όνομα (2).ext, η «Παράλειψη» αφήνει το αρχείο που υπάρχει και δεν ξεκινά καν τη λήψη, η «Αντικατάσταση» το αντικαθιστά και είναι η μόνη από τις τρεις που μπορεί να σου χαλάσει αρχείο που είχες ήδη. Αποφασίζεται εκ των προτέρων, γιατί δεν κάθεται κανείς μπροστά στον διακομιστή για να ρωτηθεί. Μόνο στον ενσωματωμένο downloader μπορείς να πεις ποιο όνομα να γράψει: ένας σύνδεσμος που παραδίδεται στο JDownloader, στο TorBox ή στο yt-dlp ονομάζει μόνος του το αρχείο του, οπότε για αυτούς η «Παράλειψη» είναι η μόνη απάντηση που φτάνει καν στο αρχείο.`,"settings.downloads.collisionAttempts":`Το πολύ τόσα αριθμημένα ονόματα`,"settings.downloads.collisionAttemptsHint":`Αυτό το χρησιμοποιεί μόνο η «Διατήρηση και των δύο». Μετράει προς τα πάνω όνομα (2), όνομα (3) και ούτω καθεξής, και τα παρατά με σφάλμα μόλις δοκιμάσει τόσα. Το 0 σημαίνει το ενσωματωμένο όριο των 1000, όχι «χωρίς όριο»: ένας φάκελος που γεμίζει με χίλια αντίγραφα του ίδιου ονόματος είναι λάθος κάπου αλλού, συνήθως ένας παρακολουθούμενος φάκελος που διαβάζει ξανά την ίδια λίστα, και ένας μετρητής που δεν σταματά ποτέ το κάνει κατάλογο που δεν ανοίγει κανείς. Οτιδήποτε πάνω από 1000 γυρίζει πίσω στα 1000 κατά την αποθήκευση.`,"settings.downloads.autoConfirmDelay":`Αναμονή πριν από την αυτόματη επιβεβαίωση (δευτερόλεπτα)`,"settings.downloads.autoConfirmDelayHint":`Πόσο κάθεται μια νέα παρτίδα στον συλλέκτη πριν επιβεβαιωθεί μόνη της, δηλαδή το παράθυρό σου για να την κοιτάξεις, να πετάξεις έναν σύνδεσμο ή να διορθώσεις τον φάκελο. Το 0 επιβεβαιώνει τη στιγμή που φτάνει η παρτίδα, όπως γίνεται σήμερα. Δεν κάνει απολύτως τίποτα αν δεν είναι ενεργό το «Άμεση έναρξη των συνδέσμων που προστίθενται», στα Γενικά. Μία ημέρα είναι το ανώτατο όριο: αυτή η αντίστροφη μέτρηση είναι φτιαγμένη για να διαβάζεται όσο τρέχει, και οτιδήποτε μεγαλύτερο είναι ένα ψηφίο που ξέφυγε και όχι προτίμηση. Ένας αρνητικός αριθμός γίνεται 0 κατά την αποθήκευση.`,"settings.downloads.onDupes":`Σύνδεσμοι που έχεις ήδη`,"settings.downloads.onDupesHint":`Τι γίνεται με έναν σύνδεσμο που φεύγει από τον συλλέκτη και βρίσκεται ήδη στη λίστα σου. Το «Πρόσθεσέ τον έτσι κι αλλιώς» τον αντιμετωπίζει σαν κάθε άλλον σύνδεσμο. Το «Άφησέ τον στον συλλέκτη» δεν τον επιβεβαιώνει και δεν αλλάζει τίποτα άλλο πάνω του, οπότε μια νέα επιβεβαίωση αργότερα τον πιάνει κανονικά. Το «Πέταξέ τον» τον βγάζει από τη λίστα και είναι η μόνη απάντηση που πετάει κάτι, γι’ αυτό δεν είναι ποτέ η προεπιλογή. Το «Ρώτα με» ρωτά μόνο όταν έχει πατήσει πραγματικά κάποιος άνθρωπος Επιβεβαίωση: η αντίστροφη μέτρηση, ο παρακολουθούμενος φάκελος και το Click'n'Load δεν έχουν κανέναν να ρωτήσουν, οπότε γι’ αυτούς πέφτει πίσω στο να μείνει ο σύνδεσμος στον συλλέκτη. Μια μεμονωμένη παρτίδα μπορεί να υπερισχύσει αυτού. Ό,τι ορίζεις εδώ ισχύει όταν δεν το κάνει.`,"settings.downloads.addAtTop":`Οι νέοι επιβεβαιωμένοι σύνδεσμοι μπαίνουν μπροστά στην ουρά`,"settings.downloads.addAtTopHint":`Μια παρτίδα που φεύγει από τον συλλέκτη παίζει επόμενη, αντί να μπει στην ουρά πίσω από όλα όσα ήδη περίμεναν. Μετακινείται μέσα στη δική της βαθμίδα προτεραιότητας, ακριβώς εκεί που θα την έβαζε και η «Μετακίνηση στην κορυφή», οπότε μια λήψη στην οποία έδωσες υψηλότερη προτεραιότητα τρέχει και πάλι πρώτη. Σβηστό, οι σύνδεσμοι μπαίνουν στο τέλος της ουράς, όπως γίνεται σήμερα. Ισχύει όπως κι αν επιβεβαιώθηκε η παρτίδα: με το χέρι, από την αντίστροφη μέτρηση ή από τον παρακολουθούμενο φάκελο.`,"settings.stall.enabled":`Σήμανση των λήψεων που σταματούν να προχωρούν`,"settings.stall.enabledHint":`Μια νεκρή σύνδεση δεν αποτυγχάνει και δεν σταματά. Η γραμμή λέει ακόμη ότι τρέχει, με 0 B/s, κρατά τη θέση της στις λήψεις, και το πρωί κάθεται εκεί με το ίδιο τρία τοις εκατό που είχε τα μεσάνυχτα. Με αυτό αναμμένο, μια μεταφορά που δεν έχει κουνήσει byte για τον χρόνο που ορίζεται από κάτω σημειώνεται στη λίστα ως κολλημένη. Η σήμανση δεν αλλάζει τίποτα στην ίδια τη λήψη, λέει μόνο αυτό που ισχύει ήδη. Σβηστό σημαίνει ότι δεν σημειώνεται ποτέ τίποτα.`,"settings.stall.timeout":`Χρόνος χωρίς byte (δευτερόλεπτα)`,"settings.stall.timeoutHint":`Πόσο επιτρέπεται σε μια λήψη που τρέχει να μην κουνά κανένα byte πριν μετρήσει ως κολλημένη. Τα 60 δευτερόλεπτα είναι η μικρότερη τιμή που υπάρχει, και οτιδήποτε χαμηλότερο ανεβαίνει στα 60 κατά την αποθήκευση: κάτω από ένα λεπτό, μια αλλαγή κομματιού, μια επανασύνδεση ή η αναμονή που επιβάλλει ο ίδιος ο πάροχος μοιάζουν ακριβώς με νεκρή σύνδεση, οπότε ένας μικρότερος χρόνος δεν θα έβρισκε κολλήματα, θα σημείωνε ολόκληρη την ουρά. Το ανώτατο όριο είναι μία ημέρα (86400 δευτερόλεπτα). Ένας σύνδεσμος που περιμένει captcha δεν μετράει ποτέ ως κολλημένος, και το ρολόι του ξαναρχίζει από το μηδέν μόλις απαντηθεί το captcha.`,"settings.stall.restart":`Επανεκκίνηση κολλημένης λήψης από την αρχή`,"settings.stall.restartHint":`Βάζει μια σημειωμένη λήψη πίσω στην ουρά και την ξεκινά από την αρχή. Έτσι πετιούνται τα byte που είχε ήδη φέρει η κολλημένη προσπάθεια, ακριβώς όπως σε μια επανεκκίνηση με το χέρι, και γι’ αυτό είναι δικός του διακόπτης και μένει σβηστός μέχρι να τον ανάψεις: η σήμανση είναι πληροφορία, η επανεκκίνηση είναι απόφαση. Τα torrent δεν ξεκινούν ποτέ ξανά από εδώ, ό,τι κι αν λέει αυτό, γιατί ένα torrent που δεν βρήκε ομότιμους θα έπαιρνε απλώς πάλι το ίδιο magnet, μείον όλα όσα είχε ήδη φέρει.`,"settings.stall.maxRestarts":`Επανεκκινήσεις ανά λήψη`,"settings.stall.maxRestartsHint":`Πόσες φορές επιτρέπεται να ξεκινήσει αυτόματα από την αρχή μία λήψη πριν την αφήσουν ήσυχη. Το 0 δεν σημαίνει απεριόριστες, σημαίνει 3, τον ενσωματωμένο αριθμό. Μόλις φτάσει το όριο, η λήψη κρατά τη σήμανσή της και μένει εκεί που είναι, ώστε να δεις εσύ ο ίδιος τι συμβαίνει, αντί να δουλεύει εκείνη όλη νύχτα τον ίδιο διακομιστή στο κενό. Ο διακομιστής δέχεται το πολύ 20, οτιδήποτε παραπάνω αποθηκεύεται ως 20. Ο μετρητής ανήκει στη λήψη και μηδενίζεται μόνο όταν αυτή ολοκληρωθεί.`,"settings.resolvers.audioFormat":`Μορφή ήχου`,"settings.resolvers.audioFormatHint":`Σε τι μετατρέπεται μια γραμμή ήχου. Η «Καλύτερη» αντιγράφει το κομμάτι της ίδιας της πηγής χωρίς να το ξανακωδικοποιήσει, οπότε δεν χάνεται τίποτα και το αρχείο κρατά όποιον container χρησιμοποιούσε ήδη ο ιστότοπος. Κάθε άλλη επιλογή το περνά από το ffmpeg. Αυτό εδώ είναι μόνο η εφεδρική απάντηση: ένας σύνδεσμος που ετοιμάζεται σήμερα παίρνει τη μορφή ήχου του από τις προεπιλογές ανά πάροχο πιο κάτω σε αυτή τη σελίδα, και ο επιλογέας πάνω στην ίδια τη γραμμή κερδίζει και τα δύο.`,"settings.resolvers.audioBitrate":`Ρυθμός bit ήχου`,"settings.resolvers.audioBitrateHint":`Ο στόχος στον οποίο κωδικοποιεί το ffmpeg, όταν η μορφή παραπάνω κάνει πραγματικά μετατροπή, σε kbit/s. Το «Αυτόματο» δεν δίνει κανέναν στόχο και αφήνει την προεπιλογή του ίδιου του yt-dlp, περίπου 128 kbit/s μεταβλητό. Δεν κάνει απολύτως τίποτα σε μια εξαγωγή με την «Καλύτερη», που αντιγράφει τη ροή της πηγής και δεν έχει ρυθμό bit για να ξαναοριστεί. Και είναι ανώτατο όριο, όχι υπόσχεση: αν ζητήσεις 320 από μια πηγή που κουβαλά μόνο 128, δεν δημιουργούνται bit που δεν υπήρξαν ποτέ.`,"settings.resolvers.audioLang":`Ομιλούμενη γλώσσα`,"settings.resolvers.audioLangHint":`Περιορίζει μια γραμμή ήχου σε μία ομιλούμενη γλώσσα, όταν η πηγή κουβαλά περισσότερες, κάτι που παράγει ακριβώς η αυτόματη μεταγλώττιση του YouTube: χωρίς αυτό κερδίζει το κομμάτι που ακούγεται καλύτερα, και αυτό δεν είναι αξιόπιστα εκείνο που πραγματικά μιλήθηκε. Δύο γράμματα, ή ολόκληρος κωδικός όπως pt-BR. Η σύγκριση γίνεται από την αρχή, οπότε το de παίρνει και το de-DE. Κενό σημαίνει καμία προτίμηση και είναι ακριβώς ό,τι έκανε κάθε λήψη πριν υπάρξει αυτό. Μια πηγή που δεν ονομάζει γλώσσα ανά κομμάτι δεν αποτυγχάνει γι’ αυτό: το αίτημα πέφτει πίσω στο συνηθισμένο καλύτερο κομμάτι.`,"settings.resolvers.music":`Σήμανση των λήψεων ήχου ως μουσική`,"settings.resolvers.musicHint":`Μετατρέπει τη γραμμή ήχου σε tagger: καλλιτέχνης, άλμπουμ, τίτλος και αριθμός κομματιού γράφονται μέσα στο αρχείο, τα αρχεία καταλήγουν σε φακέλους καλλιτέχνη και άλμπουμ με αριθμημένα ονόματα, και δίπλα τους αποθηκεύεται ένα cover.jpg. Χωρίς ετικέτες, δώδεκα αρχεία είναι δώδεκα άσχετα σινγκλ του Unknown Artist στο Jellyfin ή στο Navidrome, γιατί μια βιβλιοθήκη διαβάζει τις ετικέτες και όχι το όνομα αρχείου. Η μετονομασία γίνεται μόνο όσο το πεδίο για το όνομα αρχείου εξόδου παραπάνω είναι κενό: ένα πρότυπο που έγραψε κάποιος κερδίζει πάντα.`,"settings.resolvers.subtitleStrict":`Γραμμή υποτίτλων που δεν παρήγαγε αρχείο να μετρά ως σφάλμα`,"settings.resolvers.subtitleStrictHint":`Μια πηγή που δεν κουβαλά τη γλώσσα που ζήτησες το λέει ως προειδοποίηση, και αυτό το backend τρέχει το yt-dlp με τις προειδοποιήσεις σβηστές. Η εργασία λοιπόν τελειώνει καθαρά και κάθεται πράσινη πάνω από έναν άδειο φάκελο, και τίποτα δεν σου λέει ότι η γλώσσα δεν υπήρξε ποτέ διαθέσιμη. Με αυτό αναμμένο, μια γραμμή υποτίτλων που δεν έγραψε τίποτα γίνεται κόκκινη και ονομάζει τις γλώσσες που ζήτησε. Σβηστό από προεπιλογή, γιατί το άναμμά του κάνει να αποτυγχάνουν γραμμές που μια υπάρχουσα εγκατάσταση τις κλείνει πράσινες εδώ και μήνες.`,"settings.resolvers.embedMetadata":`Εγγραφή τίτλου, δημιουργού και ημερομηνίας μέσα στο αρχείο`,"settings.resolvers.embedMetadataHint":`Βάζει τον τίτλο, τον δημιουργό που το ανέβασε, την ημερομηνία και την περιγραφή της ίδιας της πηγής στο μπλοκ ετικετών του container. Αυτό είναι το πρώτο που διαβάζουν το Jellyfin και το Plex όταν δεν υπάρχει NFO δίπλα στο αρχείο. Μόνο γραμμές βίντεο και ήχου: η μικρογραφία, οι υπότιτλοι και η περιγραφή είναι επίτηδες ξεχωριστά αρχεία, και το να γράψεις ετικέτες μέσα τους θα ήταν αντίφαση.`,"settings.resolvers.embedThumbnail":`Ενσωμάτωση της εικόνας εξωφύλλου`,"settings.resolvers.embedThumbnailHint":`Επισυνάπτει τη μικρογραφία της ίδιας της πηγής ως εξώφυλλο μέσα στο αρχείο, ώστε και μια βιβλιοθήκη που δεν ψάχνει τίποτα μόνη της να δείχνει εικόνα. Μόνο γραμμές βίντεο και ήχου. Δεν αντικαθιστά τη γραμμή μικρογραφίας, που αποθηκεύει την ίδια εικόνα ως δικό της .jpg δίπλα στη λήψη.`,"settings.resolvers.embedChapters":`Ενσωμάτωση των σημαδιών κεφαλαίων`,"settings.resolvers.embedChaptersHint":`Γράφει τα σημάδια κεφαλαίων της ίδιας της πηγής μέσα στον container. Αυτό είναι που κάνει το κουμπί παράλειψης ενός player να πηδά στην επόμενη ενότητα, αντί για έναν σταθερό αριθμό δευτερολέπτων.`,"settings.resolvers.embedSubs":`Ενσωμάτωση των υποτίτλων στο βίντεο`,"settings.resolvers.embedSubsHint":`Φέρνει τις γλώσσες που ονομάζονται στην κάρτα υποτίτλων παραπάνω και τις βάζει μέσα στο αρχείο βίντεο, αντί να αφήνει αρχεία .srt δίπλα του. Μόνο γραμμές βίντεο: ένα εξαγόμενο αρχείο ήχου δεν έχει ροή υποτίτλων για να τις κουβαλήσει, και το yt-dlp απαντά σε τέτοιο αίτημα με μια προειδοποίηση που αυτό το backend δεν τυπώνει ποτέ. Χρησιμοποιεί την ίδια λίστα γλωσσών και τον ίδιο διακόπτη για τους αυτόματους υπότιτλους με τη γραμμή υποτίτλων, οπότε τα δύο δεν μπορούν ποτέ να διαφωνήσουν μεταξύ τους.`,"settings.resolvers.embedSplitChapters":`Αποθήκευση και ενός αρχείου ανά κεφάλαιο`,"settings.resolvers.embedSplitChaptersHint":`Γράφει ένα επιπλέον αρχείο ανά κεφάλαιο δίπλα στην πλήρη λήψη. Προσθέτει αρχεία αντί να αντικαθιστά το ολόκληρο, οπότε ένα δίωρο βίντεο με είκοσι κεφάλαια καταλήγει ως είκοσι ένα αρχεία.`,"settings.resolvers.embedNfo":`Εγγραφή αρχείου NFO δίπλα στη λήψη`,"settings.resolvers.embedNfoHint":`Αποθηκεύει ένα .nfo σε στιλ Kodi, Jellyfin και Plex δίπλα στο ολοκληρωμένο αρχείο, φτιαγμένο από τα δεδομένα που είχε ήδη μαζέψει το yt-dlp κατά την εξαγωγή. Μόνο γραμμές βίντεο και ήχου. Μια αποτυχημένη εγγραφή δεν ρίχνει ποτέ τη λήψη: το αρχείο πολυμέσων είναι έτσι κι αλλιώς πλήρες, και το συνοδευτικό εμφανίζεται ξανά αν η εργασία τρέξει άλλη μια φορά.`,"settings.resolvers.measure":`Μέτρηση του ολοκληρωμένου αρχείου`,"settings.resolvers.measureHint":`Διαβάζει κάθε ολοκληρωμένη λήψη βίντεο ή ήχου πίσω με το ffprobe και καταγράφει τι υπάρχει πραγματικά μέσα: διάρκεια, ανάλυση, codec, πόσα κομμάτια ήχου. Μία σύντομη τοπική διεργασία ανά λήψη, χωρίς δίκτυο, χωρίς νέα εξάρτηση. Αυτό που πιάνει είναι μια λήψη που σταμάτησε νωρίς και ενώθηκε παρ’ όλα αυτά, όπου ο κωδικός εξόδου είναι 0, το μέγεθος φαίνεται λογικό και η εικόνα σταματά στο εικοστό λεπτό. Αυτό που δεν μπορεί να πιάσει είναι μια ένωση που σκοτώθηκε στη μέση της εγγραφής, η οποία κρατά την προβλεπόμενη διάρκεια στην κεφαλίδα της, και αυτή η περίπτωση συνήθως αποτυγχάνει έτσι κι αλλιώς θορυβωδώς από μόνη της.`,"settings.resolvers.measureShortPercent":`Μετράει ως κοντό κάτω από (ποσοστό)`,"settings.resolvers.measureShortPercentHint":`Πόσο από τη διάρκεια που ανακοίνωσε η πηγή πρέπει να περιέχει πραγματικά το αρχείο για να πάψει να μετράει ως κοντό, σε ποσοστό. Το 90 είναι η προεπιλογή, και επίτηδες όχι το 99: μια πραγματική λήψη καταλήγει συχνά λίγο κάτω από τον ανακοινωμένο αριθμό, και ένα κατώφλι που χτυπά σε αυτές μαθαίνει σε όλους να το αγνοούν. Μια κομμένη ένωση δεν λείπει κατά πέντε τοις εκατό, λείπει κατά το μισό. Οτιδήποτε εκτός του 1 έως 100 αποθηκεύεται ως 90 αντί να καρφωθεί στο κοντινότερο άκρο, και το 0 με την έννοια «μη γκρινιάζεις ποτέ» επίτηδες δεν υπάρχει, γιατί το να σου το πει είναι όλο το νόημα του να ανάψεις τον έλεγχο.`,"settings.resolvers.measureFailOnShort":`Το κοντό αρχείο να μετρά ως σφάλμα αντί για προειδοποίηση`,"settings.resolvers.measureFailOnShortHint":`Ένα αρχείο κάτω από το κατώφλι παραπάνω καταλήγει ως ολοκληρωμένο και κουβαλά μια προειδοποίηση στη γραμμή του. Με αυτό αναμμένο γίνεται κόκκινο, κάτι που το κάνει να ξανατρέχει με ένα κλικ. Σβηστό από προεπιλογή, γιατί τα byte στον δίσκο είναι αληθινά και συχνά αξίζει να κρατηθούν.`,"settings.resolvers.live":`Αναγνώριση ζωντανών μεταδόσεων`,"settings.resolvers.liveHint":`Μια ζωντανή μετάδοση δεν έχει τέλος και δεν έχει συνολικό μέγεθος, οπότε χωρίς αυτό ένας σύνδεσμος προς μία φτάνει ως συνηθισμένη λήψη, με μπάρα προόδου φτιαγμένη από έναν αριθμό που δεν ξέρει κανείς, και σέρνεται προς ένα τέλος που δεν έρχεται ποτέ ενώ ο δίσκος γεμίζει. Με αυτό αναμμένο, μια τέτοια γραμμή δείχνει πόση ώρα καταγράφει ήδη και πόσο έχει φτάσει, και τα δύο όρια από κάτω μπορούν να τη φρενάρουν. Ελέγχει επίσης την ίδια την αναγνώριση: αφημένο σβηστό, οι λήψεις τρέχουν με ακριβώς τη μορφή προόδου και ακριβώς την ανάλυση που είχαν πάντα.`,"settings.resolvers.liveFromStart":`Έναρξη από την αρχή της μετάδοσης`,"settings.resolvers.liveFromStartHint":`Καταγράφει από την ίδια την αρχή της μετάδοσης, αντί να μπαίνει στο ζωντανό άκρο. Το yt-dlp το αναφέρει ως μόνο για YouTube και πειραματικό, και αγνοείται εντελώς για οτιδήποτε δεν είναι ζωντανό, οπότε εκεί που δεν ισχύει δεν κοστίζει τίποτα.`,"settings.resolvers.liveMaxMinutes":`Χρονικό όριο εγγραφής`,"settings.resolvers.liveMaxMinutesHint":`Σταματά μια εγγραφή μετά από τόσα λεπτά, μετρημένα από την πρώτη στιγμή που φτάνουν πραγματικά δεδομένα της μετάδοσης και όχι από τότε που ξεκίνησε η εργασία, ώστε η αναμονή για μια πρεμιέρα ή η πάλη με έναν έλεγχο κατά των bot να μην τρώει από τον χρόνο. Το 0 σημαίνει κανένα όριο. Επίτηδες διάρκεια και όχι ώρα της ημέρας: το «σταμάτα στις 23:00» σε μια μετάδοση που ξεκίνησε στις 22:00 είναι όριο μιας ώρας, που γίνεται σιωπηλά είκοσι τριών ωρών όταν ο ίδιος σύνδεσμος επικολληθεί τα μεσάνυχτα. Όταν φτάσει το όριο, η εγγραφή σταματά ήπια, οπότε το αρχείο οριστικοποιείται και παίζει, και η γραμμή κλείνει ως ολοκληρωμένη με τον λόγο πάνω της, όχι ως σφάλμα.`,"settings.resolvers.liveMaxMB":`Όριο μεγέθους εγγραφής`,"settings.resolvers.liveMaxMBHint":`Σταματά μια εγγραφή μόλις φτάσει τόσο υλικό, σε MiB. Το 0 σημαίνει κανένα όριο. Μετριέται ό,τι αναφέρει το yt-dlp ως κατεβασμένο, όχι το μέγεθος στον δίσκο: μια ζωντανή λήψη γράφεται ως προσωρινά κομμάτια, των οποίων το συνολικό μέγεθος δεν είναι ο αριθμός πάνω στον οποίο βάζει κανείς όριο. Όποιο από τα δύο όρια φτάσει πρώτο τερματίζει την εγγραφή, ήπια, και η γραμμή κλείνει ως ολοκληρωμένη με τον λόγο πάνω της.`,"settings.resolvers.cookies":`Χρήση αποθηκευμένων cookies σύνδεσης`,"settings.resolvers.cookiesHint":`Παραδίδει στο yt-dlp το cookies.txt που είναι αποθηκευμένο για έναν ιστότοπο, και αυτό είναι που περνά το «συνδέσου για να επιβεβαιώσεις ότι δεν είσαι bot» και τις πύλες ηλικίας. Το αρχείο δεν είναι ποτέ μέρος του εγγράφου ρυθμίσεων: ζει στον κρυπτογραφημένο χώρο διαπιστευτηρίων, γράφεται σε ένα προσωρινό αρχείο που μπορεί να διαβάσει μόνο αυτός ο διακομιστής, και εκείνο το αρχείο σβήνεται τη στιγμή που τελειώνει η διεργασία. Διακόπτης και όχι αυτόματο, γιατί το να στέλνεις μια συνδεδεμένη συνεδρία έχει συνέπειες: ένα όριο ρυθμού ή ένας αποκλεισμός πέφτει στον λογαριασμό, όχι στη διεύθυνση. Για έναν ιστότοπο χωρίς αποθηκευμένο αρχείο, αυτό δεν αλλάζει τίποτα εκεί.`,"settings.resolvers.presetsTitle":`Προεπιλογές ανά πάροχο`,"settings.resolvers.presetsHint":`Κάθε σύνδεσμος yt-dlp ετοιμάζεται ως πέντε γραμμές, βίντεο, ήχος, μικρογραφία, υπότιτλοι, περιγραφή, και αυτός ο πίνακας αποφασίζει, ανά ιστότοπο, ποιες από αυτές ξεκινούν αναμμένες και με ποια ποιότητα και ποια μορφή ήχου ξεκινούν οι δύο που έχουν τέτοια. Ένας ιστότοπος χωρίς γραμμή εδώ παίρνει και τις πέντε αναμμένες, στην καλύτερη ποιότητα, με τον καλύτερο ήχο. Αυτή είναι επίσης η απάντηση που φτάνει πραγματικά σε έναν νέο σύνδεσμο: η ποιότητα και η μορφή ήχου στην κορυφή αυτής της σελίδας ισχύουν μόνο για γραμμές που δεν κουβαλούν δική τους επιλογή. Οι ίδιες ρυθμίσεις ανοίγουν και από το σήμα με το γρανάζι πάνω σε ένα πακέτο στον συλλέκτη, εκεί για τον έναν πάροχο στον οποίο ανήκει το πακέτο.`,"settings.nav.categories":`Κατηγορίες`,"settings.module.categories":`Κατηγορίες`,"settings.module.feeds":`Συνδρομές RSS και Atom`,"settings.module.downloadclient":`Πελάτης λήψεων για Sonarr και Radarr`,"settings.downloads.collisionTitle":`Συγκρούσεις ονομάτων`,"settings.downloads.collectorTitle":`Συλλέκτης`,"settings.downloads.diskTitle":`Χώρος στον δίσκο`,"settings.downloads.diskHint":`Τρεις αριθμοί που κρατούν πίσω τις λήψεις πριν γεμίσει ο δίσκος, αντί για μετά. Και οι τρεις εννοούν ελεύθερα byte στον δίσκο στον οποίο γράφεται η λήψη, οπότε αν ο φάκελος εργασίας είναι σε άλλον δίσκο, μετριέται εκείνος. Το μηδέν σβήνει τον κάθε αριθμό. Πρόσεξε τι δεν μπορεί να κάνει αυτό: δεν μπορεί να ρωτηθεί κάθε σύστημα πόσος χώρος είναι ελεύθερος, και όπου δεν υπάρχει απάντηση δεν κρατιέται ποτέ τίποτα πίσω, γιατί μια δικλείδα που μπλοκάρει όταν δεν ξέρει θα σταματούσε ένα εντελώς υγιές μηχάνημα.`,"settings.stall.title":`Κόλλημα`,"settings.advanced.mirrorsTitle":`Αντίγραφα του ίδιου αρχείου`,"settings.advanced.offlineTitle":`Σύνδεσμοι που είναι ήδη νεκροί`,"settings.advanced.reclaimTitle":`Αρχεία που βρίσκονται ήδη στον δίσκο`,"settings.advanced.retryTitle":`Επαναλήψεις ανά είδος σφάλματος`,"settings.resolvers.audioTitle":`Ήχος`,"settings.resolvers.subtitlesTitle":`Υπότιτλοι`,"settings.resolvers.embedTitle":`Μέσα στο αρχείο`,"settings.resolvers.measureTitle":`Έλεγχος του ολοκληρωμένου αρχείου`,"settings.resolvers.liveTitle":`Ζωντανές μεταδόσεις`,"settings.resolvers.cookiesTitle":`Cookies σύνδεσης`,"settings.hostRules.add":`Προσθήκη παρόχου`,"settings.hostRules.remove":`Αφαίρεση`,"settings.hostRules.empty":`Κανένας πάροχος δεν έχει ακόμη δικούς του αριθμούς.`,"settings.hostRules.emptyHint":`Μέχρι να προσθέσεις έναν, όλα ακολουθούν τις τιμές παραπάνω.`,"settings.hostRules.duplicate":`Υπάρχει ήδη γραμμή για αυτόν τον πάροχο.`,"settings.feeds.add":`Προσθήκη συνδρομής`,"settings.feeds.remove":`Αφαίρεση`,"settings.feeds.empty":`Δεν υπάρχουν ακόμη συνδρομές.`,"settings.feeds.emptyHint":`Μια συνδρομή ελέγχει μόνη της μια ροή και βάζει ό,τι είναι νέο στον συλλέκτη.`,"settings.feeds.duplicate":`Αυτή η διεύθυνση είναι ήδη σε συνδρομή.`,"settings.categories.add":`Προσθήκη κατηγορίας`,"settings.categories.remove":`Αφαίρεση`,"settings.categories.empty":`Δεν υπάρχουν ακόμη κατηγορίες.`,"settings.categories.emptyHint":`Μια κατηγορία κρατά έναν φάκελο και μερικές προεπιλογές κάτω από ένα όνομα, ώστε να διαλέγεις το όνομα αντί να περιγράφεις ξανά το ίδιο πράγμα.`,"settings.categories.duplicate":`Υπάρχει ήδη κατηγορία με αυτό το όνομα.`,"settings.categories.full":`Ο πίνακας είναι γεμάτος στις {max} κατηγορίες.`,"settings.resolvers.presetAdd":`Προσθήκη παρόχου`,"settings.resolvers.presetRemove":`Αφαίρεση`,"settings.resolvers.presetsEmpty":`Κανένας πάροχος δεν έχει ακόμη δικές του προεπιλογές.`,"settings.resolvers.presetHost":`Πάροχος`,"settings.resolvers.presetHostHint":`Ο ιστότοπος για τον οποίο ισχύουν αυτές οι προεπιλογές, για παράδειγμα youtube.com. Αποθηκεύεται με πεζά και χωρίς αρχικό «www.», και μπορείς να επικολλήσεις και ολόκληρη διεύθυνση: κρατιέται μόνο ο κόμβος. Ένας πάροχος χωρίς καταχώριση εδώ ξεκινά κάθε παραλλαγή αναμμένη, στην καλύτερη ποιότητα.`,"settings.resolvers.quality.4320p":`Έως 4320p (8K)`,"settings.resolvers.quality.240p":`Έως 240p`,"settings.resolvers.quality.144p":`Έως 144p`,"settings.downloads.confirm.include":`Πρόσθεσέ τον έτσι κι αλλιώς`,"settings.downloads.confirm.exclude":`Άφησέ τον στον συλλέκτη`,"settings.downloads.confirm.excludeAndRemove":`Πέταξέ τον`,"settings.downloads.confirm.ask":`Ρώτα με`,"settings.advanced.mirror.off":`Ποτέ`,"settings.advanced.mirror.filename-only":`Ίδιο όνομα αρχείου`,"settings.advanced.mirror.size-only":`Ίδιο μέγεθος`,"settings.advanced.mirror.filename-and-size":`Ίδιο όνομα και ίδιο μέγεθος`,"settings.advanced.mirror.filename-or-hash":`Ίδιο όνομα, ή ίδιο άθροισμα ελέγχου`,"settings.advanced.mirror.hash-only":`Ίδιο άθροισμα ελέγχου`,"settings.advanced.offline.include":`Πρόσθεσέ τον έτσι κι αλλιώς`,"settings.advanced.offline.exclude":`Άφησέ τον στον συλλέκτη`,"settings.advanced.offline.exclude-and-remove":`Πέταξέ τον`,"settings.advanced.offline.ask":`Ρώτα με`,"settings.advanced.reclaim.checksum":`Άθροισμα ελέγχου που ταιριάζει`,"settings.advanced.reclaim.record":`Μια καταγραφή ότι αυτή η λήψη το έγραψε`,"settings.advanced.reclaim.size":`Το σωστό όνομα και το σωστό μέγεθος`,"settings.categories.priorityNone":`Καμία προτίμηση`,"settings.feeds.priorityNone":`Χωρίς ορισμό`,"task.waiting.disk":`Περιμένει χώρο στον δίσκο`,"settings.feeds.status":`Κατάσταση`,"settings.feeds.statusPolling":`Ελέγχεται`,"settings.feeds.statusNotPolling":`Δεν ελέγχεται`,"settings.feeds.statusUnknown":`Δεν έχει ελεγχθεί ακόμη από τότε που ξεκίνησε ο διακομιστής`,"settings.feeds.lastPolled":`Τελευταίος έλεγχος`,"settings.feeds.lastPolledNever":`Δεν έχει ελεγχθεί ακόμη`,"settings.feeds.lastPolledHint":`Πότε κοιτάχτηκε τελευταία φορά αυτή η συνδρομή, είτε πέτυχε η ανάκτηση είτε όχι. Στην επανεκκίνηση του διακομιστή η ένδειξη χάνεται, ενώ ό,τι έχει ήδη προσθέσει η συνδρομή δεν χάνεται. Μια ροή που ακολουθείς εδώ και μήνες δείχνει έτσι ανέλεγκτη για τα λίγα δευτερόλεπτα μετά την επανεκκίνηση.`,"settings.feeds.pollFailed":`Ο τελευταίος έλεγχος απέτυχε`,"settings.feeds.notPolledReason":`Αυτή η συνδρομή δεν ελέγχεται καθόλου`,"settings.feeds.seededYes":`Έτοιμη, προστίθεται μόνο ό,τι είναι νέο`,"settings.feeds.seededNo":`Ο πρώτος έλεγχος δεν έχει γίνει ακόμη, και μέχρι τότε δεν προστίθεται τίποτα`,"settings.feeds.seededHint":`Ο πρώτος έλεγχος μιας νέας συνδρομής σημειώνει ό,τι κουβαλά η ροή εκείνη τη στιγμή και δεν προσθέτει τίποτα από αυτά, ώστε να μη σου πέσει μονομιάς όλο το παλιό αρχείο ενός εκδότη. Προστίθεται μόνο ό,τι εμφανιστεί από εκεί και πέρα.`,"settings.feeds.remembered":`{n} καταχωρίσεις σε μνήμη`,"settings.feeds.rememberedHint":`Πόσες καταχωρίσεις αναγνωρίζει ξανά αυτή η συνδρομή, ώστε να μην προστεθούν δεύτερη φορά όσο η ροή τις σερβίρει ακόμη. Το πολύ 500 ανά συνδρομή. Οι παλαιότερες φεύγουν πρώτες, και μια καταχώριση που είναι ακόμη στη ροή δεν είναι ποτέ ανάμεσά τους.`,"settings.feeds.test":`Δοκιμή`,"settings.feeds.testBusy":`Γίνεται ανάκτηση`,"settings.feeds.testHint":`Ανακτά αυτή τη διεύθυνση μία φορά και σου δείχνει τι υπάρχει μέσα, ώστε να δεις τους τίτλους πάνω στους οποίους δοκιμάζεται το φίλτρο σου. Μόνο διαβάζει: τίποτα δεν μπαίνει στον συλλέκτη και τίποτα δεν σημειώνεται ως ιδωμένο, οπότε μπορείς να το πατήσεις και για διεύθυνση που δεν έχεις αποθηκεύσει ακόμη.`,"settings.feeds.testResult":`Τι υπάρχει σε αυτή τη ροή`,"settings.feeds.testFeedName":`Όνομα ροής`,"settings.feeds.testNoName":`Αυτό το έγγραφο δεν δημοσιεύει όνομα`,"settings.feeds.testMatched":`{matched} από {total} καταχωρίσεις ταιριάζουν στο φίλτρο τίτλων`,"settings.feeds.testNoFilter":`Κανένα φίλτρο τίτλων, οπότε παίρνονται και οι {total} καταχωρίσεις`,"settings.feeds.testShowing":`Εμφανίζονται οι πρώτες {n}`,"settings.feeds.testMatchYes":`Παίρνεται`,"settings.feeds.testMatchNo":`Μένει απ’ έξω`,"settings.feeds.testNoneMatch":`Τίποτα σε αυτή τη ροή δεν ταιριάζει στο φίλτρο τίτλων σου. Σύγκρινε τη γραφή με τους τίτλους παραπάνω.`,"settings.feeds.testEmpty":`Η διεύθυνση απάντησε, αλλά το έγγραφο δεν περιέχει καμία απολύτως καταχώριση. Έλεγξε αν είναι πράγματι ροή και όχι η σελίδα πάνω στην οποία βρίσκεται η ροή.`,"settings.feeds.testFailed":`Αυτή η ροή δεν μπόρεσε να διαβαστεί`,"settings.feeds.testSafe":`Η δοκιμή μόνο διαβάζει. Τίποτα δεν προστέθηκε και τίποτα δεν κρατήθηκε στη μνήμη.`,"settings.headerProfiles.title":`Προφίλ κεφαλίδων`,"settings.headerProfiles.hint":`Μερικοί ιστότοποι δίνουν ένα αρχείο μόνο σε συνδεδεμένο περιηγητή, ή μόνο όταν η κλήση έρχεται από μια δική τους σελίδα. Ένα προφίλ αποθηκεύει τις κεφαλίδες για έναν ακριβώς ιστότοπο, κρυπτογραφημένες όπως και τα διαπιστευτήριά σου, και το KnightLoader τις στέλνει μαζί με κάθε λήψη από αυτόν τον ιστότοπο.`,"settings.headerProfiles.empty":`Δεν υπάρχουν ακόμη προφίλ κεφαλίδων.`,"settings.headerProfiles.emptyHint":`Αξίζει ένα, μόλις μια λήψη δουλεύει μόνο όσο είσαι συνδεδεμένος στον περιηγητή.`,"settings.headerProfiles.add":`Προσθήκη προφίλ`,"settings.headerProfiles.name":`Όνομα προφίλ`,"settings.headerProfiles.nameHint":`Με αυτό το όνομα καλείς το προφίλ, σε έναν κανόνα Packagizer όπως και εδώ. Μόνο γράμματα, ψηφία και - _ ή .`,"settings.headerProfiles.namePlaceholder":`π.χ. forum`,"settings.headerProfiles.origin":`Ιστότοπος`,"settings.headerProfiles.originHint":`Επικόλλησε τη διεύθυνση της σελίδας από την οποία αντέγραψες τις κεφαλίδες. Άλλη θύρα, και http αντί για https, μετρούν ως άλλος ιστότοπος και χρειάζονται δικό τους προφίλ. Ένας υποτομέας δεν καλύπτεται από το προφίλ του τομέα του.`,"settings.headerProfiles.headers":`Κεφαλίδες`,"settings.headerProfiles.headerName":`Όνομα`,"settings.headerProfiles.headerValue":`Τιμή`,"settings.headerProfiles.valueStored":`Αποθηκευμένη`,"settings.headerProfiles.valueStoredHint":`Η τιμή μένει σε αυτό το στιγμιότυπο και δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα. Άφησε το πεδίο όπως είναι για να τη διατηρήσεις, ή γράψε νέα τιμή για να την αντικαταστήσεις.`,"settings.headerProfiles.addHeader":`Προσθήκη κεφαλίδας`,"settings.headerProfiles.removeHeader":`Αφαίρεση αυτής της κεφαλίδας`,"settings.headerProfiles.count":`{n} κεφαλίδες`,"settings.headerProfiles.save":`Αποθήκευση προφίλ`,"settings.headerProfiles.delete":`Διαγραφή προφίλ`,"settings.headerProfiles.deleteConfirm":`Να διαγραφεί το προφίλ {id}; Οι κεφαλίδες που κρατά χάνονται, και οι λήψεις από {origin} φεύγουν ξανά χωρίς αυτές.`,"settings.rules.action.category":`Κατηγορία`,"settings.rules.action.categoryHint":`Βάζει τους συνδέσμους που ταιριάζουν σε ένα από τα συρτάρια της σελίδας Κατηγορίες, το οποίο φέρνει μαζί του δικό του φάκελο, δική του θέση στην ουρά, δικό του διακόπτη αποσυμπίεσης και δικό του κανόνα για ένα αρχείο που υπάρχει ήδη. Αν μείνει αμετάβλητο, κανένας κανόνας δεν έχει άποψη και ο σύνδεσμος μένει αταξινόμητος. Αν αυτός ο κανόνας ονομάζει και φάκελο λήψεων, κερδίζει εκείνος ο φάκελος και το συρτάρι δίνει και πάλι όλα τα υπόλοιπα. Το να ονομάσεις ένα συρτάρι που έχει διαγραφεί απορρίπτεται κατά την αποθήκευση, γιατί ένας κανόνας που δείχνει σε συρτάρι που δεν υπάρχει δεν κάνει απολύτως τίποτα σε κάθε σύνδεσμο που ταιριάζει, χωρίς καμία ειδοποίηση.`,"settings.rules.action.categoryNone":`Δεν υπάρχουν ακόμη κατηγορίες. Φτιάξε πρώτα μία στη σελίδα Κατηγορίες, αλλιώς αυτός ο κανόνας θα έβαζε συνδέσμους σε ένα συρτάρι που δεν υπάρχει.`,"settings.rules.action.categoryMissing":`{id} (διαγραμμένη)`,"settings.resolvers.cookieJars":`Αποθηκευμένα αρχεία`,"settings.resolvers.cookieJarsHint":`Ένα αποθηκευμένο αρχείο δεν εμφανίζεται ποτέ ξανά: είναι μια ζωντανή συνδεδεμένη συνεδρία, οπότε ταξιδεύει μόνο προς μία κατεύθυνση, μέσα σε αυτόν τον διακομιστή. Για να αντικαταστήσεις ένα, επικόλλησε από πάνω του το νέο αρχείο.`,"settings.resolvers.cookieHost":`Ιστότοπος`,"settings.resolvers.cookieHostPlaceholder":`youtube.com, ή η διεύθυνση από την οποία εξήγαγες το αρχείο`,"settings.resolvers.cookieText":`cookies.txt`,"settings.resolvers.cookieTextPlaceholder":`Επικόλλησε εδώ την εξαγόμενη cookies.txt`,"settings.resolvers.cookieSave":`Αποθήκευση αρχείου`,"settings.resolvers.cookieRemove":`Αφαίρεση`,"settings.resolvers.cookieRemoveConfirm":`Να αφαιρεθεί το αποθηκευμένο αρχείο για {host}; Οι λήψεις από αυτόν τον ιστότοπο γίνονται τότε ξανά ανώνυμες.`,"settings.resolvers.cookieEmpty":`Κανένας ιστότοπος δεν έχει ακόμη αποθηκευμένο αρχείο.`,"settings.resolvers.cookieStored":`Αποθηκευμένο`,"detail.label":`Λεπτομέρειες εργασίας`,"detail.link":`Σύνδεσμος`,"detail.address":`Διεύθυνση`,"detail.addressHint":`Η διεύθυνση από την οποία ξεκίνησε αυτή η λήψη. Αυτό ζήτησε η εφαρμογή, και δεν είναι πάντα το σημείο από το οποίο ήρθαν τα byte: μέσω μιας υπηρεσίας debrid, ο πάροχος παρακάτω είναι ο ιστότοπος όπου βρίσκεται το αρχείο, και το backend είναι αυτό που το έφερε.`,"detail.copy":`Αντιγραφή`,"detail.copied":`Αντιγράφηκε`,"detail.copyFailed":`Δεν αντιγράφηκε τίποτα.`,"detail.origin":`Μπήκε μέσω`,"detail.originUnknown":`Δεν καταγράφηκε`,"detail.package":`Πακέτο`,"detail.noPackage":`Σε κανένα πακέτο`,"detail.onDisk":`Αυτή τη στιγμή στον δίσκο`,"detail.onDiskHint":`Πόσο μετρά το αρχείο στον δίσκο αυτό το δευτερόλεπτο, ρωτημένο από τον διακομιστή αντί να μετρηθεί εδώ. Μια λήψη που τρέχει μεγαλώνει από τη μια ματιά στην άλλη, και αυτό δεν είναι το μέγεθος που ανακοίνωσε ο πάροχος.`,"detail.mirrorOf":`Εφεδρικό αντίγραφο του`,"detail.times":`Χρονικές σημάνσεις`,"detail.timesHint":`Πότε έφτασε αυτός ο σύνδεσμος, πότε άλλαξε τελευταία φορά και πότε ολοκληρώθηκε. Δεν υπάρχει ώρα για το πότε ξεκίνησε η μεταφορά: η εφαρμογή δεν την κράτησε ποτέ πουθενά, και μια εικασία από τις άλλες τρεις θα ήταν ένας αριθμός πάνω στον οποίο ενεργεί κόσμος.`,"detail.nextTry":`Επόμενη προσπάθεια`,"detail.stalledSince":`Κολλημένο από`,"detail.retries":`Επαναλήψεις μέχρι τώρα`,"detail.retriesHint":`Πόσες φορές δοκιμάστηκε ξανά αυτή η λήψη μετά από σφάλμα. Μηδενίζεται τη στιγμή που η λήψη ολοκληρώνεται, οπότε μια ολοκληρωμένη γραμμή δείχνει μηδέν ακόμη κι όταν χρειάστηκαν τέσσερις γύροι. Πόσες προσπάθειες απομένουν δεν φαίνεται εδώ: το ανώτατο όριο εξαρτάται από την αιτία και από τον πάροχο, και αυτή η σελίδα δεν μπορεί να το υπολογίσει.`,"detail.stallRestarts":`Επανεκκινήσεις μετά από κόλλημα`,"detail.stallRestartsHint":`Πόσες φορές η επιτήρηση κολλημάτων ξεκίνησε από μόνη της ξανά αυτή τη λήψη. Μηδενίζεται μόλις η λήψη ολοκληρωθεί, ακριβώς όπως ο μετρητής από πάνω.`,"detail.failure":`Τι πήγε στραβά`,"detail.cause":`Αιτία`,"detail.message":`Τι είπε το backend`,"detail.messageHint":`Η πρόταση από αυτό που προσπάθησε να φέρει τη λήψη, λέξη προς λέξη και αμετάφραστη. Είναι το τρέχον σφάλμα και τίποτε άλλο: μια επανεκκίνηση το σβήνει, και τα προηγούμενα δεν κρατιούνται πουθενά.`,"detail.heldBack":`Κρατιέται πίσω από`,"detail.doing":`Κάνει αυτή τη στιγμή`,"detail.filtered":`Κρατήθηκε από το φίλτρο συνδέσμων`,"detail.gaveUp":`Καμία νέα προσπάθεια`,"detail.gaveUpHint":`Εδώ σταματά επίτηδες, όχι επειδή εξαντλήθηκαν οι προσπάθειες: ένα captcha, ένας γεμάτος δίσκος, ή ένας κανόνας που λέει «ποτέ» για αυτόν τον πάροχο. Το να ανεβάσεις τον αριθμό των επαναλήψεων δεν αλλάζει τίποτα εδώ. Η ίδια η σήμανση δεν γράφεται στη βάση δεδομένων, οπότε μετά από επανεκκίνηση χάνεται, ενώ ο λόγος της μένει.`,"detail.rules":`Κανόνες που το διαμόρφωσαν`,"detail.rulesHint":`Οι κανόνες που ενεργοποιήθηκαν σε αυτόν τον σύνδεσμο καθώς ετοιμαζόταν, με τη σειρά που έτρεξαν. Κρατιούνται με το όνομά τους, οπότε ένας κανόνας που μετονομάστηκε από τότε δεν βρίσκεται πια, και ένας κανόνας που δεν είχε ποτέ όνομα κρατιέται με τη θέση που είχε τότε. Ένα κλικ τον ανοίγει στον επεξεργαστή κανόνων.`,"detail.openRule":`Άνοιγμα στον επεξεργαστή κανόνων`,"detail.noRules":`Κανένας κανόνας δεν άγγιξε αυτόν τον σύνδεσμο.`,"detail.player":`Αναπαραγωγή`,"detail.play":`Αναπαραγωγή εδώ`,"detail.playHint":`Παίζει το αρχείο απευθείας από αυτό το στιγμιότυπο, χωρίς να το κατεβάσεις δεύτερη φορά. Πριν πατήσεις αναπαραγωγή δεν φέρνεται τίποτα, και το αρχείο μένει εκεί που είναι.`,"detail.playPartial":`Αυτή η λήψη δεν έχει ολοκληρωθεί. Παίζει μόνο το κομμάτι που βρίσκεται ήδη στον δίσκο, δεν γίνεται να πηδήξεις πέρα από αυτό, και μερικά αρχεία δεν παίζουν απολύτως τίποτα πριν φτάσει το τελευταίο byte.`,"detail.playUnsupported":`Αυτός ο περιηγητής δεν μπορεί να παίξει αυτό το αρχείο. Άνοιξέ το ή αποθήκευσέ το από το μενού του δεξιού κλικ.`,"detail.playRemote":`Εδώ παίζουν μόνο αρχεία αυτού του στιγμιότυπου. Ένα άλλο στιγμιότυπο δίνει τα αρχεία του μονοκόμματα και χωρίς δυνατότητα μετακίνησης, και με αυτό δεν τα βγάζει πέρα ένα πρόγραμμα αναπαραγωγής.`,"detail.playNotLocal":`Αυτή τη λήψη την έφερε το JDownloader, οπότε το αρχείο βρίσκεται στον δίσκο εκείνης της διεργασίας και όχι σε αυτόν εδώ.`,"detail.playNoFile":`Δεν υπάρχει ακόμη τίποτα στον δίσκο για αναπαραγωγή.`,"detail.playRefused":`Ο διακομιστής δεν δίνει αυτό το αρχείο: {reason}`,"detail.playFailed":`Η αναπαραγωγή σταμάτησε: {reason}`,"detail.playClose":`Κλείσιμο του προγράμματος αναπαραγωγής`,"settings.rules.notFound":`Κανένας κανόνας εδώ δεν λέγεται «{name}». Μετονομάστηκε ή διαγράφηκε από τότε που προστέθηκε ο σύνδεσμος που τον ονομάζει.`,"notifications.title":`Ειδοποιήσεις`,"notifications.titleHint":`Αποφάσισε ανά συμβάν αν εμφανίζεται ως μήνυμα μέσα στην εφαρμογή, ως ειδοποίηση του λειτουργικού σου συστήματος, ή καθόλου. Μια ειδοποίηση συστήματος σε φτάνει μόνο όσο είναι ανοιχτή μια καρτέλα του KnightLoader, και η αθόρυβη λειτουργία παρακάτω ισχύει επιπλέον.`,"notifications.channel.app":`Μέσα στην εφαρμογή`,"notifications.channel.system":`Ειδοποίηση συστήματος`,"notifications.channel.silent":`Να μην εμφανίζεται τίποτα`,"notifications.event.downloadDone":`Η λήψη ολοκληρώθηκε`,"notifications.event.downloadDoneHint":`Κάθε λήψη που φτάνει ως το τέλος το λέει. Με διακόσια αρχεία στην ουρά, αυτά είναι διακόσια μηνύματα, οπότε σκέψου το δύο φορές πριν τα στείλεις στο σύστημα.`,"notifications.event.downloadFailed":`Η λήψη απέτυχε`,"notifications.event.downloadFailedHint":`Μια λήψη που τα παράτησε. Η αθόρυβη λειτουργία δεν την κρύβει ποτέ.`,"notifications.event.extractionDone":`Η αποσυμπίεση ολοκληρώθηκε`,"notifications.event.extractionDoneHint":`Ένα συμπιεσμένο αρχείο που αποσυμπιέστηκε ως το τέλος. Αυτό δεν αναφερόταν μέχρι τώρα πουθενά, γι’ αυτό ξεκινά στο «Να μην εμφανίζεται τίποτα».`,"notifications.event.extractionFailed":`Η αποσυμπίεση απέτυχε`,"notifications.event.extractionFailedHint":`Ένα συμπιεσμένο αρχείο που σταμάτησε χωρίς να τελειώσει. Συνήθως λείπει ο κωδικός, και τα αρχεία μένουν εκεί που είναι μέχρι να ασχοληθείς.`,"notifications.event.captchaWaiting":`Ένα captcha περιμένει`,"notifications.event.captchaWaitingHint":`Το παράθυρο του captcha ανοίγει σε αυτή την καρτέλα έτσι κι αλλιώς. Ξεκινά στο «Να μην εμφανίζεται τίποτα», γιατί εκείνο το παράθυρο είναι ήδη το μήνυμα όσο το κοιτάς. Βάλε το σε ειδοποίηση συστήματος και ένα captcha σε καρτέλα στο παρασκήνιο σε φτάνει πριν ο πάροχος πετάξει τη συνεδρία.`,"notifications.event.captchaFailed":`Το captcha απέτυχε`,"notifications.event.captchaFailedHint":`Κανείς δεν απάντησε εγκαίρως, ή η απάντηση δεν πέρασε. Η λήψη από πίσω μένει εκεί που είναι.`,"notifications.event.captchaResolved":`Το captcha απαντήθηκε αλλού`,"notifications.event.captchaResolvedHint":`Κάποιος σε άλλον περιηγητή, ή ένας αυτόματος λύτης, το απάντησε και το παράθυρο έκλεισε μόνο του.`,"notifications.systemUnavailable":`Οι ειδοποιήσεις συστήματος δεν είναι διαθέσιμες εδώ: ο περιηγητής σου τις προσφέρει μόνο μέσω HTTPS ή σε localhost. Όλα όσα βρίσκονται σε αυτή την κάρτα εξακολουθούν να εμφανίζονται μέσα στην εφαρμογή.`,"notifications.systemBlocked":`Ο περιηγητής σου μπλοκάρει τις ειδοποιήσεις για αυτή τη διεύθυνση. Οι γραμμές που είναι στο «Ειδοποίηση συστήματος» εμφανίζονται στη θέση τους μέσα στην εφαρμογή, μέχρι να τις επιτρέψεις ξανά στις ρυθμίσεις ιστοτόπου του περιηγητή σου.`,"notifications.systemNotGranted":`Ο περιηγητής δεν έδωσε την άδεια, οπότε αυτό το συμβάν μένει μέσα στην εφαρμογή. Διάλεξε ξανά «Ειδοποίηση συστήματος» για να ρωτηθεί άλλη μια φορά.`,"notifications.test":`Αποστολή δοκιμής`,"notifications.testBody":`Έτσι μοιάζει μια ειδοποίηση του KnightLoader.`,"captcha.waiting":`Ένα captcha για {host} περιμένει απάντηση.`,"archive.doneToast":`Το {name} αποσυμπιέστηκε.`,"archive.failedToast":`Η αποσυμπίεση του {name} απέτυχε.`,"settings.search.placeholder":`Αναζήτηση σε όλες τις ρυθμίσεις…`,"settings.search.hint":`Ψάχνει σε κάθε ενότητα των ρυθμίσεων: στα ονόματα των ενοτήτων, στους τίτλους των καρτών, στη λεζάντα δίπλα σε κάθε στοιχείο ελέγχου και στις εξηγήσεις πίσω από το (i). Αν διαλέξεις ένα αποτέλεσμα, ανοίγει εκείνη η ενότητα και επισημαίνεται η γραμμή. Δεν ψάχνει στις τιμές που έχεις ορίσει: γι’ αυτό υπάρχει το πλαίσιο στην καρτέλα Για προχωρημένους.`,"settings.search.clear":`Καθαρισμός αναζήτησης`,"settings.search.noMatch":`Δεν ταιριάζει τίποτα.`,"settings.search.results":`Αποτελέσματα αναζήτησης`,"settings.search.countOne":`1 αποτέλεσμα`,"settings.search.count":`{n} αποτελέσματα`,"settings.search.inHint":`βρέθηκε στο επεξηγηματικό κείμενο`,"settings.search.section":`Ενότητα`,"settings.search.rowHidden":`Το {card} είναι ανοιχτό. Εκείνη η γραμμή δεν φαίνεται αυτή τη στιγμή.`,"settings.search.command":`Αναζήτηση σε όλες τις ρυθμίσεις`,"views.label":`Αποθηκευμένες προβολές`,"views.save":`Αποθήκευση αυτής της προβολής`,"views.saveHint":`Μια προβολή είναι η αναζήτηση και τα φίλτρα που έχεις ορίσει αυτή τη στιγμή, αποθηκευμένα κάτω από ένα όνομα που δίνεις εσύ. Οι στήλες και η ταξινόμηση δεν ανήκουν σε αυτήν, εκείνες θυμούνται χωριστά.`,"views.saveTitle":`Ονομασία της προβολής`,"views.nameLabel":`Όνομα`,"views.namePlaceholder":`Μεγάλα αρχεία της περασμένης εβδομάδας`,"views.saveConfirm":`Αποθήκευση προβολής`,"views.overwriteConfirm":`Αντικατάσταση της προβολής`,"views.full":`Έχεις {n} αποθηκευμένες προβολές, και περισσότερες δεν κρατά αυτή η λίστα. Διάγραψε μία για να ελευθερωθεί θέση.`,"views.tooBig":`Αυτή η προβολή περιέχει περισσότερες τιμές φίλτρων από όσες μπορούν να αποθηκευτούν. Βγάλε την επιλογή από μερικές στην πλαϊνή γραμμή και αποθήκευσέ την ξανά.`,"views.manage":`Διαχείριση αποθηκευμένων προβολών`,"views.rename":`Μετονομασία`,"views.renameTitle":`Μετονομασία της προβολής`,"views.delete":`Διαγραφή`,"views.deleteTitle":`Να διαγραφεί η προβολή «{name}»;`,"views.deleteBody":`Μια προβολή είναι μόνο ένα όνομα για μια αναζήτηση και μερικά φίλτρα. Με τη διαγραφή δεν αλλάζει τίποτα στη λίστα και δεν αφαιρείται κανένας σύνδεσμος.`,"views.deleteConfirm":`Διαγραφή προβολής`,"views.clearAll":`Καθαρισμός της αναζήτησης και όλων των φίλτρων`,"views.clearAllHint":`Η αναζήτηση και τα φίλτρα μένουν ορισμένα όταν φύγεις από αυτή τη σελίδα και ξαναγυρίσεις, οπότε βρίσκεις πάλι τη λίστα που άφησες. Αυτό εδώ φέρνει πίσω ολόκληρη τη λίστα. Οι αποθηκευμένες προβολές μένουν όπως είναι.`,"disk.title":`Φάκελοι προορισμού`,"disk.hint":`Ελεύθερος και κατειλημμένος χώρος σε κάθε φάκελο στον οποίο μπορεί να καταλήξει μια λήψη, και πόσα έχει ακόμη να γράψει εκεί η ουρά. Οι τιμές έρχονται από την ίδια κλήση με την οποία ελέγχονται και τα όρια δίσκου, και είναι το πολύ λίγων δευτερολέπτων. Ο ελεύθερος και ο κατειλημμένος χώρος δεν δίνουν πάντα μαζί το μέγεθος του τόμου: ένα σύστημα αρχείων κρατά ένα κομμάτι για το σύστημα, και μια ποσόστωση ανά χρήστη μπορεί να αφήνει σε αυτό το στιγμιότυπο λιγότερα από όσα έχει πραγματικά ο τόμος. Δύο φάκελοι στον ίδιο δίσκο δείχνουν ο καθένας τον ίδιο δίσκο, οπότε ποτέ μην προσθέτεις τις γραμμές μεταξύ τους.`,"disk.free":`Ελεύθερα`,"disk.used":`Κατειλημμένα`,"disk.size":`Μέγεθος τόμου`,"disk.queued":`Μένουν να γραφτούν`,"disk.queuedHint":`Τι θα πρόσθεταν σε αυτόν τον φάκελο οι λήψεις που εκκρεμούν ακόμη: το μέγεθος που ανακοίνωσε ο πάροχος, μείον όσα έχουν ήδη φτάσει. Μια λήψη της οποίας το μέγεθος δεν το λέει ο πάροχος μετρά εδώ ως μηδέν, οπότε ο αριθμός είναι κατώτατο όριο και ποτέ υπόσχεση, και γι’ αυτό μπορεί να γράφει μηδέν byte δίπλα σε μια σειρά από λήψεις. Οι λήψεις που έχεις απενεργοποιήσει μένουν απ’ έξω, ο ίδιος κανόνας που ακολουθούν και οι μετρητές κάτω από τη λίστα. Μια λήψη που ήδη τρέχει έχει συνήθως δεσμεύσει τον χώρο της στον δίσκο τη στιγμή που ξεκίνησε, οπότε τα byte της λείπουν ήδη από τον ελεύθερο χώρο δίπλα και δεν έρχονται από πάνω του.`,"disk.tasks":`{n} λήψεις`,"disk.unknown":`Αυτό το σύστημα δεν αναφέρει ελεύθερο χώρο`,"disk.unknownHint":`Δεν μπορεί να ρωτηθεί κάθε πυρήνας πόσος χώρος έχει μείνει σε έναν τόμο, και αυτό το build δεν έχει κλήση για εκείνον πάνω στον οποίο τρέχει. Όπου λείπει η απάντηση, δεν κρατιέται τίποτα πίσω: οι λήψεις ξεκινούν ακριβώς όπως ξεκινούσαν πριν υπάρξουν τα όρια δίσκου. Αυτή η γραμμή υπάρχει για να το ξεχωρίζεις από έναν δίσκο που είναι πράγματι γεμάτος.`,"disk.missing":`Δεν έχει δημιουργηθεί ακόμη`,"disk.missingHint":`Αυτόν τον φάκελο τον δημιουργεί όποιος γράψει μέσα του το πρώτο αρχείο, οπότε δεν υπάρχει ακόμη. Οι τιμές περιγράφουν το {path}, τον πλησιέστερο υπαρκτό φάκελο από πάνω του, και εκείνος βρίσκεται στον τόμο στον οποίο θα κατέληγε η λήψη.`,"disk.measured":`Μετρήθηκε στο {path}`,"disk.elsewhereHint":`Ο ίδιος ο φάκελος δεν μπόρεσε να μετρηθεί, οπότε μετρήθηκε ο πλησιέστερος από πάνω του που μπορούσε. Αν κάποια προσάρτηση δεν σηκώθηκε, αυτός μπορεί να είναι εντελώς άλλος δίσκος από εκείνον για τον οποίο προορίζεται η λήψη. Κοίτα τη διαδρομή πριν βγάλεις οποιοδήποτε συμπέρασμα από τους αριθμούς.`,"disk.sampled":`Διαβάστηκε πριν από {n} δευτερόλεπτα`,"disk.tight":`Η ουρά δεν χωράει`,"disk.tightHint":`Σε αυτόν τον φάκελο εκκρεμούν περισσότερα από όσα έχει ελεύθερα ο τόμος. Αυτή η γραμμή από μόνη της δεν σταματά τίποτα: οι λήψεις κρατιούνται πίσω μία μία, καθώς έρχεται η σειρά τους, σύμφωνα με τους αριθμούς στη σελίδα ρυθμίσεων Λήψεις, και μια λήψη της οποίας το μέγεθος δεν το ξέρει κανείς δεν μετρά εδώ καθόλου.`,"disk.truncated":`Δεν αναφέρονται όλοι οι φάκελοι`,"disk.truncatedHint":`Η ουρά στοχεύει σε περισσότερους φακέλους εκτός των ρυθμισμένων από όσους αξίζει να μετριούνται σε κάθε ανάγνωση, οπότε λείπουν εκείνοι με τα λιγότερα. Κάθε φάκελος που έχεις ρυθμίσει είναι πάντα εδώ.`,"disk.markLow":`Κάτω από εδώ δεν ξεκινά τίποτα καινούριο`,"disk.markStop":`Κάτω από εδώ σταματούν τα πάντα`,"disk.limits":`Ρύθμιση των ορίων δίσκου`,"disk.stripLabel":`Χώρος στους φακέλους προορισμού`,"disk.role.downloads":`Φάκελος λήψεων`,"disk.role.category":`Φάκελος κατηγορίας`,"disk.role.work":`Φάκελος εργασίας`,"disk.role.task":`Ορισμένος πάνω στην ίδια τη λήψη`,"settings.volume.title":`Ανώτατο όριο όγκου`,"settings.volume.titleHint":`Τι έχει κατεβάσει ολοκληρωμένο αυτό το στιγμιότυπο, μετρημένο πάνω σε ένα ανώτατο όριο που ορίζεις εσύ, ανά περίοδο. Μετριέται το μέγεθος που ανακοίνωσε ο πάροχος για κάθε ολοκληρωμένη λήψη. Ό,τι τελειώνει χωρίς δηλωμένο μέγεθος μετρά ως μηδέν, και ό,τι ανεβάζει ένα torrent δεν μετρά καθόλου. Είναι μια ανάγνωση των λήψεών σου, όχι μέτρηση της γραμμής σου: τα byte που κίνησε πραγματικά ο δρομολογητής σου δεν τα βλέπει εδώ κανείς.`,"settings.volume.cap":`Ανώτατο όριο ανά περίοδο (GB)`,"settings.volume.capHint":`Το 0 σημαίνει κανένα ανώτατο όριο: ο μετρητής συνεχίζει να τρέχει και δεν κρατιέται ποτέ τίποτα πίσω. Τα gigabyte εδώ είναι δεκαδικά, όπως δίνει τον όγκο ο πάροχος της σύνδεσής σου: τα 500 GB είναι 500.000.000.000 byte και όχι 465 GiB. Οι τιμές δίσκου πιο πάνω σε αυτή τη σελίδα είναι δυαδικά GiB, άλλη μονάδα για άλλη ερώτηση.`,"settings.volume.resetDay":`Ο μετρητής ξεκινά ξανά την ημέρα`,"settings.volume.resetDayHint":`Η ημέρα του μήνα κατά την οποία ο μετρητής επιστρέφει στο μηδέν, συνήθως η ημέρα που ανανεώνεται ο όγκος σου. Σε έναν μήνα πιο σύντομο από την ημέρα που διάλεξες, ξεκινά ξανά την τελευταία ημέρα εκείνου του μήνα και δεν γλιστρά ποτέ στον επόμενο. Μετριέται με το ρολόι του διακομιστή και όχι με εκείνο του περιηγητή σου, γιατί ο διακομιστής είναι που κρατά πίσω την ουρά.`,"settings.volume.action":`Όταν συμπληρωθεί το ανώτατο όριο`,"settings.volume.actionHint":`Μια μεταφορά που ήδη τρέχει δεν διακόπτεται ποτέ, ό,τι κι αν διαλέξεις: το να σταματήσεις στη μέση ενός αρχείου πετά byte που έχεις ήδη ξοδέψει. Το «Μόνο ενημέρωση» δεν αλλάζει τίποτα και αφήνει τον μετρητή ως ολόκληρη τη λειτουργία. Το «Να μην ξεκινούν άλλες λήψεις» αφήνει να τελειώσει ό,τι τρέχει και κρατά πίσω την ουρά μέχρι να ξεκινήσει ξανά ο μετρητής, και κάθε γραμμή που περιμένει το λέει. Το «Επιβράδυνση των πάντων» αφήνει την ουρά να συνεχίσει, με την ταχύτητα από κάτω.`,"settings.volume.actionReport":`Μόνο ενημέρωση`,"settings.volume.actionPause":`Να μην ξεκινούν άλλες λήψεις`,"settings.volume.actionThrottle":`Επιβράδυνση των πάντων`,"settings.volume.throttle":`Ταχύτητα μετά το όριο (KiB/s)`,"settings.volume.throttleHint":`Το όριο που ισχύει για το υπόλοιπο της περιόδου. Είναι ένα ανώτατο όριο δίπλα στα άλλα σου όρια και ποτέ στη θέση τους: ένα νυχτερινό παράθυρο ή ο αθόρυβος διακόπτης, που ζητούν λιγότερα, εξακολουθούν να κερδίζουν. Το 0 εδώ θα σήμαινε καθόλου όριο, δηλαδή το ίδιο με το να μην υπάρχει ανώτατο όριο, οπότε ο μικρότερος χρήσιμος αριθμός είναι το 1.`,"settings.volume.noCap":`Χωρίς ανώτατο όριο`,"settings.volume.used":`Κατέβηκαν σε αυτή την περίοδο`,"settings.volume.usedOf":`{used} από {cap}`,"settings.volume.resetsOn":`Ξεκινά ξανά στις {date}`,"settings.volume.reached":`Το ανώτατο όριο συμπληρώθηκε.`,"volume.title":`Όγκος λήψεων`,"volume.titleHint":`Ολοκληρωμένες λήψεις, αθροισμένες ανά ημέρα και ανά μήνα, από το ιστορικό λήψεων. Το ιστορικό έχει δικό του ανώτατο όριο και μπορεί να αδειάσει με το χέρι, οπότε οι μήνες που έχουν πέσει έξω από το τέλος του απλώς δεν είναι εδώ. Μια λήψη που ξεκίνησες ξανά μετρά μία φορά, την ημέρα που ολοκληρώθηκε τελευταία. Το ημερολόγιο είναι του διακομιστή, σε {zone}.`,"volume.range.days":`30 ημέρες`,"volume.range.months":`12 μήνες`,"volume.split.total":`Όλα`,"volume.split.host":`Ανά πάροχο`,"volume.split.backend":`Ανά backend`,"volume.other":`Όλα τα υπόλοιπα`,"volume.empty":`Σε αυτό το διάστημα δεν έχει ολοκληρωθεί ακόμη τίποτα.`,"volume.unsizedHint":`Σε {n} από αυτές τις λήψεις ο πάροχος δεν δήλωσε ποτέ μέγεθος. Δεν προσθέτουν τίποτα στο σύνολο, οπότε ο πραγματικός αριθμός είναι μεγαλύτερος από αυτόν που σχεδιάζεται εδώ.`,"volume.trimmedHint":`Το ιστορικό είναι στο δικό του όριο, οπότε ό,τι είναι παλαιότερο από την παλαιότερη εγγραφή του λείπει και από αυτή την καμπύλη. Ανέβασε το ανώτατο όριο του ιστορικού σε αυτή τη σελίδα αν θέλεις να βλέπεις πιο πίσω.`,"volume.meter":`Όγκος`,"volume.meterHint":`Τι έχει κατέβει ολοκληρωμένο από την τελευταία επανεκκίνηση του μετρητή, μετρημένο πάνω στο ανώτατο όριο της σελίδας ρυθμίσεων Λήψεις. Ο αριθμός κινείται όταν μια λήψη ολοκληρώνεται, όχι όσο τρέχει: πηδά, αντί να σέρνεται. Αθροίζεται από το ιστορικό λήψεων, οπότε όποιος αδειάσει το ιστορικό μηδενίζει και αυτόν τον μετρητή.`,"task.waiting.volumeCap":`Περιμένει το ανώτατο όριο όγκου`,"task.reason.botCheck":`Έλεγχος για bot`,"task.reason.membersOnly":`Μόνο για μέλη`,"task.reason.geoBlocked":`Αποκλεισμένο εδώ`,"task.reason.drm":`DRM`,"task.reason.extractorBroken":`Ο ιστότοπος άλλαξε`,"events.title":`Συμβάντα`,"events.open":`Άνοιγμα της λίστας συμβάντων`,"events.titleHint":`Κάθε μήνυμα που σου δείχνει αυτό το παράθυρο καταλήγει και εδώ, οπότε μπορείς να διαβάσεις και ένα του οποίου η φούσκα έχει ήδη φύγει. Κρατιούνται τα τελευταία {max}, και σε κάθε φόρτωση της σελίδας η λίστα ξεκινά από την αρχή.`,"events.unread":`{n} μη αναγνωσμένα`,"events.empty":`Δεν έχει συμβεί ακόμη τίποτα`,"events.emptyHint":`Ό,τι σου αναφέρει στη συνέχεια το KnightLoader, θα βρίσκεται εδώ.`,"events.noMatch":`Τίποτα αυτού του είδους δεν υπάρχει στη λίστα`,"events.filterLabel":`Είδος`,"events.kind.downloads":`Λήψεις`,"events.kind.archives":`Συμπιεσμένα αρχεία`,"events.kind.captcha":`Captcha`,"events.kind.accounts":`Λογαριασμοί`,"events.kind.actions":`Ενέργειες`,"events.clear":`Άδειασμα της λίστας`,"events.jump":`Εμφάνιση της γραμμής`,"events.jumpGone":`Αυτή η λήψη δεν είναι πια στη λίστα`,"commands.openEvents":`Άνοιγμα της λίστας συμβάντων`,"list.keysHint":`Η λίστα δουλεύει και από το πληκτρολόγιο. Με το Tab μπαίνεις μέσα, με τα βέλη πηγαίνεις από γραμμή σε γραμμή, με το διάστημα παίρνεις μια γραμμή στην επιλογή ή τη βγάζεις ξανά, με Shift και ένα βέλος παίρνεις ολόκληρη περιοχή, με το Enter ανοίγεις τις ιδιότητες, και με το αριστερό και το δεξί βέλος κλείνεις και ανοίγεις έναν φάκελο. Στις Ρυθμίσεις, Συντομεύσεις είναι όλες γραμμένες.`,"settings.shortcuts.listTitle":`Πλήκτρα της λίστας`,"settings.shortcuts.listHint":`Αυτά ανήκουν στη λίστα λήψεων και στη λίστα του συλλέκτη και δεν μπορούν να πάρουν άλλη αντιστοίχιση. Λειτουργούν μόνο όσο μια γραμμή έχει την εστίαση, γι’ αυτό κανένα τους δεν παίρνει πλήκτρο από κάποια εντολή πιο πάνω.`,"keys.list.move":`Μετάβαση από γραμμή σε γραμμή`,"keys.list.moveKeep":`Μετάβαση χωρίς αλλαγή της επιλογής`,"keys.list.edges":`Μετάβαση στην πρώτη ή στην τελευταία γραμμή`,"keys.list.pick":`Προσθήκη της γραμμής στην επιλογή, ή αφαίρεσή της`,"keys.list.range":`Επέκταση της επιλογής ως τη γραμμή στην οποία πηγαίνεις`,"keys.list.properties":`Άνοιγμα των ιδιοτήτων του επιλεγμένου`,"keys.list.open":`Άνοιγμα ενός φακέλου, ή μετάβαση στον πρώτο σύνδεσμο μέσα του`,"keys.list.close":`Κλείσιμο ενός φακέλου, ή μετάβαση από έναν σύνδεσμο στον φάκελό του`,"keys.list.menu":`Άνοιγμα του μενού της γραμμής`,"settings.shortcuts.key.home":`Home`,"settings.shortcuts.key.end":`End`,"settings.shortcuts.key.delete":`Del`,"task.retry.pending":`Επανάληψη {n} από {max}, η επόμενη σε {countdown}`,"task.retry.pendingNoMax":`Επανάληψη {n}, η επόμενη σε {countdown}`,"task.retry.due":`Επανάληψη {n} από {max}, ξεκινά τώρα`,"task.retry.dueNoMax":`Επανάληψη {n}, ξεκινά τώρα`,"task.retry.compact":`{n}/{max} · {countdown}`,"task.retry.compactNoMax":`{n} · {countdown}`,"task.retry.exhausted":`Καμία επανάληψη πια, {n} από {max} χρησιμοποιήθηκαν`,"task.retry.exhaustedNoMax":`Καμία επανάληψη πια, {n} χρησιμοποιήθηκαν`,"task.retry.gaveUp":`Δεν θα δοκιμαστεί ξανά`,"task.retry.skip":`Επανάληψη τώρα`,"task.retry.skipDetail":`Ξεκινά τον σύνδεσμο αμέσως, αντί στο τέλος της αναμονής. Ο μετρητής συνεχίζει να τρέχει: αυτή είναι η επανάληψη που ήταν έτσι κι αλλιώς προγραμματισμένη, όχι μια επιπλέον.`,"task.retry.skipFailed":`Η επανάληψη δεν μπόρεσε να ξεκινήσει.`,"volume.rangeLabel":`Χρονικό διάστημα`,"volume.splitLabel":`Διαχωρισμός`,"failure.title":`Γιατί απέτυχε αυτό`,"failure.open":`Γιατί απέτυχε αυτό`,"failure.raw":`Τι είπε το backend`,"failure.rawHint":`Η γραμμή που τύπωσε το ίδιο το εργαλείο, αμετάβλητη και στα αγγλικά. Χρήσιμη όταν την ψάχνεις ή τη δηλώνεις κάπου. Η πρόταση από πάνω είναι η ερμηνεία αυτής της εφαρμογής.`,"failure.nothingToDo":`Τίποτα μέσα στο KnightLoader δεν αλλάζει αυτό εδώ.`,"failure.close":`Κλείσιμο`,"failure.botCheck.line":`Ο ιστότοπος θέλει συνδεδεμένη συνεδρία πριν δώσει το βίντεο.`,"failure.botCheck.hint":`Η αναμονή, μια πιο αργή λήψη ή μια άλλη ταυτότητα περιηγητή δεν αλλάζουν τίποτα εδώ. Μόνο cookies από περιηγητή στον οποίο είσαι πραγματικά συνδεδεμένος. Εξήγαγε την cookies.txt του ιστότοπου από εκείνον τον περιηγητή και επικόλλησέ την εδώ: φυλάσσεται στον κρυπτογραφημένο χώρο διαπιστευτηρίων, δίνεται στο yt-dlp ως αρχείο που μόνο αυτός ο διακομιστής μπορεί να διαβάσει, και διαγράφεται ξανά μόλις τελειώσει η λήψη.`,"failure.botCheck.action":`Αποθήκευση cookies για αυτόν τον ιστότοπο`,"failure.membersOnly.line":`Μόνο για μέλη, και η λήψη έφτασε χωρίς συνδρομή μέλους.`,"failure.membersOnly.hint":`Το yt-dlp φτάνει ως αυτός που λένε τα αποθηκευμένα cookies. Συνδέσου με τον λογαριασμό που έχει τη συνδρομή μέλους, εξήγαγε από εκείνον τον περιηγητή την cookies.txt του ιστότοπου και επικόλλησέ την. Χωρίς συνδρομή μέλους σε εκείνον τον λογαριασμό, τίποτα εδώ δεν αλλάζει την απάντηση.`,"failure.membersOnly.action":`Αποθήκευση cookies για αυτόν τον ιστότοπο`,"failure.geoBlocked.line":`Ο ιστότοπος δεν δίνει αυτό το βίντεο σε αυτή την περιοχή.`,"failure.geoBlocked.hint":`Τα cookies δεν βοηθούν: αποκλεισμένη είναι η διεύθυνση και όχι ο λογαριασμός. Το KnightLoader δεν μπορεί ούτε να στείλει μια λήψη του yt-dlp μέσα από μία από τις ονομασμένες συνδέσεις του, γιατί το yt-dlp τρέχει ως δική του διεργασία και παίρνει τον διαμεσολαβητή του από το περιβάλλον μέσα στο οποίο ξεκίνησε αυτός ο διακομιστής. Η λύση βρίσκεται λοιπόν έξω από αυτό το παράθυρο: ξεκίνα τον διακομιστή πίσω από ένα VPN, ή όρισε γι’ αυτόν τα HTTP_PROXY και HTTPS_PROXY.`,"failure.gone.line":`Η πηγή λέει ότι αυτό δεν υπάρχει πια.`,"failure.gone.hint":`Διαγράφηκε, κατέβηκε ή τέθηκε σε ιδιωτικό στην πηγή. Κανένας λογαριασμός και καμία νέα προσπάθεια δεν το φέρνει πίσω, και κάθε επόμενη προσπάθεια απλώς κάνει τον πάροχο να επαναλάβει την ίδια απάντηση. Η αφαίρεση βγάζει τη γραμμή από τη λίστα, ό,τι έχει ήδη κατέβει μένει στον δίσκο.`,"failure.gone.action":`Αφαίρεση αυτού του συνδέσμου`,"failure.drm.line":`Αυτό το βίντεο είναι κρυπτογραφημένο, και το yt-dlp δεν το αποκρυπτογραφεί.`,"failure.drm.hint":`Το DRM δεν είναι φράγμα που το προσπερνά μια σύνδεση ή μια άλλη διεύθυνση: τα δεδομένα φτάνουν κρυπτογραφημένα, και το κλειδί το παίρνει μόνο ένα πρόγραμμα αναπαραγωγής που εμπιστεύεται ο ιστότοπος. Δεν υπάρχει τίποτα να ρυθμίσεις γι’ αυτό. Οι άλλες γραμμές του ίδιου συνδέσμου, η μικρογραφία, η περιγραφή και οι υπότιτλοι, συνήθως δεν επηρεάζονται και μπορούν να μείνουν.`,"failure.drm.action":`Αφαίρεση αυτού του συνδέσμου`,"failure.extractorBroken.line":`Ο ιστότοπος άλλαξε, και το yt-dlp αυτής της έκδοσης δεν βγάζει πια έξω το βίντεο.`,"failure.extractorBroken.hint":`Το ίδιο το yt-dlp το είπε: δεν μπόρεσε να διαβάσει τη σελίδα και ζήτησε αναφορά σφάλματος. Σχεδόν πάντα ο ιστότοπος έχει μετακινήσει κάτι, και ένα νεότερο yt-dlp τα καταφέρνει ξανά μέσα σε λίγες ημέρες. Το yt-dlp βρίσκεται μέσα στην εικόνα του KnightLoader, οπότε ο δρόμος προς μια νεότερη έκδοση είναι μια νεότερη εικόνα και όχι ένα κουμπί εδώ μέσα: αυτός ο διακομιστής δεν επιτρέπεται να το αντικαταστήσει και, μέσα σε container, δεν θα είχε πού να βάλει ένα νέο αντίγραφο.`,"cookies.title":`Cookies για {host}`,"cookies.addTitle":`Αποθήκευση cookies για έναν ιστότοπο`,"cookies.add":`Προσθήκη ιστότοπου`,"cookies.save":`Αποθήκευση και νέα προσπάθεια`,"cookies.saved":`Τα cookies αποθηκεύτηκαν.`,"cookies.hostHint":`Το αρχείο αναζητείται με βάση αυτόν τον κόμβο και κάθε τομέα από πάνω του, από το πιο ειδικό προς το πιο γενικό, οπότε ένα αποθηκευμένο ως youtube.com είναι και αυτό που χρησιμοποιεί ένας σύνδεσμος του music.youtube.com. Ο διακομιστής γράφει το όνομα με πεζά, αφαιρεί ένα αρχικό www. και κόβει μια ολόκληρη επικολλημένη διεύθυνση στον ίδιο τον ιστότοπο, γι’ αυτό η λίστα μπορεί να τον ονομάζει λίγο διαφορετικά από ό,τι τον πληκτρολόγησες.`,"cookies.jarHint":`Επικόλλησε ό,τι σου δίνει ένας εξαγωγέας cookies, στη μορφή Netscape, μαζί με τις γραμμές σχολίων. Αποθηκεύεται ακριβώς όπως το επικολλάς: το να αναμορφώσεις ένα αρχείο που πάει να διαβάσει το yt-dlp είναι ο δρόμος για να δουλεύει σε ένα εργαλείο και στο άλλο όχι.`,"cookies.useStoredHint":`Ένας διακόπτης για ολόκληρο το στιγμιότυπο, όχι γι’ αυτόν τον σύνδεσμο: όσο είναι κλειστός, ένα αποθηκευμένο αρχείο δεν πηγαίνει πουθενά, και το να επικολλήσεις ένα εδώ δεν αλλάζει τίποτα. Ανήκει σε ό,τι κάνει η Αποθήκευση και δεν είναι ζωντανή ένδειξη της ρύθμισης: βλέπεις τι πρόκειται να αφήσει πίσω του αυτό το παράθυρο. Και είναι διακόπτης, όχι κάτι αυτόματο, γιατί μια συνδεδεμένη συνεδρία έχει συνέπειες: ένα όριο ή μια απαγόρευση χτυπά τον λογαριασμό και όχι τη διεύθυνση.`,"select.hidden":`από αυτά {n} μη ορατά`,"select.hiddenTip":`Στην επιλογή βρίσκονται και γραμμές που κρύβουν αυτή τη στιγμή η αναζήτηση, ένα φίλτρο ή ένα συμπτυγμένο πακέτο, και το Del τις παίρνει μαζί. Κάντε κλικ στον αριθμό για να φύγουν από την επιλογή και να μείνουν μόνο οι γραμμές που βλέπετε.`,"select.reduceKeep":`Διατήρηση μόνο των ορατών γραμμών`,"select.reduceKeepAria":`{n} επιλεγμένες γραμμές δεν είναι ορατές. Κάντε κλικ για να κρατήσετε μόνο τις ορατές.`,"select.reduceRemove":`Αφαίρεση μόνο των ορατών γραμμών`,"select.reduceRemoveAria":`{n} από τις γραμμές που πρόκειται να φύγουν δεν είναι ορατές. Κάντε κλικ για να αφαιρεθούν μόνο οι ορατές.`,"select.reduced":`Βγήκαν {n} γραμμές από την επιλογή.`,"remove.doneHidden":`Αφαιρέθηκαν {n} λήψεις. Οι {hidden} από αυτές δεν ήταν στην οθόνη.`,"settings.dbmaint.title":`Συντήρηση βάσης δεδομένων`,"settings.dbmaint.hint":`Η λίστα εργασιών, το ιστορικό λήψεων και η κατάσταση της διεπαφής βρίσκονται μαζί σε ένα αρχείο SQLite. Οι διαγραμμένες γραμμές ελευθερώνουν χώρο μέσα στο αρχείο, αλλά ποτέ πίσω στον δίσκο. Μετά από μερικά χρόνια το αρχείο είναι γι’ αυτό συχνά πολλαπλάσιο του περιεχομένου του. Ο έλεγχος διαβάζει κάθε σελίδα και λέει αν το αρχείο είναι ακόμη ακέραιο. Η συμπύκνωση το ξαναγράφει στο πραγματικό του μέγεθος. Και τα δύο τρέχουν πάνω στη ζωντανή βάση δεδομένων και κρατούν όσο διαρκούν κάθε άλλη εγγραφή σε αναμονή.`,"settings.dbmaint.storeSize":`Αρχείο βάσης δεδομένων`,"settings.dbmaint.storeSizeHint":`Η βάση δεδομένων, μαζί με ένα αρχείο journal δίπλα της, αν το SQLite κρατά αυτή τη στιγμή κάποιο ανοιχτό.`,"settings.dbmaint.reclaimable":`Ελεύθερο μέσα στο αρχείο`,"settings.dbmaint.reclaimableHint":`Χώρος που άφησαν πίσω τους οι διαγραμμένες γραμμές. Ανήκει ακόμη στο αρχείο πάνω στον δίσκο, και μόνο η συμπύκνωση τον δίνει πίσω. Ο αριθμός είναι κάτω όριο: στη συμπύκνωση ξαναπακετάρονται και οι μισογεμάτες σελίδες, οπότε συνήθως επιστρέφουν περισσότερα.`,"settings.dbmaint.settingsSize":`settings.json`,"settings.dbmaint.settingsMissing":`Δεν έχει γραφτεί ακόμη`,"settings.dbmaint.settingsMissingHint":`Αυτό το αρχείο γράφεται μόνο την πρώτη φορά που θα αποθηκεύσετε μια σελίδα ρυθμίσεων. Μέχρι τότε το στιγμιότυπο τρέχει με τις ενσωματωμένες προεπιλογές.`,"settings.dbmaint.inBundle":`Αυτά τα μεγέθη βρίσκονται και στο πακέτο διαγνωστικών. Οι διαδρομές όχι: το πακέτο πρέπει να μπορεί να επισυναφθεί σε μια δημόσια αναφορά σφάλματος.`,"settings.dbmaint.check":`Έλεγχος ακεραιότητας`,"settings.dbmaint.checkHint":`Διαβάζει κάθε σελίδα της βάσης δεδομένων και αναφέρει τι βρίσκει το SQLite. Γίνεται μόνο ανάγνωση, δεν αλλάζει τίποτα. Σε μεγάλο αρχείο αυτό παίρνει ώρα, και όσο τρέχει τίποτα άλλο δεν μπορεί να γράψει στη βάση δεδομένων.`,"settings.dbmaint.compact":`Συμπύκνωση`,"settings.dbmaint.compactHint":`Ξαναγράφει ολόκληρο το αρχείο στο πραγματικό του μέγεθος. Γι’ αυτό χρειάζεται χώρος για ένα πλήρες δεύτερο αντίγραφο της βάσης δεδομένων, και αυτό καταλήγει στον προσωρινό φάκελο, όχι στον φάκελο δεδομένων.`,"settings.dbmaint.analyze":`Ανανέωση στατιστικών ερωτημάτων`,"settings.dbmaint.analyzeHint":`Αφήνει το SQLite να μετρήσει ξανά τους πίνακες, ώστε να διαλέγει καλύτερα πλάνα για τα ερωτήματα της λίστας και του ιστορικού. Γίνεται γρήγορα και δεν αλλάζει δεδομένα. Τα ερωτήματα που ετοιμάστηκαν νωρίτερα κρατούν το παλιό τους πλάνο, οπότε η επίδραση είναι πλήρης το αργότερο μετά την επόμενη επανεκκίνηση.`,"settings.dbmaint.running":`Σε εξέλιξη…`,"settings.dbmaint.busy":`Κάτι τρέχει ήδη. Περιμένετε να τελειώσει.`,"settings.dbmaint.neverRun":`Σε αυτό το στιγμιότυπο δεν έχει τρέξει ακόμη τίποτα.`,"settings.dbmaint.lastRun":`Τελευταία εκτέλεση {when}, διήρκεσε {seconds} δευτ.`,"settings.dbmaint.checkOk":`Ακέραιο. Το SQLite διάβασε κάθε σελίδα και δεν βρήκε τίποτα.`,"settings.dbmaint.checkFailed":`Κατεστραμμένο. Το SQLite αναφέρει {n} προβλήματα.`,"settings.dbmaint.checkFailedHelp":`Μην κάνετε επανεκκίνηση του διακομιστή. Με μια βάση δεδομένων που δεν μπορεί να ανοίξει δεν ξεκινά καν, και ένα container με δικό του κανόνα επανεκκίνησης γυρίζει τότε σε κύκλο. Πάρτε πρώτα το κουμπί λήψης κάτω από το «Αντίγραφο ασφαλείας & Επαναφορά» και βάλτε το αρχείο σε ασφαλές μέρος· σε βαριά κατεστραμμένη βάση δεδομένων μπορεί να αποτύχει και αυτό. Αν αποτύχει, σταματήστε τον διακομιστή και αντιγράψτε το {path} στο πλάι με το χέρι, πριν το ακουμπήσει οτιδήποτε άλλο. Μετά επαναφέρετε το τελευταίο καλό αντίγραφο ασφαλείας μέσω της Επαναφοράς.`,"settings.dbmaint.compacted":`Πριν {before}, μετά {after}. {freed} ξανά στον δίσκο.`,"settings.dbmaint.compactedNothing":`Πριν και μετά {before}. Δεν υπήρχε τίποτα να επιστραφεί.`,"settings.dbmaint.analyzed":`Τα στατιστικά ανανεώθηκαν.`,"settings.dbmaint.failed":`Δεν ολοκληρώθηκε: {error}`,"settings.dbmaint.diskFullHelp":`Στη συμπύκνωση γράφεται πρώτα ένα πλήρες δεύτερο αντίγραφο της βάσης δεδομένων και μετά αντικαθίσταται το πρωτότυπο. Αυτό το αντίγραφο καταλήγει στον προσωρινό φάκελο, όχι στον φάκελο δεδομένων. Εδώ είναι ο {tmp}, με {free} ελεύθερα. Δείξτε με το TMPDIR σε έναν φάκελο στον ίδιο τόμο με τον φάκελο δεδομένων σας και δοκιμάστε ξανά.`,"settings.dbmaint.skippedBusy":`Η προγραμματισμένη εκτέλεση παραλείφθηκε επειδή έτρεχαν λήψεις.`,"settings.dbmaint.interval":`Να τρέχει από μόνη της`,"settings.dbmaint.intervalHint":`Σε μια υπάρχουσα εγκατάσταση είναι κλειστό, και μετά από ενημέρωση παραμένει κλειστό: τίποτα δεν αρχίζει να τρέχει από μόνο του μόνο και μόνο επειδή εγκαταστήσατε μια νέα έκδοση. Όταν το ανάψετε, η πρώτη εκτέλεση απέχει ένα ολόκληρο διάστημα, όχι τώρα αμέσως. Αν εκείνη τη στιγμή τρέχει κάποια λήψη, η εκτέλεση παραλείπεται και δεν μπαίνει σε αναμονή.`,"settings.dbmaint.intervalNever":`Μόνο με πάτημα κουμπιού`,"settings.dbmaint.interval30":`Κάθε 30 ημέρες`,"settings.dbmaint.interval90":`Κάθε 90 ημέρες`,"settings.dbmaint.interval180":`Κάθε 180 ημέρες`,"settings.dbmaint.nextRun":`Επόμενη εκτέλεση {when}.`,"settings.dbmaint.compactOnSchedule":`Συμπύκνωση και στην προγραμματισμένη εκτέλεση`,"settings.dbmaint.compactOnScheduleHint":`Κλειστό σημαίνει: η προγραμματισμένη εκτέλεση μόνο διαβάζει και αναφέρει. Η συμπύκνωση ξαναγράφει ολόκληρο το αρχείο και χρειάζεται γι’ αυτό χώρο για ένα δεύτερο αντίγραφό του στον προσωρινό τόμο. Μην το ανάβετε λοιπόν χωρίς να ξέρετε ότι αυτός ο χώρος υπάρχει. Το κουμπί Συμπύκνωση παραπάνω συμπυκνώνει πάντα όταν το πατάτε, ό,τι κι αν λέει εδώ.`,"settings.dbmaint.confirmTitle":`Συμπύκνωση της βάσης δεδομένων;`,"settings.dbmaint.confirmBody":`Το αρχείο ξαναγράφεται εξ ολοκλήρου από την αρχή. Μέχρι να τελειώσει αυτό, τίποτα άλλο δεν μπορεί να γράψει μέσα του, και στα {size} μπορεί να πάρει ώρα. Οι λήψεις συνεχίζονται, αλλά ό,τι αναφέρουν καταγράφεται μόνο μετά.`,"settings.dbmaint.loadFailed":`Δεν ήταν δυνατή η ανάγνωση του μεγέθους της βάσης δεδομένων. Είναι προσβάσιμος ο διακομιστής;`,"overview.speedWindow":`Χρονικό παράθυρο της καμπύλης`,"overview.speedWindow.minute":`Τελευταίο λεπτό`,"overview.speedWindow.hour":`Τελευταία ώρα`,"overview.speedGraphHint":`Το στιγμιότυπο καταγράφει το ίδιο αυτή την καμπύλη: μία τιμή ανά δευτερόλεπτο για τα τελευταία δύο λεπτά, μία ανά δέκα δευτερόλεπτα για την τελευταία ώρα. Γι’ αυτό, μετά την επαναφόρτωση της σελίδας, είναι ήδη γεμάτη αντί να ξεκινά επίπεδη. Η καταγραφή βρίσκεται μόνο στη μνήμη εργασίας: αν κάνετε επανεκκίνηση του KnightLoader, είναι άδεια, η καμπύλη ξεκινά πάλι ως επίπεδη γραμμή και γεμίζει με την πάροδο του χρόνου.`,"settings.diagnostics.speedSamples":`Καταγεγραμμένες τιμές ταχύτητας`,"settings.diagnostics.speedSamplesHint":`Από πόσες τιμές σχεδιάζεται αυτή τη στιγμή η καμπύλη ταχύτητας στην Επισκόπηση, σε σχέση με αυτό που κρατά το πολύ: πρώτα η καταγραφή των δύο λεπτών, μετά εκείνη της μίας ώρας. Αν και στις δύο υπάρχει μηδέν, δεν καταγράφει τίποτα, και η καμπύλη στην Επισκόπηση θα μείνει επίπεδη μέχρι να διορθωθεί αυτό. Μετά από κάθε επανεκκίνηση η καταγραφή ξεκινά άδεια, και στον δίσκο δεν γράφεται ποτέ.`,"settings.downloads.idleActionQuit":`Έξοδος από το KnightLoader`,"settings.downloads.idleActionCommand":`Εκτέλεση εντολής`,"settings.downloads.idleActionSuspend":`Αναστολή λειτουργίας αυτού του υπολογιστή`,"settings.downloads.idleDeploymentContainer":`Αυτό εδώ τρέχει μέσα σε κοντέινερ. Η διεργασία του είναι το PID 1 στον δικό της χώρο ονομάτων: η έξοδος σταματά το κοντέινερ και τίποτα άλλο, και τον υπολογιστή από κάτω δεν μπορεί να τον βάλει σε αναστολή, γιατί στην κατάσταση ρεύματος εκείνου του υπολογιστή δεν φτάνει τίποτα από μέσα από το κοντέινερ. Το αν το κοντέινερ ξαναέρχεται μετά την έξοδο το αποφασίζει ο κανόνας επανεκκίνησης που του έδωσες, όχι αυτή η ρύθμιση. Αν θέλεις να κοιμηθεί ο host, βάλε εδώ μια εντολή που φτάνει στον host.`,"settings.downloads.idleDeploymentDesktop":`Αυτή εδώ είναι η έκδοση για υπολογιστή, μπορεί λοιπόν να βάλει αυτόν τον υπολογιστή σε αναστολή. Η έξοδος δεν προσφέρεται εδώ, γιατί το παράθυρο και η περιοχή ειδοποιήσεων κλείνουν ήδη την εφαρμογή με καθαρό τρόπο.`,"settings.downloads.idleQuitHint":`Η έξοδος αφήνει να ολοκληρωθεί ό,τι είναι σε εξέλιξη και σταματά τη διεργασία, ακριβώς όπως το κουμπί Έξοδος στη σελίδα Για προχωρημένους. Το αν ξεκινήσει ξανά μετά το αποφασίζει ο κανόνας επανεκκίνησης του κοντέινερ σου, όχι αυτή η ρύθμιση.`,"settings.downloads.idleSuspendHint":`Η αναστολή ζητά από το λειτουργικό σύστημα να βάλει αυτόν τον υπολογιστή σε εξοικονόμηση ενέργειας. Δουλεύει μόνο εκεί όπου το σύστημα αφήνει αυτή την εφαρμογή να ρωτήσει: στο Linux η διαχείριση δικαιωμάτων μπορεί να αρνηθεί, και τότε ο λόγος γράφεται κάτω από την τελευταία εκτέλεση.`,"settings.downloads.idleCommandProgram":`Πρόγραμμα`,"settings.downloads.idleCommandProgramHint":`Η πλήρης διαδρομή του προγράμματος που εκτελείται. Τρέχει απευθείας και όχι μέσω κελύφους, άρα μια διοχέτευση, μια ανακατεύθυνση ή δύο εντολές στη σειρά ανήκουν σε ένα αρχείο σεναρίου, στο οποίο δείχνεις από εδώ. Δεν αντικαθίσταται τίποτα μέσα του: ό,τι γράφεις εδώ, αυτό ακριβώς τρέχει.`,"settings.downloads.idleCommandArgs":`Ορίσματα`,"settings.downloads.idleCommandArgsHint":`Ένα ανά γραμμή, ώστε ένα όρισμα με κενό μέσα του να μένει ένα όρισμα.`,"settings.downloads.idleCommandTimeout":`Διακοπή μετά από (δευτερόλεπτα)`,"settings.downloads.idleCommandTimeoutHint":`Πόση ώρα επιτρέπεται να τρέχει το πρόγραμμα πριν σταματήσει. Το να σταματήσει δεν είναι το ίδιο με το να έχει αποτύχει: μια εντολή που βάζει έναν υπολογιστή σε αναστολή μπορεί να σκοτωθεί στον δρόμο και να έχει κάνει τη δουλειά της παρ’ όλα αυτά.`,"settings.downloads.idleCommandSecretHint":`Η γραμμή εντολών αποθηκεύεται σε απλό κείμενο στο settings.json και ταξιδεύει μέσα σε κάθε αντίγραφο ασφαλείας, οπότε κράτα έξω από αυτήν κωδικούς και διακριτικά: βάλ’ τα σε ένα αρχείο που το διαβάζει μόνο το πρόγραμμα. Από το πακέτο διαγνωστικών μένει έξω, και σε αυτή τη σελίδα δεν εμφανίζεται ξανά, γι’ αυτό το πλαίσιο παραπάνω είναι άδειο μόλις αποθηκευτεί κάτι.`,"settings.downloads.idleCommandStored":`Μια εντολή είναι αποθηκευμένη και δεν εμφανίζεται ξανά εδώ. Γράψε κάτι για να την αντικαταστήσεις.`,"settings.downloads.idleCommandStoredShort":`η αποθηκευμένη εντολή`,"settings.downloads.idleCommandVerify":`Πριν το κάνει η αντίστροφη μέτρηση`,"settings.downloads.idleCommandVerifyHint":`Ο έλεγχος μόνο εντοπίζει το πρόγραμμα και λέει τι βρήκε, οπότε το πάτημά του δεν κοστίζει τίποτα. Η εκτέλεση κάνει ακριβώς ό,τι θα έκανε η αντίστροφη μέτρηση, σε αυτό το στιγμιότυπο και τώρα αμέσως. Και τα δύο ρωτούν για ό,τι είναι αποθηκευμένο, αποθήκευσε λοιπόν πρώτα τη σελίδα: όσο κάτι εδώ είναι μη αποθηκευμένο, τα δύο κουμπιά μένουν σβηστά.`,"settings.downloads.idleCommandCheck":`Έλεγχος της εντολής`,"settings.downloads.idleCommandChecking":`Γίνεται έλεγχος…`,"settings.downloads.idleCommandCheckOk":`Βρέθηκε στο {path}. Καλείται ως: {argv}`,"settings.downloads.idleCommandRun":`Εκτέλεση τώρα`,"settings.downloads.idleCommandRunConfirm":`Έτσι τρέχει το {program} τώρα αμέσως, σε αυτό το στιγμιότυπο, ακριβώς όπως θα το έκανε η αντίστροφη μέτρηση.`,"settings.downloads.idleArmHint":`Αν αποθηκεύσεις αυτή τη σελίδα ενώ η ουρά είναι ήδη άδεια, η αντίστροφη μέτρηση ξεκινά αμέσως. Δεν περιμένει να τελειώσει η επόμενη παρτίδα.`,"idleAction.action.quit":`Γίνεται έξοδος`,"idleAction.action.command":`Η εντολή τρέχει`,"idleAction.action.suspend":`Ο υπολογιστής μπαίνει σε αναστολή`,"idleAction.lastRun":`Τελευταία εκτέλεση`,"idleAction.lastRunHint":`Από την τελευταία εκκίνηση αυτού του στιγμιότυπου. Εδώ τίποτα δεν επιβιώνει μιας επανεκκίνησης, οπότε μια έξοδος που πέτυχε δεν αφήνει καμία γραμμή: η καταχώριση έφυγε μαζί με τη διεργασία.`,"idleAction.lastRunNever":`Αυτό δεν έχει τρέξει ακόμη ποτέ.`,"idleAction.lastRunOk":`Έτρεξε στις {at} και δεν είχε τίποτα να αναφέρει.`,"idleAction.lastRunFailed":`Απέτυχε στις {at}.`,"idleAction.problem.empty":`Δεν έχει οριστεί πρόγραμμα, άρα δεν τρέχει τίποτα. Γράψε παραπάνω την πλήρη διαδρομή του προγράμματος.`,"idleAction.problem.notFound":`Το {program} δεν υπάρχει σε αυτό το στιγμιότυπο.`,"idleAction.problem.notFoundContainer":`Το {program} δεν υπάρχει μέσα σε αυτό το κοντέινερ. Εδώ υπάρχει μόνο ό,τι φέρνει μαζί του το image: κανένα systemd, κανένα curl, κανένα ssh, κανένα sudo. Βάλε την εντολή στον host και κάλεσέ την από εδώ, ή δείξε από εδώ σε ένα σενάριο που έχεις προσαρτήσει μέσα στο κοντέινερ.`,"idleAction.problem.notExecutable":`Το {path} υπάρχει, αλλά δεν εκτελείται. Βάλε του το δικαίωμα εκτέλεσης και φρόντισε ο χρήστης με τον οποίο τρέχει αυτή η διεργασία να μπορεί να το διαβάσει: στο κοντέινερ αυτός είναι το uid 1000, όχι ο root.`,"idleAction.problem.permission":`Το σύστημα αρνήθηκε: αυτή η διεργασία δεν επιτρέπεται να το κάνει. Στο κοντέινερ τρέχει ως uid 1000, χωρίς root και χωρίς καμία πρόσβαση στον host, οπότε ό,τι αλλάζει την κατάσταση ρεύματος του υπολογιστή πρέπει να γίνει στον ίδιο τον host.`,"idleAction.problem.timeout":`Το πρόγραμμα έτρεχε ακόμη μετά από {seconds} δευτερόλεπτα και σταμάτησε. Κάλλιστα μπορεί να έχει κάνει τη δουλειά του παρ’ όλα αυτά. Ανέβασε το όριο, αν η εντολή πρέπει να παίρνει περισσότερη ώρα.`,"idleAction.problem.exit":`Το πρόγραμμα σταμάτησε με κωδικό εξόδου {code}. Η δική του έξοδος: {output}`,"idleAction.problem.notSupported":`Αυτό το build δεν μπορεί να το εκτελέσει. Διάλεξε άλλη ενέργεια στο τέλος της ουράς.`,"idleAction.problem.suspendRefused":`Το σύστημα αρνήθηκε την αναστολή. Στο Linux συνήθως η διαχείριση δικαιωμάτων θέλει μια επιβεβαίωση που αυτή η εφαρμογή δεν μπορεί να δώσει: επίτρεψε την αναστολή για τον χρήστη σου, ή γύρνα στο «Εκτέλεση εντολής» και βάλε τον υπολογιστή σε αναστολή μέσα από δικό σου σενάριο.`,"idleAction.runFailed":`Η εντολή δεν μπόρεσε να ξεκινήσει.`,"idleAction.failedTitle":`Η ενέργεια στο τέλος της ουράς δεν πέτυχε`,"idleAction.openSettings":`Στη ρύθμιση`,"idleAction.dismiss":`Απόκρυψη`,"settings.transfer.title":`Μόνο οι ρυθμίσεις`,"settings.transfer.hint":`Γράφει το settings.json σε ένα αρχείο: όρια ουράς, φακέλους, σύνολα κανόνων, κατηγορίες και χρονοδιάγραμμα. Όχι τη λίστα λήψεων και όχι το ιστορικό. Το αρχείο το αποθηκεύει ο περιηγητής σου, δεν πηγαίνει πουθενά αλλού.`,"settings.transfer.export":`Εξαγωγή ρυθμίσεων`,"settings.transfer.exportHint":`Αποθηκεύει ένα αρχείο .json. Κάνε το εισαγωγή στο νέο μηχάνημα και διάλεξε εκεί τι θα μεταφερθεί.`,"settings.transfer.import":`Εισαγωγή ρυθμίσεων`,"settings.transfer.importHint":`Πριν δεις τη λίστα και την επιβεβαιώσεις, δεν γράφεται τίποτα. Αλλάζει μόνο ό,τι επιλέξεις, όλα τα άλλα μένουν όπως είναι εδώ. Χωρίς επανεκκίνηση.`,"settings.transfer.withSecrets":`Να συμπεριληφθούν οι αποθηκευμένοι κωδικοί`,"settings.transfer.withSecretsHint":`Αναμμένο: το αρχείο κουβαλά τον κωδικό του δρομολογητή, κάθε κωδικό διαμεσολαβητή και κάθε κωδικό συμπιεσμένου αρχείου σε απλό κείμενο. Σβηστό: αυτά τα πεδία φτάνουν άδεια στο άλλο μηχάνημα και τα πληκτρολογείς εκεί μία φορά. Και στις δύο περιπτώσεις μπορεί να κάθεται ένα μυστικό κάπου που δεν το αναγνωρίζει τίποτα εδώ: μια διεύθυνση ροής με κλειδί API μέσα της, ή ένας κωδικός γραμμένος μέσα σε ένα σενάριο επανασύνδεσης.`,"settings.transfer.notTravellingLabel":`Τι δεν ταξιδεύει ποτέ`,"settings.transfer.notTravelling":`Τι δεν περιέχει ποτέ αυτό το αρχείο: τα στοιχεία σύνδεσης debrid και hoster, τα προφίλ κεφαλίδων, τα κλειδιά captcha, τον κωδικό πρόσβασης για αυτή τη διεπαφή και τα σενάριά σου. Αυτά βρίσκονται κρυπτογραφημένα έξω από το settings.json, και ούτε το πλήρες αντίγραφο ασφαλείας τα κουβαλά. Αυτά τα στήνεις ξανά στο νέο μηχάνημα.`,"settings.transfer.previewTitle":`Τι να μεταφερθεί;`,"settings.transfer.previewFrom":`Από την έκδοση {version}, {date}`,"settings.transfer.previewSecretless":`Αυτό το αρχείο εξήχθη χωρίς κωδικούς. Οι γραμμές που σημειώνονται παρακάτω φτάνουν χωρίς τον δικό τους.`,"settings.transfer.colStored":`Εδώ τώρα`,"settings.transfer.colFile":`Στο αρχείο`,"settings.transfer.same":`Ίδιο`,"settings.transfer.unknownKey":`Αυτό το build δεν γνωρίζει αυτή τη ρύθμιση, οπότε δεν μπορεί να μεταφερθεί.`,"settings.transfer.identityKey":`Ανήκει σε αυτό το μηχάνημα και δεν μεταφέρεται ποτέ`,"settings.transfer.identityKeyHint":`Μέσω του αναγνωριστικού στιγμιότυπου μιλούν σε αυτό το μηχάνημα ο αναμεταδότης και κάθε ζευγαρωμένο αδελφό στιγμιότυπο. Δύο μηχανήματα με το ίδιο αναγνωριστικό συγκρούονται μέσα στην ίδια ομάδα, γι’ αυτό μένει εκεί όπου δημιουργήθηκε.`,"settings.transfer.noPassword":`Φτάνει χωρίς τον κωδικό του. Συμπλήρωσέ τον μετά.`,"settings.transfer.wholeList":`Αντικαθιστά ολόκληρη τη λίστα εδώ, γραμμή προς γραμμή`,"settings.transfer.newFolder":`Αυτόν τον φάκελο δεν τον έχει ακόμη εδώ. Στην αποθήκευση δημιουργείται, ακόμη και μέσα σε κοντέινερ όπου δεν κρέμεται αντίστοιχος τόμος.`,"settings.transfer.selectAll":`Όλα`,"settings.transfer.selectNone":`Κανένα`,"settings.transfer.selectChanged":`Μόνο ό,τι διαφέρει`,"settings.transfer.apply":`Μεταφορά {n}`,"settings.transfer.cancel":`Άκυρο`,"settings.transfer.applying":`Γίνεται μεταφορά…`,"settings.transfer.nothingSelected":`Δεν επιλέχθηκε τίποτα.`,"settings.transfer.applied":`{n} ρυθμίσεις μεταφέρθηκαν. Δεν έγινε καμία επανεκκίνηση.`,"settings.transfer.incomplete":`Εδώ λείπει ακόμη ένας κωδικός: {fields}`,"settings.transfer.incompleteReconnect":`ο κωδικός του δρομολογητή`,"settings.transfer.incompleteConnections":`οι κωδικοί των διαμεσολαβητών`,"settings.transfer.incompleteArchives":`οι κωδικοί των συμπιεσμένων αρχείων`,"settings.transfer.ruleProblems":`Ήρθαν μαζί {n} κανόνες που αυτό το build δεν μπορεί να μεταγλωττίσει. Αποθηκεύονται και δεν ενεργοποιούνται ποτέ. Ρίξε μια ματιά στη σελίδα Κανόνες.`,"settings.transfer.parseFailed":`Αυτό δεν είναι εξαγωγή ρυθμίσεων: {reason}`,"settings.transfer.tooNew":`Αυτό το αρχείο γράφτηκε από την {version} και αυτός ο διακομιστής τρέχει την {running}. Ενημέρωσε πρώτα τον διακομιστή, μετά κάνε την εισαγωγή.`,"settings.transfer.applyFailed":`Δεν έγινε η μεταφορά: {error}`,"settings.transfer.group.queue":`Ουρά και ταχύτητα`,"settings.transfer.group.folders":`Φάκελοι`,"settings.transfer.group.archives":`Συμπιεσμένα αρχεία`,"settings.transfer.group.rules":`Κανόνες και κατηγορίες`,"settings.transfer.group.schedule":`Χρονοδιάγραμμα και αθόρυβη λειτουργία`,"settings.transfer.group.network":`Συνδέσεις και επανασύνδεση`,"settings.transfer.group.resolvers":`Backends`,"settings.transfer.group.look":`Εμφάνιση`,"settings.transfer.group.other":`Όλα τα υπόλοιπα`,"settings.mediahook.title":`Ειδοποίηση της βιβλιοθήκης πολυμέσων`,"settings.mediahook.hint":`Μια διεύθυνση που το KnightLoader καλεί μία φορά, μόλις το τελευταίο αρχείο ενός πακέτου φτάσει και μετακινηθεί στη θέση του. Είναι φτιαγμένη για μια σάρωση βιβλιοθήκης σε Jellyfin ή Plex, αλλά το πεδίο δεν ξέρει τίποτα ούτε για το ένα ούτε για το άλλο: καλεί τη διεύθυνση που γράφεις, με τη μέθοδο που διαλέγεις, και προσθέτει μία κεφαλίδα, αν δώσεις κάποια. Η τιμή της κεφαλίδας φυλάγεται κρυπτογραφημένη στον ίδιο χώρο με τα στοιχεία των λογαριασμών σου και δεν επιστρέφει ποτέ σε αυτή τη σελίδα. Δεν καλείται απολύτως τίποτα, όσο δεν έχεις αποθηκεύσει μια διεύθυνση και δεν την έχεις διαλέξει σε ένα συρτάρι κάτω από τις Κατηγορίες. Μια λήψη χωρίς όνομα πακέτου δεν πυροδοτεί ποτέ κλήση, γιατί δεν υπάρχει πακέτο του οποίου θα μπορούσε να είναι το τελευταίο αρχείο. Ούτε για ένα πακέτο που ολοκληρώνεται όσο ο διακομιστής επανεκκινείται γίνεται κλήση: το πρώτο πέρασμα σημειώνει τι είναι ήδη έτοιμο και δεν το ανακοινώνει.`,"settings.mediahook.empty":`Δεν έχει αποθηκευτεί ακόμη διεύθυνση.`,"settings.mediahook.emptyHint":`Μία αξίζει, μόλις ο διακομιστής πολυμέσων σου δεν αντιλαμβάνεται μόνος του τα νέα αρχεία.`,"settings.mediahook.add":`Προσθήκη διεύθυνσης`,"settings.mediahook.name":`Όνομα`,"settings.mediahook.nameHint":`Με αυτό το όνομα διαλέγεις τη διεύθυνση σε ένα συρτάρι κάτω από τις Κατηγορίες. Μόνο γράμματα, ψηφία και - _ ή . Αργότερα δεν αλλάζει, γιατί ένα συρτάρι δείχνει σε αυτήν μέσω αυτού του ονόματος.`,"settings.mediahook.url":`Διεύθυνση`,"settings.mediahook.urlHint":`Η πλήρης διεύθυνση που καλείται, http ή https, μαζί με host και θύρα. Διάβασέ την άλλη μια φορά πριν αποθηκεύσεις: ό,τι στέκει εδώ καλείται από αυτόν τον υπολογιστή. Η ίδια η διεύθυνση αποθηκεύεται σε απλό κείμενο στο settings.json και καταλήγει έτσι και στο πακέτο διαγνωστικών. Βάλε λοιπόν ένα διακριτικό παρακάτω στην κεφαλίδα και όχι στο τμήμα ερωτήματος της διεύθυνσης.`,"settings.mediahook.method":`Μέθοδος`,"settings.mediahook.methodHint":`GET ή POST. Ένα POST στέλνεται χωρίς σώμα. Το Jellyfin θέλει POST, το Plex θέλει GET, και αν δεν είσαι σίγουρος, η δοκιμαστική κλήση σού λέει τι δέχεται η άλλη πλευρά.`,"settings.mediahook.headerName":`Όνομα κεφαλίδας`,"settings.mediahook.headerNameHint":`Η μία κεφαλίδα που στέλνεται μαζί με την κλήση, στο Jellyfin για παράδειγμα X-Emby-Token. Άφησέ το κενό και δεν στέλνεται καμία επιπλέον κεφαλίδα.`,"settings.mediahook.headerValue":`Τιμή κεφαλίδας`,"settings.mediahook.headerValueHint":`Το διακριτικό που μπαίνει σε αυτή την κεφαλίδα. Φυλάγεται κρυπτογραφημένο στον ίδιο χώρο με τα στοιχεία των λογαριασμών σου, δεν γράφεται ποτέ στο settings.json και δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα.`,"settings.mediahook.valueStored":`Αποθηκευμένη`,"settings.mediahook.valueStoredHint":`Η τιμή μένει σε αυτό το στιγμιότυπο. Άφησε το πεδίο όπως είναι για να τη διατηρήσεις, ή γράψε νέα για να την αντικαταστήσεις. Αν αδειάσεις το πεδίο, η τιμή φεύγει.`,"settings.mediahook.goesTo":`Η κλήση πηγαίνει στο {host}`,"settings.mediahook.goesToForeign":`Αυτή η διεύθυνση δεν βρίσκεται στο δικό σου δίκτυο. Η κλήση φεύγει από αυτόν τον υπολογιστή, και η κεφαλίδα φεύγει μαζί της.`,"settings.mediahook.wait":`Αναμονή πριν την κλήση`,"settings.mediahook.waitHint":`Πόση ώρα αφήνεται ήσυχη αυτή η διεύθυνση μετά από ένα ολοκληρωμένο πακέτο, ώστε από είκοσι πακέτα που τελειώνουν μαζί να βγαίνει μία κλήση αντί για είκοσι. Μια σάρωση βιβλιοθήκης κοστίζει στον διακομιστή πολυμέσων πραγματική δουλειά, και μία που έρχεται ένα λεπτό αργότερα δεν σου κοστίζει τίποτα. Στο 0 η κλήση φεύγει μόλις τα αρχεία ενός πακέτου βρεθούν στη θέση τους, χωρίς να περιμένει άλλα.`,"settings.mediahook.waitImmediate":`Η κλήση φεύγει μόλις ένα πακέτο είναι έτοιμο, χωρίς να περιμένει άλλα.`,"settings.mediahook.save":`Αποθήκευση διεύθυνσης`,"settings.mediahook.delete":`Διαγραφή διεύθυνσης`,"settings.mediahook.deleteConfirm":`Να διαγραφεί η {name}; Η αποθηκευμένη τιμή της κεφαλίδας φεύγει μαζί, και από αυτή τη σελίδα δεν επαναφέρεται.`,"settings.mediahook.deleteInUse":`Η {name} είναι ακόμη επιλεγμένη σε {n} συρτάρια. Βάλε πρώτα εκείνα στο «Καμία ειδοποίηση», μετά διάγραψέ την.`,"settings.mediahook.usedBy":`Επιλεγμένη σε {n} συρτάρια`,"settings.mediahook.usedByNone":`Αποθηκευμένη, και δεν την καλεί ακόμη τίποτα`,"settings.mediahook.test":`Αποστολή δοκιμαστικής κλήσης`,"settings.mediahook.testRunning":`Γίνεται κλήση`,"settings.mediahook.lastCall":`Τελευταία κλήση`,"settings.mediahook.lastCallHint":`Τι έγινε την τελευταία φορά που κλήθηκε αυτή η διεύθυνση, μαζί με τις δοκιμαστικές κλήσεις. Κρατιέται μόνο στη μνήμη, οπότε μια επανεκκίνηση το σβήνει χωρίς να αλλάξει τίποτα στην ίδια τη διεύθυνση.`,"settings.mediahook.lastCallNever":`Δεν έχει κληθεί από την εκκίνηση αυτού του διακομιστή`,"settings.mediahook.lastCallOk":`Απάντησε {status} μετά από {ms} ms`,"settings.mediahook.lastCallFailed":`Απέτυχε μετά από {ms} ms`,"settings.mediahook.lastCallFor":`Για το πακέτο {name}`,"settings.mediahook.lastCallTest":`Δοκιμαστική κλήση`,"settings.mediahook.lastCallCoalesced":`Για {n} πακέτα που ολοκληρώθηκαν μαζί`,"settings.mediahook.problem.dns":`Το όνομα host δεν μπόρεσε να επιλυθεί. Έλεγξε τη γραφή, και βάλε τη διεύθυνση IP, αν αυτό το στιγμιότυπο δεν φτάνει στον διακομιστή ονομάτων του δικτύου σου.`,"settings.mediahook.problem.refused":`Σε αυτή τη θύρα δεν ακούει τίποτα. Έλεγξε τη θύρα, και έλεγξε αν ο διακομιστής πολυμέσων είναι προσβάσιμος από αυτό το κοντέινερ και όχι μόνο από τον δικό σου υπολογιστή.`,"settings.mediahook.problem.timeout":`Η άλλη πλευρά δέχτηκε τη σύνδεση και δεν απάντησε μέσα σε {seconds} δευτερόλεπτα. Η διεύθυνση μάλλον είναι σωστή, ο διακομιστής είναι απασχολημένος ή έχει κολλήσει.`,"settings.mediahook.problem.tls":`Η ασφαλής σύνδεση δεν στήθηκε. Ένα αυτοϋπογεγραμμένο πιστοποιητικό είναι ο συνηθισμένος λόγος. Βάλε http και την εσωτερική διεύθυνση, αν ο διακομιστής πολυμέσων βρίσκεται στο δικό σου δίκτυο.`,"settings.mediahook.problem.auth":`Ο διακομιστής απάντησε {status}: δεν δέχτηκε την κεφαλίδα. Έλεγξε το όνομα της κεφαλίδας και επικόλλησε ξανά το διακριτικό.`,"settings.mediahook.problem.notFound":`Ο διακομιστής απάντησε 404: η διεύθυνση είναι προσβάσιμη, αυτή τη διαδρομή όμως δεν την έχει. Έλεγξε τη διαδρομή, μαζί με το αναγνωριστικό βιβλιοθήκης, αν η διεύθυνση κουβαλά κάποιο.`,"settings.mediahook.problem.method":`Ο διακομιστής απάντησε 405: δεν δέχεται {method} σε αυτή τη διαδρομή. Άλλαξε τη μέθοδο και δοκίμασε ξανά.`,"settings.mediahook.problem.redirect":`Η διεύθυνση απάντησε {status} και δείχνει κάπου αλλού. Οι ανακατευθύνσεις δεν ακολουθούνται εδώ, γιατί η κεφαλίδα θα ταξίδευε μαζί τους στη νέα διεύθυνση. Γράψε τη διεύθυνση στην οποία δείχνει.`,"settings.mediahook.problem.server":`Ο διακομιστής απάντησε {status}. Αυτό είναι σφάλμα στην άλλη πλευρά και όχι σε αυτή τη διεύθυνση. Κοίτα στο αρχείο καταγραφής του ίδιου του διακομιστή πολυμέσων.`,"settings.mediahook.problem.proxy":`Η κλήση πέρασε από τον διαμεσολαβητή του HTTP_PROXY και δεν έφτασε. Βάλε τον host του διακομιστή πολυμέσων στο NO_PROXY και δοκίμασε ξανά.`,"settings.mediahook.problem.unknown":`Η κλήση δεν πέτυχε: {error}`,"settings.categories.notify":`Ειδοποίηση της βιβλιοθήκης πολυμέσων`,"settings.categories.notifyHint":`Ποια αποθηκευμένη διεύθυνση καλείται, μόλις ένα πακέτο που μπήκε σε αυτό το συρτάρι ολοκληρωθεί και τα αρχεία του βρεθούν στη θέση τους. Ένα πακέτο του οποίου οι σύνδεσμοι βρίσκονται σε δύο συρτάρια καλεί και τα δύο, μία φορά το καθένα. Στο «Καμία ειδοποίηση» αυτό το συρτάρι μένει σιωπηλό, και αυτό ακριβώς κάνει κάθε συρτάρι όσο δεν αλλάζεις κάτι.`,"settings.categories.notifyNone":`Καμία ειδοποίηση`,"settings.categories.notifyEmpty":`Δεν έχει αποθηκευτεί ακόμη διεύθυνση. Πρόσθεσε μία στη σελίδα Λήψεις.`,"settings.categories.notifyMissing":`{id} (διαγράφηκε)`,"settings.nav.eventtargets":`Προορισμοί συμβάντων`,"settings.module.eventtargets":`Προορισμοί συμβάντων`,"settings.eventTargets.title":`Προορισμοί συμβάντων`,"settings.eventTargets.titleHint":`Πού αναφέρει αυτό το στιγμιότυπο, όταν συμβαίνει κάτι: μια δική σου διεύθυνση, με μέθοδο, κεφαλίδες και σώμα που ορίζεις εσύ. Τίποτα δεν είναι προσυμπληρωμένο και τίποτα δεν είναι αναμμένο, μέχρι να το κάνεις εσύ, και μια αναφορά πηγαίνει μόνο στη διεύθυνση που στέκει στη γραμμή. Προσφέρονται τα ίδια συμβάντα στα οποία αντιδρά και ο επεξεργαστής σεναρίων.`,"settings.eventTargets.add":`Προσθήκη προορισμού`,"settings.eventTargets.empty":`Δεν υπάρχουν ακόμη προορισμοί.`,"settings.eventTargets.emptyHint":`Χωρίς προορισμό καμία αναφορά δεν φεύγει από αυτό το μηχάνημα. Πρόσθεσε έναν για να μαθαίνεις για ένα ολοκληρωμένο πακέτο, μια αποτυχημένη λήψη ή ένα captcha που περιμένει.`,"settings.eventTargets.remove":`Αφαίρεση`,"settings.eventTargets.name":`Όνομα`,"settings.eventTargets.nameHint":`Πώς λέγεται αυτός ο προορισμός στη λίστα, στην κατάσταση από κάτω και στην καταγραφή. Το όνομα δεν στέλνεται πουθενά, χρησιμοποίησέ το λοιπόν για να ξεχωρίζεις το κινητό σου από το δωμάτιο συνομιλίας σου.`,"settings.eventTargets.enabled":`Αποστολή σε αυτόν τον προορισμό`,"settings.eventTargets.enabledHint":`Είναι σβηστό μέχρι να το ανάψεις, και αυτό ισχύει για κάθε προορισμό που προσθέτεις. Όσο είναι σβηστό, η γραμμή κρατά όλα όσα πληκτρολόγησες και δεν στέλνει τίποτα. Έτσι μπορείς να χτίσεις έναν προορισμό με την ησυχία σου και να τον δοκιμάσεις, πριν ακούσει κανείς κάτι από αυτόν.`,"settings.eventTargets.url":`Διεύθυνση`,"settings.eventTargets.urlHint":`Η πλήρης διεύθυνση στην οποία πηγαίνει μια αναφορά, μόνο http ή https. Αυτός είναι ένας διακομιστής που ονομάζεις εσύ, όχι κάποιος που διαλέγει το KnightLoader, και όλα όσα υπάρχουν στο σώμα παρακάτω καταλήγουν εκεί. Ο host στέκει στη διπλωμένη γραμμή, ώστε να βλέπεις με μια ματιά πού αναφέρει ένας προορισμός. Οι μεταβλητές δουλεύουν και εδώ και κωδικοποιούνται για διεύθυνση. Αν η διεύθυνση ανακατευθύνει σε άλλον host, η κεφαλίδα Authorization πέφτει στον δρόμο, κάτι που συνήθως γυρίζει πίσω ως 401.`,"settings.eventTargets.method":`Μέθοδος`,"settings.eventTargets.methodHint":`GET, POST ή PUT. Το POST είναι αυτό που θέλουν και το ntfy και το Gotify και το Matrix. Το GET δεν στέλνει σώμα, οπότε το πρότυπο σώματος παρακάτω μένει τότε εκτός.`,"settings.eventTargets.headers":`Κεφαλίδες`,"settings.eventTargets.headersHint":`Μία κεφαλίδα ανά γραμμή, γραμμένη ως Όνομα: τιμή, όπως γράφονται και παντού αλλού. Εδώ μπαίνει ένα διακριτικό: Authorization: Bearer … για το Matrix, X-Title ή Priority για το ntfy. Μια τιμή αποθηκεύεται όπως ο κωδικός του δρομολογητή, στο settings.json σε αυτό το μηχάνημα, και δεν επιστρέφει ποτέ σε περιηγητή: εκεί βλέπεις οκτώ αστεράκια. Αν αλλάξεις τη διεύθυνση, η αποθηκευμένη τιμή απορρίπτεται αντί να μεταφερθεί στη νέα.`,"settings.eventTargets.body":`Πρότυπο σώματος`,"settings.eventTargets.bodyHint":`Τι στέλνεται, με μεταβλητές που συμπληρώνονται τη στιγμή που συμβαίνει το συμβάν. Άφησέ το κενό, τότε φεύγουν μόνο οι κεφαλίδες. Οι τιμές περνούν από διαφυγή χαρακτήρων ανάλογα με τον τύπο περιεχομένου που όρισες στις κεφαλίδες, σε ένα σώμα JSON λοιπόν ένα όνομα αρχείου με εισαγωγικό μέσα του περνά από διαφυγή αντί να σπάσει το έγγραφο. Ακριβώς σε αυτό αποτυγχάνουν αλλιώς αυτά τα αιτήματα στις τρεις τα ξημερώματα.`,"settings.eventTargets.events":`Συμβάντα`,"settings.eventTargets.eventsHint":`Ποια συμβάντα πηγαίνουν σε αυτόν τον προορισμό. Στην αρχή δεν είναι τσεκαρισμένο τίποτα. Τρία από αυτά δηλώνονται ξανά μετά από μια επανεκκίνηση, γιατί ό,τι θυμούνται βρίσκεται στη μνήμη και όχι στον δίσκο: η ουρά δηλώνεται ως άδεια, κάθε captcha που περιμένει ακόμη δηλώνεται άλλη μία φορά, και κάθε λογαριασμός που έχει ήδη λήξει δηλώνεται άλλη μία φορά. Ένα ολοκληρωμένο πακέτο όχι, γιατί το πρώτο πέρασμα μετά την εκκίνηση σημειώνει μόνο την κατάσταση και δεν λέει τίποτα.`,"settings.eventTargets.eventsNone":`Δεν είναι τσεκαρισμένο τίποτα, αυτός ο προορισμός λοιπόν δεν στέλνει ποτέ τίποτα.`,"settings.eventTargets.eventsBurst":`Ένας σύνδεσμος που προστίθεται πυροδοτεί μία φορά ανά σύνδεσμο, διακόσιοι επικολλημένοι σύνδεσμοι είναι λοιπόν διακόσιες αναφορές. Ό,τι δεν χωράει στην ουρά απορρίπτεται και μετριέται παρακάτω, αντί να στοιβάζεται.`,"settings.eventTargets.eventsReplay":`Τουλάχιστον ένα από τα τσεκαρισμένα συμβάντα δηλώνεται ξανά μετά από κάθε επανεκκίνηση, γιατί ό,τι θυμάται βρίσκεται στη μνήμη και όχι στον δίσκο.`,"settings.eventTargets.attempts":`Προσπάθειες παράδοσης`,"settings.eventTargets.attemptsHint":`Πόσες φορές δοκιμάζεται μία αναφορά πριν εγκαταλειφθεί. Το 0 σημαίνει ότι δεν λες τίποτα γι’ αυτό, τότε ισχύουν οι συνηθισμένες τρεις· ποιος αριθμός ισχύει αυτή τη στιγμή στέκει δίπλα στο πλαίσιο. Ανάμεσα σε 1 και 5. Μια άρνηση από την άλλη πλευρά, ένα λάθος διακριτικό ή μια διαδρομή που δεν υπάρχει, δεν επαναλαμβάνεται καθόλου, γιατί μια δεύτερη προσπάθεια δεν το αλλάζει αυτό, και ο λόγος στέκει στην κατάσταση από κάτω. Όσο μια αναφορά περιμένει, τίποτα δεν καταλήγει στον δίσκο. Ένας προορισμός που έλειπε όλη τη νύχτα δεν έχει λοιπόν τίποτα να αναπληρώσει όταν επιστρέψει.`,"settings.eventTargets.attemptsDefault":`Το 0 σημαίνει τρεις`,"settings.eventTargets.timeout":`Χρονικό όριο (δευτερόλεπτα)`,"settings.eventTargets.timeoutHint":`Πόση ώρα επιτρέπεται να πάρει μία προσπάθεια. Το 0 σημαίνει ότι δεν λες τίποτα γι’ αυτό, τότε ισχύουν δεκαπέντε δευτερόλεπτα. Ανάμεσα σε 1 και 60. Ένας διακομιστής push που απαντά αργά κρατά αυτόν τον προορισμό τόση ώρα δεσμευμένο, και ό,τι περιμένει πίσω του περιμένει μαζί.`,"settings.eventTargets.placeholders":`Μεταβλητές`,"settings.eventTargets.placeholdersHint":`Τα ονόματα που μπορείς να γράψεις στη διεύθυνση, σε μια κεφαλίδα ή στο σώμα, το καθένα με δύο σύμβολα τοις εκατό γύρω από το όνομα. Έρχονται από τον διακομιστή, αυτή η λίστα είναι λοιπόν ό,τι πραγματικά συμπληρώνει αυτό το build. Ένα όνομα που δεν το γνωρίζει αυτό το build το αφήνει όπως το πληκτρολόγησες, ώστε ένα τυπογραφικό λάθος να φαίνεται στην αναφορά αντί να εξαφανίζεται σιωπηλά. Ένα όνομα που το γνωρίζει, αλλά που αυτό το συμβάν δεν το κουβαλά, μένει κενό.`,"settings.eventTargets.placeholderUnused":`Κανένα από τα συμβάντα που τσεκάρισες παραπάνω δεν κουβαλά {name}, σε κάθε αναφορά αυτού του προορισμού η μεταβλητή μένει λοιπόν κενή.`,"settings.eventTargets.leavesTheBox":`Κάθε αναφορά αυτού του προορισμού φεύγει από αυτό το μηχάνημα και πηγαίνει στο {host}.`,"settings.eventTargets.test":`Αποστολή δοκιμής`,"settings.eventTargets.testBusy":`Γίνεται αποστολή`,"settings.eventTargets.testHint":`Αυτό στέλνει πραγματικά μία αναφορά στη διεύθυνση παραπάνω, αμέσως, με τις τιμές αυτής της γραμμής και ένα επινοημένο συμβάν. Δεν είναι δοκιμή στα ξηρά: το κινητό σου δονείται, και το δωμάτιο συνομιλίας σου το βλέπει. Η απάντηση στέκει εκεί όπως ήρθε πίσω, ώστε να μπορείς να διαβάσεις μια άρνηση αντί να τη μαντεύεις. Μια αποθηκευμένη τιμή κεφαλίδας συμπληρώνεται για το αίτημα και μετά εμφανίζεται ως οκτώ αστεράκια, γιατί αυτός ο περιηγητής δεν την είδε ποτέ.`,"settings.eventTargets.testResult":`Η απάντηση που ήρθε πίσω`,"settings.eventTargets.testSent":`Τι στάλθηκε`,"settings.eventTargets.testDuration":`Πήρε {ms} ms`,"settings.eventTargets.testTruncated":`Η απάντηση είναι μεγαλύτερη. Εδώ στέκουν μόνο οι πρώτοι {n} χαρακτήρες.`,"settings.eventTargets.testEmptyBody":`Η απάντηση δεν είχε σώμα, αυτό είναι φυσιολογικό σε έναν διακομιστή push.`,"settings.eventTargets.testNoAnswer":`Δεν ήρθε καμία απάντηση.`,"settings.eventTargets.status":`Κατάσταση`,"settings.eventTargets.statusUnknown":`Από την εκκίνηση του διακομιστή δεν έφυγε τίποτα προς αυτόν τον προορισμό. Αυτό δεν σημαίνει ότι δεν έφυγε ποτέ τίποτα.`,"settings.eventTargets.lastAttempt":`Τελευταία προσπάθεια`,"settings.eventTargets.lastOk":`Τελευταία που έφτασε`,"settings.eventTargets.lastOkNever":`Από την εκκίνηση του διακομιστή δεν έχει φτάσει τίποτα.`,"settings.eventTargets.sentCount":`{n} παραδόθηκαν από την εκκίνηση του διακομιστή`,"settings.eventTargets.dropped":`{n} απορρίφθηκαν επειδή η ουρά ήταν γεμάτη`,"settings.eventTargets.droppedHint":`Ένα κύμα που φτάνει πιο γρήγορα απ’ ό,τι το δέχεται αυτός ο προορισμός απορρίπτεται αντί να φυλαχτεί. Το να φυλαχτεί θα σήμαινε να ξοδεύεται μνήμη για αναφορές που όταν φτάσουν είναι προ πολλού παλιές. Αν αυτός ο αριθμός συνεχίζει να ανεβαίνει, ο προορισμός είναι πολύ αργός για τα συμβάντα που τσεκάρισες.`,"settings.eventTargets.problem.noUrl":`Σε αυτή τη γραμμή δεν στέκει διεύθυνση, δεν μπορεί λοιπόν να σταλεί τίποτα. Γράψε μία παραπάνω.`,"settings.eventTargets.problem.badUrl":`Η διεύθυνση δεν διαβάζεται ως διεύθυνση http ή https. Έλεγξε το σχήμα και τον host.`,"settings.eventTargets.problem.badMethod":`Αυτό το build στέλνει GET, POST και PUT και τίποτα άλλο. Πάρε ένα από τα τρία.`,"settings.eventTargets.problem.badTemplate":`Μια μεταβλητή δεν έκλεισε. Καθεμία γράφεται με δύο σύμβολα τοις εκατό και στις δύο πλευρές του ονόματος.`,"settings.eventTargets.problem.unknownTrigger":`Ένα από τα συμβάντα σε αυτή τη γραμμή δεν είναι συμβάν που πυροδοτεί αυτό το build. Βγάλ’ το και διάλεξε ένα από τη λίστα.`,"settings.eventTargets.problem.dns":`Ο host δεν μπόρεσε να επιλυθεί από αυτό το στιγμιότυπο. Ένα κοντέινερ έχει συχνά δική του υπηρεσία ονομάτων, μια διεύθυνση στην οποία φτάνει ο δικός σου υπολογιστής δεν τη φτάνει λοιπόν αυτόματα και αυτό το μηχάνημα.`,"settings.eventTargets.problem.refused":`Εκεί δεν ακούει τίποτα. Έλεγξε τη θύρα και αν η υπηρεσία τρέχει καθόλου.`,"settings.eventTargets.problem.tls":`Το πιστοποιητικό δεν έγινε δεκτό. Συνήθως φταίει ένα αυτοϋπογεγραμμένο πιστοποιητικό στον δικό σου διακομιστή. Στο δικό σου δίκτυο βάλε http, ή δώσε αυτό το πιστοποιητικό σε αυτό το κοντέινερ.`,"settings.eventTargets.problem.timeout":`Η άλλη πλευρά δεν απάντησε μέσα στο χρονικό όριο. Ανέβασε το όριο παραπάνω, ή στείλε σε κάτι πιο γρήγορο.`,"settings.eventTargets.problem.auth":`Η άλλη πλευρά απέρριψε τα διαπιστευτήρια. Έλεγξε το διακριτικό στις κεφαλίδες, και θυμήσου ότι μια ανακατεύθυνση σε άλλον host πετά την κεφαλίδα Authorization στον δρόμο.`,"settings.eventTargets.problem.notFound":`Η άλλη πλευρά δεν γνωρίζει αυτή τη διαδρομή. Στο ntfy το θέμα ανήκει στη διεύθυνση, στο Matrix το αναγνωριστικό δωματίου.`,"settings.eventTargets.problem.rejected":`Η άλλη πλευρά διάβασε το αίτημα και το απέρριψε. Η απάντηση παρακάτω είναι η δική της διατύπωση και λέει περισσότερα απ’ ό,τι θα μπορούσε μια κατάταξη εδώ.`,"settings.eventTargets.problem.rateLimited":`Η άλλη πλευρά αρνείται προς το παρόν, επειδή έφτασαν πολλά μαζί. Βγάλε τα πιο θορυβώδη συμβάντα, ή στείλε στον δικό σου διακομιστή αντί σε δημόσιο.`,"settings.eventTargets.problem.server":`Η άλλη πλευρά απάντησε με δικό της σφάλμα. Δοκιμάστηκε τόσες φορές όσες επιτρέπει αυτή η γραμμή, το επόμενο μέρος που κοιτάς είναι λοιπόν το δικό της αρχείο καταγραφής.`,"settings.scripts.trigger.linkAdded":`Ένας σύνδεσμος προστίθεται`,"settings.scripts.trigger.packageDone":`Ένα πακέτο ολοκληρώνεται`,"settings.scripts.trigger.extractDone":`Ένα συμπιεσμένο αρχείο ολοκληρώνει την αποσυμπίεση`,"settings.scripts.trigger.checksumFailed":`Ένα άθροισμα ελέγχου δεν ταιριάζει`,"settings.scripts.trigger.reconnectDone":`Μια επανασύνδεση έτρεξε`,"settings.scripts.trigger.accountExpired":`Ένας λογαριασμός έληξε`,"settings.scripts.trigger.captchaPending":`Ένα captcha περιμένει`,"settings.nav.health":`Κατάσταση`,"settings.module.metrics":`Διεύθυνση μετρήσεων για σύστημα παρακολούθησης`,"settings.health.title":`Κατάσταση αυτή τη στιγμή`,"settings.health.titleHint":`Αυτή η σελίδα μόνο διαβάζει. Τίποτα πάνω της δεν ξεκινά, δεν σταματά και δεν αλλάζει κάτι, και αν την αφήσεις ανοιχτή δεν αλλάζει ούτε αυτό κάτι. Οι τιμές ανακτώνται κάθε δέκα δευτερόλεπτα. Αν μια ανάκτηση αποτύχει, μένει η τελευταία μέτρηση αντί να αδειάσει η σελίδα. Τα μέρη που πρέπει να ρωτηθούν μοιράζονται για μισό λεπτό. Ό,τι στέκει εδώ μπορεί λοιπόν να είναι μέχρι και τριάντα δευτερόλεπτα πίσω από τις γραμμές στη σελίδα Λήψεις.`,"settings.health.version":`Έκδοση`,"settings.health.uptime":`Τρέχει εδώ και`,"settings.health.uptimeHint":`Πόση ώρα τρέχει αυτή η διεργασία, όχι πόση ώρα τρέχει το μηχάνημα. Ένα κοντέινερ που ξαναξεκίνησε πριν από μία ώρα αρχίζει εδώ πάλι από το μηδέν, ό,τι κι αν λέει ο host. Η ημερομηνία δίπλα του είναι το ρολόι του ίδιου του διακομιστή, όχι του περιηγητή σου.`,"settings.health.startedAt":`Ξεκίνησε`,"settings.health.sampled":`Διαβάστηκε πριν από {n} δευτερόλεπτο(α)`,"settings.health.loadFailed":`Δεν ήταν δυνατή η φόρτωση της κατάστασης. Είναι προσβάσιμος ο διακομιστής;`,"settings.health.oldHealthHint":`Η παλιά διεύθυνση /api/health δεν έχει αλλάξει και συνεχίζει να απαντά «ok» όσο τρέχει αυτή η διεργασία, ό,τι κι αν στέκει σε αυτή τη σελίδα. Αυτό είναι σκόπιμο: ο έλεγχος υγείας του ίδιου του κοντέινερ, η γέφυρα Click'n'Load και η αναζήτηση στιγμιότυπων της εφαρμογής κινητού τη διαβάζουν όλες, και μια απάντηση άλλη από το «ok» θα σήμαινε το κοντέινερ ως μη υγιές και θα φρόντιζε ώστε το κινητό να μη βρίσκει πια αυτό το στιγμιότυπο. Ένα σφάλμα αναφέρεται σε αυτή τη σελίδα. Εκείνη η διεύθυνση λέει μόνο αν ακούει καν κανείς.`,"health.state.ok":`Λειτουργεί`,"health.state.degraded":`Λειτουργεί, αλλά με ένα σφάλμα`,"health.state.failed":`Δεν λειτουργεί`,"health.state.unused":`Δεν είναι σε λειτουργία εδώ`,"health.state.unknown":`Δεν μπορεί να ελεγχθεί εδώ`,"settings.health.parts":`Μέρη`,"settings.health.partsHint":`Μία γραμμή για κάθε μέρος που μπορεί να αποτύχει από μόνο του. Ένα μέρος που δεν το έστησες ποτέ σε αυτό το στιγμιότυπο το λέει, αντί να μετρήσει ως σφάλμα, και ένα μέρος που αυτό το build δεν μπορεί να το ρωτήσει το λέει επίσης. Αυτή είναι μια τρίτη απάντηση και όχι ένα σιωπηλό μηδέν. Το να διαβάσεις μια γραμμή δεν αλλάζει τίποτα: ένα μέρος που δεν λειτουργεί αποτυγχάνει ήδη εδώ και ώρα, εδώ απλώς το βλέπεις.`,"health.part.store":`Βάση δεδομένων`,"health.part.queue":`Ουρά`,"health.part.disk":`Φάκελοι προορισμού`,"health.part.jd":`Βοηθητικό JDownloader`,"health.part.ytdlp":`yt-dlp`,"health.part.accounts":`Λογαριασμοί hoster`,"health.part.feeds":`Συνδρομές σε ροές`,"health.part.relay":`Αναμεταδότης`,"health.part.captcha":`Captcha`,"health.remedy.store.failed":`Η βάση δεδομένων δεν απάντησε. Οι λήψεις συνεχίζονται, αλλά γι’ αυτές δεν καταγράφεται τίποτα πια. Μια επανεκκίνηση θα έχανε λοιπόν όλα όσα άλλαξαν από τότε. Δες αν ο φάκελος δεδομένων είναι ακόμη προσαρτημένος και ακόμη εγγράψιμος.`,"health.remedy.jd.unreachable":`Το KL_JD ονομάζει μια διεύθυνση στην οποία αυτό το στιγμιότυπο δεν φτάνει αυτή τη στιγμή. Δες αν το κοντέινερ JDownloader τρέχει και αν η θύρα API του απαντά από εδώ. Οι σύνδεσμοι που μόνο το JDownloader μπορεί να φέρει μένουν στο μεταξύ στην ουρά και δεν έχουν αποτύχει.`,"health.remedy.jd.notWired":`Το JDownloader απαντά ξανά, αλλά αυτή η διεργασία καλωδίωσε τα backend της κατά την εκκίνηση και τότε δεν το είχε. Κάνε επανεκκίνηση του KnightLoader, ώστε να το παραλάβει.`,"health.remedy.ytdlp.missing":`Κατά την εκκίνηση δεν βρέθηκε κανένα yt-dlp (KL_YTDLP, ή «yt-dlp» στο PATH). Οι σελίδες πολυμέσων αποτυγχάνουν τότε με το σφάλμα της ίδιας της σελίδας, αντί να ανοίγουν σε παραλλαγές. Για να βρεθεί, χρειάζεται επανεκκίνηση.`,"health.remedy.disk.low":`Ένας φάκελος προορισμού βρίσκεται κάτω από το όριο που έβαλες στη σελίδα Λήψεις. Εκεί δεν ξεκινά τίποτα καινούριο, μέχρι να υπάρξει ξανά χώρος ή μέχρι να κατεβάσεις το όριο. Ό,τι ήδη τρέχει δεν το σταματά αυτό το όριο.`,"health.remedy.disk.elsewhere":`Ένας φάκελος δεν είναι εκεί, γι’ αυτό οι αριθμοί περιγράφουν τον πλησιέστερο φάκελο από πάνω του. Αν μια προσάρτηση δεν ανέβηκε, αυτός είναι ένας εντελώς άλλος δίσκος. Δες τη διαδρομή, πριν πιστέψεις τους αριθμούς.`,"health.remedy.accounts.benched":`Τουλάχιστον ένας λογαριασμός hoster αφήνεται ήσυχος μετά από ένα σφάλμα. Δοκιμάζεται από μόνος του άλλη μία φορά, όταν περάσει η αναμονή, και η αναμονή διπλασιάζεται κάθε φορά. Πήγαινε στους Λογαριασμούς και πάτα Ανανέωση στη γραμμή, αν θέλεις να το μάθεις τώρα.`,"health.remedy.accounts.invalid":`Τουλάχιστον ένας λογαριασμός hoster απορρίφθηκε. Ένα νέο κλειδί ή μια ανανεωμένη συνδρομή βοηθά, η αναμονή όχι.`,"health.remedy.feeds.failing":`Σε τουλάχιστον μία συνδρομή απέτυχε η τελευταία ανάκτηση. Ποια και γιατί, στέκει στη σελίδα Λήψεις δίπλα στη ροή και στις γραμμές καταγραφής στη σελίδα Διαγνωστικά.`,"health.remedy.relay.down":`Μια διεύθυνση αναμεταδότη είναι αποθηκευμένη και η σύνδεση δεν στέκει. Αυτό το στιγμιότυπο ξαναπροσπαθεί από μόνο του, και τοπικά όλα λειτουργούν ως συνήθως. Μόνο από έξω δεν είναι αυτή τη στιγμή προσβάσιμο.`,"health.remedy.captcha.waiting":`Ένα backend σταμάτησε και ρωτά έναν άνθρωπο. Πίσω του δεν κινείται τίποτα, μέχρι να απαντήσει κάποιος.`,"settings.health.tasks":`Λήψεις αυτή τη στιγμή`,"settings.health.tasksHint":`Μια στιγμιαία εικόνα της λίστας όπως είναι, όχι ένα μετρητικό στον χρόνο. Το «Απέτυχαν» μετρά τις γραμμές που στέκουν αυτή τη στιγμή με ένα σφάλμα μέσα στη λίστα. Ο αριθμός πέφτει λοιπόν, όταν τις καθαρίζεις και όταν η λίστα τακτοποιείται μετά από τις μέρες που έχεις ορίσει, και ανεβαίνει ξανά, όταν κάτι νέο πάει στραβά. Τίποτα εδώ δεν είναι ρυθμός, και τίποτα εδώ δεν λέει πόσο συχνά έχει αποτύχει κάτι.`,"settings.health.running":`Σε εξέλιξη`,"settings.health.waiting":`Σε αναμονή`,"settings.health.failed":`Απέτυχαν`,"settings.health.waitingWhy":`Why they are waiting`,"settings.health.failedWhy":`What went wrong`,"settings.health.nothingWaiting":`Nothing is being held back.`,"settings.health.nothingFailed":`Nothing in the list has failed.`,"settings.health.diskLink":`Room on the target folders is on the Downloads page`,"settings.health.scrape":`Monitoring`,"settings.health.scrapeSwitch":`Answer at the metrics address`,"settings.health.scrapeHint":`Opens a second address that gives the same figures as plain text, in the format Prometheus and the tools built like it read. It is fetched, never sent: nothing leaves this machine unless your own monitoring comes here and asks for it. While this is off the address does not exist at all and answers 404, the same as any address this app does not have. On an instance with a password the fetch needs one of your API tokens, and every collector can be told to send one. A collector sends no origin header and therefore gets through; a browser tab on another address does send one and is refused when it does not match this instance's own address. The text carries your target folders' paths, so put it where you would put the folder names themselves.`,"settings.health.scrapeUrl":`Metrics address`,"settings.health.scrapeCopy":`Copy address`,"settings.health.scrapeCopied":`Address copied`,"settings.health.scrapeOffHint":`This address answers nothing while the switch above is off.`,"settings.diagnostics.systemTitle":`System information`,"settings.diagnostics.fileTitle":`Log file`,"settings.diagnostics.fileOn":`Write the log to a file`,"settings.diagnostics.fileOnHint":`Off until you switch it on, and an update never switches it on for you. With it on, this instance writes every line it logs into a file in its data folder, so a crash from two nights ago is still readable after a restart. A log line can name the address of a feed you subscribe to, so treat the file as yours. In a container the same lines already reach docker logs; the file is what stays once that has moved on.`,"settings.diagnostics.fileSize":`Size per file`,"settings.diagnostics.fileSizeHint":`Once the file reaches this, it is renamed and a new one starts.`,"settings.diagnostics.fileKeep":`Old files kept`,"settings.diagnostics.fileKeepHint":`How many renamed files stay beside the one being written. Zero keeps only the current file, which is a real answer and not a way to switch the log off.`,"settings.diagnostics.fileWhere":`Where it is written`,"settings.diagnostics.fileWhereHint":`Fixed, so a typo in a path cannot be what stops the log being written. Set KL_LOG_DIR before starting the app to put it on another disk.`,"settings.diagnostics.fileStateOff":`Not being written`,"settings.diagnostics.fileStateOn":`{size} of {max} used`,"settings.diagnostics.fileProblem":`The log file is not being written: {error}`,"settings.diagnostics.fileProblemHint":`Check that {path} exists and that the account this process runs under may write there. On Unraid that usually means the folder belongs to root while the container runs as another user. Nothing else stopped: the last {n} lines are still in memory and still go into the diagnostics bundle.`,"settings.diagnostics.fileProblemSpace":`{free} free on that volume.`,"settings.diagnostics.fileProblemSpaceUnknown":`How much room is left on that volume could not be read on this system.`,"settings.diagnostics.fileCurrent":`Current file`,"settings.diagnostics.fileOlder":`Older file {n}`,"settings.diagnostics.fileEmpty":`Nothing written yet.`,"settings.diagnostics.fileDownload":`Download`,"settings.diagnostics.logSearch":`Search the lines`,"settings.diagnostics.logSearchHint":`Plain text, no wildcards, upper and lower case treated the same. It searches the lines loaded here, not the older files. Download a file to search all of it.`,"settings.diagnostics.logSource":`Source`,"settings.diagnostics.logSourceAll":`All sources`,"settings.diagnostics.logSourceOther":`Everything else`,"settings.diagnostics.logSourceHint":`Which part of the app a line came from, read from the beginning of the line itself. A line that names no part is under "Everything else". There are no severity levels to filter by: nothing in this app records one.`,"settings.diagnostics.logFollow":`Follow new lines`,"settings.diagnostics.logFollowHint":`Asks every two seconds for what has arrived since the last time and jumps to the newest line. Switching it off leaves the view where it is, so you can read something without it sliding away.`,"settings.diagnostics.logMatches":`{shown} of {total} lines`,"settings.diagnostics.logNoMatches":`No line here contains that.`,"settings.diagnostics.logGap":`{n} lines fell out between two checks: more arrived than the {cap} lines memory holds. Switch the log file on to keep them.`,"settings.diagnostics.logTaskOnly":`Only this download`,"settings.diagnostics.logTaskClear":`Show every download again`,"settings.diagnostics.logTaskChip":`Show only the lines that name this download`,"detail.log.title":`Log for this download`,"detail.log.hint":`The lines this instance logged that name this download by its id.`,"detail.log.empty":`Nothing logged against this download.`,"detail.log.emptyHint":`Not every line records which download it belongs to, so a download can run into trouble without a single line appearing here. The whole log is on the Diagnostics page.`,"detail.log.openDiagnostics":`Open the whole log`,"detail.log.remote":`The log stays on the instance that wrote it, so there is nothing to show for a download running on another box.`,"settings.owner.identityTitle":`Who this instance writes as`,"settings.owner.identityHint":`Every file this instance creates gets this owner and these permissions, and so does everything it starts: yt-dlp, ffmpeg and the bundled JDownloader. In a container the identity is fixed the moment the container starts, by the account it was started under, and nothing on this page can change it.`,"settings.owner.uid":`User`,"settings.owner.gid":`Group`,"settings.owner.umask":`Umask`,"settings.owner.umaskUnknown":`This kernel does not report it`,"settings.owner.asked":`Asked for`,"settings.owner.envIgnored":`{name}={value} is set, but nothing in this image reads it. The identity is fixed by the account the container was started under, which is {owner}.`,"settings.owner.envHow":`To run under another account, name it in the run command: --user <uid>:<gid>. On Unraid that goes in Extra Parameters, and the container has to be recreated for it to take.`,"settings.owner.desktopNote":`The desktop app runs under your own account. PUID, PGID and UMASK are container settings and do nothing here.`,"settings.owner.noOwners":`This system has no file owners, so there is nothing to compare. That is not a fault.`,"settings.owner.checkTitle":`Folder check`,"settings.owner.checkHint":`This really writes one file and one sub-folder into each folder, reads back who owns them and who else may read them, and removes both again. It has to be measured rather than worked out: a share can carry its own permission rules, and a folder marked set-group-id hands out a different group than the one this process has. It runs on its own after you save a changed folder, and whenever you press the button.`,"settings.owner.run":`Check the folders now`,"settings.owner.running":`Checking…`,"settings.owner.never":`Not checked yet.`,"settings.owner.checkedAt":`Last checked {time}.`,"settings.owner.checkFailed":`The check could not run: {error}`,"settings.owner.role.downloads":`Download folder`,"settings.owner.role.work":`Working folder`,"settings.owner.role.category":`Category folder`,"settings.owner.role.watch":`Watched folder`,"settings.owner.v.ok":`Files land here as {fileOwner} with {fileMode}, new sub-folders with {subdirMode}, and the folder itself belongs to {dirOwner}. Nothing about that stands out.`,"settings.owner.v.ownerMismatch":`Files land here as {fileOwner}, but the folder belongs to {dirOwner}. Reading them usually still works; renaming, moving and deleting them from another account does not, and anything that expects the folder to own what is in it treats those files as foreign.`,"settings.owner.v.groupUnreadable":`Files land here with {fileMode}, so only {fileOwner} can open them. Anything running under another account sees the names and gets nothing else.`,"settings.owner.v.dirUnreadable":`New sub-folders land here with {subdirMode}. Nobody but {fileOwner} gets inside them, whatever the files in them allow, and every download lands in one.`,"settings.owner.v.notWritable":`This instance cannot write here at all: {detail}`,"settings.owner.v.missing":`The folder is not there. It will be created the first time something is written into it.`,"settings.owner.v.unknown":`This system has no file owners, so there is nothing to compare here. That is not a fault.`,"settings.owner.fix.user":`Start the container under the account the folder belongs to: --user {dirUid}:{dirGid} in the run command. On Unraid that goes in Extra Parameters.`,"settings.owner.fix.chown":`Or hand the folder over instead, on the host: chown -R {uid}:{gid} {dir}`,"settings.owner.fix.mask":`This instance cannot change that. The mask comes from whatever started the container, and a mounted share can force its own with a umask, file_mode or dir_mode option. Fix it where the folder is mounted.`,"settings.owner.fix.recreate":`A changed run command needs the container recreated. Restarting is not enough: the identity is fixed the moment it starts.`,"settings.owner.fix.past":`Files already downloaded keep the owner they were written with. Anything you change applies to what comes next; the rest needs the command above.`,"settings.selftest.title":`Self-test`,"settings.selftest.hint":`Everything this instance can find out about itself: the JDownloader sidecar, yt-dlp, your folders, your debrid logins, the relay and the clock. All of it runs on this machine. The only thing that leaves it is the debrid logins, which go to the providers you set up.`,"settings.selftest.run":`Run self-test`,"settings.selftest.running":`Checking…`,"settings.selftest.pending":`Waiting`,"settings.selftest.never":`Not run yet.`,"settings.selftest.lastRun":`Last run {when}.`,"settings.selftest.startFailed":`The self-test could not be started: {error}`,"settings.selftest.status.pass":`Fine`,"settings.selftest.status.warn":`Worth a look`,"settings.selftest.status.fail":`Broken`,"settings.selftest.status.skipped":`Not set up`,"settings.selftest.status.unknown":`Cannot tell`,"settings.selftest.jd":`JDownloader sidecar`,"settings.selftest.jd.ok":`Reachable, revision {version}.`,"settings.selftest.jd.provisioningOff":`Provisioning is switched off and no address is set, so there is no sidecar to reach.`,"settings.selftest.jd.missing":`No sidecar address. Encrypted DLC and container links are refused.`,"settings.selftest.jd.missingAdvice":`This build normally starts its own headless JDownloader while booting and fills KL_JD in itself. That it is empty means that start failed. Look for "JD provisioning failed" in the log further down, or set KL_JD to a JDownloader of your own.`,"settings.selftest.jd.unreachable":`{address} did not answer.`,"settings.selftest.jd.unreachableAdvice":`The address is stored and nothing is listening on it. Check that the sidecar is running, and that its port 3128 is reachable from inside this container, not just from the host.`,"settings.selftest.jd.noVersion":`Answers, but will not say which revision it is.`,"settings.selftest.ytdlp":`yt-dlp`,"settings.selftest.ytdlp.ok":`{version}, {days} days old.`,"settings.selftest.ytdlp.aging":`{version} is {days} days old.`,"settings.selftest.ytdlp.old":`{version} is {days} days old. The big video sites usually break it within weeks.`,"settings.selftest.ytdlp.oldAdvice":`In the container, yt-dlp comes from the Alpine package that was current when the image was built, and it never updates itself. Pull a newer image, or mount a yt-dlp of your own into the container and point KL_YTDLP at it.`,"settings.selftest.ytdlp.missing":`Not found, so media pages fail with the hoster's own error instead.`,"settings.selftest.ytdlp.missingAdvice":`Point KL_YTDLP at the binary, or put yt-dlp on PATH. It is looked for once while starting up, so one installed now is only used after a restart.`,"settings.selftest.ytdlp.undated":`{version} does not look like a date, so its age cannot be judged.`,"settings.selftest.folders":`Download and working folder`,"settings.selftest.folders.allOk":`Every folder that was checked is there and can be written to.`,"settings.selftest.folders.someBad":`At least one folder has something worth looking at.`,"settings.selftest.folders.none":`No folder could be measured at all.`,"settings.selftest.folders.ok":`{dir} can be written to, {free} free.`,"settings.selftest.folders.notWritable":`{dir} cannot be written to.`,"settings.selftest.folders.notWritableAdvice":`This process runs as uid {uid}. Check who owns that folder on the host and whether that uid may write in it.`,"settings.selftest.folders.missing":`{dir} is not there yet, so the figures describe {measured} instead.`,"settings.selftest.folders.missingAdvice":`That is normal for a folder nothing has written into yet, and the first download creates it. But if {measured} is the root of the volume, the mount you expected is missing, and the download lands inside the container instead of on your disk.`,"settings.selftest.folders.low":`Only {free} left on {dir}, below the {mark} at which the queue stops.`,"settings.selftest.folders.noMark":`{free} free on {dir}. You have set no fixed threshold, so the queue only holds a download back when it would not fit as it is.`,"settings.selftest.folders.unknown":`This platform cannot be asked how much room is on {dir}.`,"settings.selftest.accounts":`Debrid logins`,"settings.selftest.accounts.none":`No debrid account is set up, so there was nothing to check.`,"settings.selftest.accounts.allOk":`All {n} logins were accepted.`,"settings.selftest.accounts.someFailed":`{bad} of {n} logins were refused.`,"settings.selftest.accounts.rowOk":`{label}: accepted, {hosts} hosters.`,"settings.selftest.accounts.rowFailed":`{label}: refused.`,"settings.selftest.accounts.rowGone":`{label}: the key was removed while the check was running.`,"settings.selftest.accounts.rowUnknownService":`{label}: this build does not know that service.`,"settings.selftest.accounts.advice.invalid":`The provider says this key is wrong or has been withdrawn. Only a new key helps.`,"settings.selftest.accounts.advice.expired":`The key is fine, the subscription is not. Renew it at the provider.`,"settings.selftest.accounts.advice.temp":`Could be a rate limit, an outage at the provider or your own line. It is retried on its own.`,"settings.selftest.accounts.advice.error":`The provider names something neither a new key nor waiting will clear, a block on your address for instance.`,"settings.selftest.accounts.readOnlyHint":`This check changes nothing about routing. A login that fails here is reported, not set aside: a self-test run while your line is down must not stop every account for the next quarter of an hour.`,"settings.selftest.relay":`Relay`,"settings.selftest.relay.off":`You have switched the relay off, so nothing was dialled.`,"settings.selftest.relay.notSetUp":`Remote access has never been set up here, so no relay is dialled.`,"settings.selftest.relay.ownNoAddress":`Your own relay is selected and no address is set, so nothing is dialled.`,"settings.selftest.relay.badSecret":`The stored connection secret cannot be read. Enter the connection phrase again.`,"settings.selftest.relay.connected":`Connected to {address}.`,"settings.selftest.relay.notConnected":`{address} is stored and the connection is not up.`,"settings.selftest.relay.notConnectedAdvice":`Either the relay cannot be reached right now, or it refused the key. It keeps trying on its own. If it never comes up, check the address and enter the connection phrase again.`,"settings.selftest.clock":`Clock and time zone`,"settings.selftest.clock.ok":`This machine says {time}, zone {zone}.`,"settings.selftest.clock.skew":`This machine and your browser are {skew} apart.`,"settings.selftest.clock.skewAdvice":`One of the two is wrong and this app cannot say which. A clock this far out makes TLS certificates look invalid and gets debrid tokens rejected. Check the host's clock first, the container takes its time from there.`,"settings.selftest.clock.utc":`The time zone is UTC, and you have a timetable set.`,"settings.selftest.clock.utcAdvice":`The timetable runs on this machine's local time, and with no TZ set that is UTC. A window you put at 22:00 then starts at 22:00 UTC, which in Berlin is 23:00 in winter and midnight in summer. Start the container with TZ, TZ=Europe/Berlin for example, and restart it.`,"settings.selftest.clock.noZoneDB":`TZ names {zone} and the zone database could not be read, so every time in this process falls back to UTC.`,"settings.selftest.torrentPort":`Torrent port`,"settings.selftest.torrentPort.noPort":`The torrent engine picks its own port and this build cannot read back which one it took.`,"settings.selftest.torrentPort.noPortAdvice":`Set a fixed port on the Torrents page. Without one there is nothing to forward and nothing to check, and peers behind another router reach you only when they connect first.`,"settings.selftest.torrentPort.notChecked":`Port {port} is set. Nothing outside this network was asked, so whether it is open from outside is not known.`,"settings.selftest.torrentPort.notCheckedAdvice":`Only a machine outside your own network can answer that, and this app contacts none you did not pick yourself. The UPnP button on the Torrents page asks your router to forward the port and says honestly whether it could confirm it. One more thing worth knowing: a port saved after this run's first torrent only takes effect after a restart.`,"settings.selftest.proxy.title":`Reverse proxy`,"settings.selftest.proxy.hint":`What your browser and this instance each say about the very same request. These four are the ones that go wrong behind Nginx Proxy Manager and Traefik, and three of the four fail without any error at all.`,"settings.selftest.proxy.desktopSkip":`The desktop version serves its own interface and has no proxy in front of it, so there is nothing here to compare.`,"settings.selftest.proxy.host":`Host header`,"settings.selftest.proxy.host.ok":`Your browser and this instance agree that the host is {host}.`,"settings.selftest.proxy.host.rewritten":`Your browser asked for {browser}, this instance was told {server}.`,"settings.selftest.proxy.host.rewrittenAdvice":`Your proxy is replacing the Host header. This instance compares your browser's Origin against Host, so every write is refused with 403 and the live view never opens, while the page itself still loads and looks fine. In Traefik leave passHostHeader on. In nginx use proxy_set_header Host $host.`,"settings.selftest.proxy.proto":`Forwarded protocol`,"settings.selftest.proxy.proto.ok":`The proxy says https, which is what your browser is on.`,"settings.selftest.proxy.proto.direct":`You reached this instance directly, so there is no proxy that would have to declare anything.`,"settings.selftest.proxy.proto.missing":`Your browser is on https and the proxy did not pass that on.`,"settings.selftest.proxy.proto.missingAdvice":`Without X-Forwarded-Proto this instance believes it was reached over plain http. The QR code and the pairing addresses on the Access page then offer http:// links, and a container handed to JDownloader is fetched over http. In nginx use proxy_set_header X-Forwarded-Proto $scheme; Traefik and Caddy set it themselves.`,"settings.selftest.proxy.prefix":`Path prefix`,"settings.selftest.proxy.prefix.ok":`This instance is served at the root of {host}, which is the only place it works.`,"settings.selftest.proxy.prefix.underPath":`This instance is served under {path}.`,"settings.selftest.proxy.prefix.underPathAdvice":`It builds every file and every call it makes from the root, so a folder cannot work: the page may load and then ask for /api/, which your proxy hands to whatever else lives there. Give it a name of its own, kl.example.com rather than example.com/kl.`,"settings.selftest.proxy.ws":`WebSocket upgrade`,"settings.selftest.proxy.ws.ok":`The live connection opened.`,"settings.selftest.proxy.ws.failed":`The live connection did not open.`,"settings.selftest.proxy.ws.failedAdvice":`This is the most common thing to be wrong behind a proxy, and nothing else shows it to you: the app quietly reconnects for ever, the list simply stops moving, and only reloading the page shows anything new. In nginx the location needs proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade and proxy_set_header Connection "upgrade". Nginx Proxy Manager has a Websockets Support switch on the host. Traefik and Caddy need nothing.`,"settings.diagnostics.startupTitle":`Start report`,"settings.diagnostics.startupHint":`What this instance checked once when it started: the programs it calls out to, every folder a download can land in, and the clock a schedule is read against. It is a reading and not a gate, so nothing here holds a download back or stops the server coming up. The start only looks; the write test happens when you press Check again.`,"settings.diagnostics.startupTakenAt":`Checked at {when}, just after this instance started.`,"settings.diagnostics.startupJustChecked":`Checked just now. The bundle you download still carries the reading taken at start, because that is the one a bug report needs.`,"settings.diagnostics.startupRunning":`Still checking. A folder on a share that has stopped answering takes as long as that share takes to give up.`,"settings.diagnostics.startupOff":`The check is switched off for this instance (KL_STARTUP_CHECK=0). Nothing was looked at, which is not the same as nothing being wrong.`,"settings.diagnostics.startupNotRun":`This build never ran the check. It runs in the server and in the desktop app.`,"settings.diagnostics.startupStatOnly":`The start only looked: nothing was written into any folder. A folder marked fine is therefore a folder that is there, not one this instance has written in.`,"settings.diagnostics.startupNothingWrong":`Nothing here needs doing.`,"settings.diagnostics.startupRecheck":`Check again`,"settings.diagnostics.startupRechecking":`Checking…`,"settings.diagnostics.startupRecheckHint":`Runs the same checks now and this time writes a small test file into every folder that is there, then deletes it again. That is not done at start, because writing into a folder on an array wakes the disk it sits on and it would happen at every restart. The bundle you download keeps the reading taken at start, because that is the one a bug report needs.`,"settings.diagnostics.startupRecheckFailed":`Could not check again: {error}`,"settings.diagnostics.startupNearest":`nearest existing folder: {measured}`,"settings.diagnostics.verdict.ok":`Fine`,"settings.diagnostics.verdict.warn":`Worth a look`,"settings.diagnostics.verdict.fail":`Not usable`,"settings.diagnostics.verdict.skipped":`Not needed here`,"settings.diagnostics.check.data":`Data directory`,"settings.diagnostics.check.java":`Java`,"settings.diagnostics.check.ytdlp":`yt-dlp`,"settings.diagnostics.check.ffmpeg":`ffmpeg`,"settings.diagnostics.check.ffprobe":`ffprobe`,"settings.diagnostics.check.clock":`Time zone and local time`,"settings.diagnostics.role.downloads":`Download folder`,"settings.diagnostics.role.work":`Working folder`,"settings.diagnostics.role.category":`Category folder`,"settings.diagnostics.role.extract":`Extraction folder`,"settings.diagnostics.role.extractMove":`Folder the extraction is moved to`,"settings.diagnostics.role.watch":`Watched folder`,"settings.diagnostics.fix.missing":`The folder is not there. The nearest one above it that does exist is {measured}. On a box that mounts a share this usually means the share is not mounted, and nothing here created the folder on purpose: a folder made underneath a missing mount takes the downloads instead, and they are gone with the next container update.`,"settings.diagnostics.fix.denied":`The folder is there and this instance may not write in it. In the container KnightLoader runs as uid 1000, so the folder has to belong to that user or to a group it is in.`,"settings.diagnostics.fix.readonly":`The filesystem under this folder is mounted read-only. Nothing this instance does changes that; the mount has to change.`,"settings.diagnostics.fix.full":`There is no room left on the volume this folder sits on.`,"settings.diagnostics.fix.notRemoved":`The test file could be written and not deleted again. A download would arrive here and then never be renamed or moved out of the way. Look at the delete permission on the folder, not at the write permission.`,"settings.diagnostics.fix.notADir":`There is a file at this path, not a folder.`,"settings.diagnostics.fix.timeout":`The folder did not answer in time and was left alone. A share whose server is off behaves exactly like this, and so does one on a network that has gone away.`,"settings.diagnostics.fix.dataDenied":`This is the one folder the instance cannot do without: the database, the settings and the encrypted account store all live here. Downloads keep running for now, and the next thing you save is lost.`,"settings.diagnostics.fix.javaMissing":`No Java was found. The container image ships one; a desktop install uses the bundled runtime or one on PATH. Without it the private JDownloader does not start, so an encrypted container link (.dlc, .ccf, .rsdf) cannot be opened at all. Set JAVA_HOME, or point KL_JD at a JDownloader running somewhere else.`,"settings.diagnostics.fix.javaNotNeeded":`This instance starts no Java process of its own: either KL_JD points at a JDownloader running somewhere else, or the private one is switched off with KL_PROVISION_JD=0.`,"settings.diagnostics.fix.ytdlpMissing":`yt-dlp was not found (KL_YTDLP, or “yt-dlp” on PATH). Media pages then fail with the site’s own error instead of being downloaded.`,"settings.diagnostics.fix.ffmpegMissing":`ffmpeg was not found. yt-dlp needs it to join the separate picture and sound streams most sites hand out, so a download stops at one of the two or comes back without sound.`,"settings.diagnostics.fix.ffprobeMissing":`ffprobe was not found. Only the length check on a finished video uses it; everything else works without.`,"settings.diagnostics.fix.notRunnable":`Found at {subject} and it did not run: {error}`,"settings.diagnostics.fix.appearedLate":`It runs now, and it was not there when this instance started, so nothing is being routed to it yet. Restart to pick it up.`,"settings.diagnostics.fix.utcFallback":`TZ is set to {subject} and this instance could not load that zone, so it fell back to UTC without saying so anywhere. Every schedule window runs on UTC until this is fixed. Check the spelling against the zone list (“Europe/Berlin”), and that the image has a zone database at all.`,"settings.diagnostics.fix.noZoneDatabase":`This system has no zone database, so times are read with no daylight saving changes at all. A nightly window keeps its winter hour right through the summer, and nothing says so when it happens.`,"settings.diagnostics.fix.tzUnset":`TZ is not set and no local time was found, so this instance runs on UTC. That works, and it is worth knowing: a schedule window written as 23:00 means 23:00 UTC, not 23:00 where you are.`,"settings.resolvers.toolsTitle":`Tools`,"settings.resolvers.toolsHint":`yt-dlp reads the media page, ffmpeg joins the streams it hands back. Both are separate programs KnightLoader starts and neither is part of this build, so their versions are worth knowing: an out of date yt-dlp is the most common reason a media link that worked last month stops working.`,"settings.resolvers.toolsInUse":`In use`,"settings.resolvers.toolsNotFound":`Not found`,"settings.resolvers.toolsFrom.managed":`KnightLoader's own copy`,"settings.resolvers.toolsFrom.env":`KL_YTDLP`,"settings.resolvers.toolsFrom.path":`Found on PATH`,"settings.resolvers.toolsFrom.none":`Nowhere`,"settings.resolvers.toolsYtdlpMissingHint":`Without yt-dlp there is no media backend at all: a link to a video page is refused with the site's own error instead of being downloaded. In the container it comes from the image's yt-dlp package; on the desktop you install it yourself and either put it on PATH or point KL_YTDLP at it. The button below fetches a copy on its own if neither is an option.`,"settings.resolvers.toolsFfmpegMissingHint":`Without ffmpeg, yt-dlp cannot join the separate picture and sound tracks that most sites hand out, so a download either lands as a silent video track or fails outright. Without ffprobe, "Check the finished file" further up this page measures nothing and says nothing about it. In the container both come from the ffmpeg package the image installs; on the desktop you install them yourself and put them on PATH.`,"settings.resolvers.toolsShadowed":`KnightLoader's own copy is running. KL_YTDLP and PATH are not being started while it is there: {path} would be used instead, and it reports {version}.`,"settings.resolvers.toolsShadowedOlder":`Careful: the copy KnightLoader fetched ({current}) is older than the one already on this machine ({system}, at {path}). A container update brings a newer yt-dlp with it, and your own copy does not move with it. Fetch a new one, or go back to the system copy.`,"settings.resolvers.toolsManagedBroken":`A fetched copy is recorded at {path} and it does not start. What is running instead is the fallback shown above. Fetch it again, or go back to the system copy.`,"settings.resolvers.toolsActions":`Keeping yt-dlp current`,"settings.resolvers.toolsActionsHint":`Fetching downloads yt-dlp from github.com, checks it against the SHA2-256SUMS file published in the same release, starts it once to see that it runs on this machine at all, and only then puts it next to your data, where KnightLoader starts it from. Until that last step the copy you already had keeps working, and your system's own yt-dlp is never touched.`,"settings.resolvers.toolsCheck":`Ask GitHub`,"settings.resolvers.toolsChecking":`Asking GitHub…`,"settings.resolvers.toolsFetch":`Fetch this release`,"settings.resolvers.toolsFetching":`Fetching and checking…`,"settings.resolvers.toolsRevert":`Back to the system copy`,"settings.resolvers.toolsReverting":`Removing…`,"settings.resolvers.toolsSame":`{version} is installed, and it is the newest published release.`,"settings.resolvers.toolsNewer":`{latest} is published, {current} is installed.`,"settings.resolvers.toolsOlder":`{current} is installed and is newer than the newest published release ({latest}). Nothing to do.`,"settings.resolvers.toolsUnknown":`{latest} is published, {current} is installed. Which of the two is newer cannot be read off the two version strings, so nothing is claimed here.`,"settings.resolvers.toolsCheckFailed":`GitHub could not be asked: {error}`,"settings.resolvers.toolsFetched":`{version} is in place and running.`,"settings.resolvers.toolsFetchFailed":`Nothing was replaced. {error}`,"settings.resolvers.toolsReverted":`The fetched copy is gone. {path} is running again.`,"settings.resolvers.toolsAutoCheck":`Ask GitHub for the yt-dlp version when this page opens`,"settings.resolvers.toolsAutoCheckHint":`One request to api.github.com each time this page loads, and nothing beyond it: nothing is downloaded and nothing is replaced without you pressing the button. Off by default, because a machine you run yourself should not call out on its own until you have said it may.`,"settings.diagnostics.toolsMissing":`not found`};export{e as el};